export default "  from lfx.services.model_provider_policy import ModelProviderPolicyError, ModelProviderPolicyPurpose\\n\\n        component = KnowledgeComponent(_user_id=self.USER_ID)\\n        denial = ModelProviderPolicyError(\\\"openai\\\", ModelProviderPolicyPurpose.CONFIGURE)\\n        snapshot = SimpleNamespace(require=Mock(side_effect=denial))\\n        resolve_policy = AsyncMock(return_value=snapshot)\\n        metadata_lookup = AsyncMock(side_effect=AssertionError(\\\"stored KB metadata read for create dialog\\\"))\\n        monkeypatch.setattr(\\\"lfx.services.model_provider_policy.aresolve_model_provider_policy\\\", resolve_policy)\\n        monkeypatch.setattr(component, \\\"_get_kb_metadata\\\", metadata_lookup)\\n\\n        parameters = {\\n            \\\"knowledge_base\\\": {\\n                \\\"01_new_kb_name\\\": \\\"support_docs\\\",\\n                \\\"02_embedding_model\\\": [{\\\"name\\\": \\\"text-embedding-3-small\\\", \\\"provider\\\": \\\"OpenAI\\\"}],\\n            }\\n        }\\n        with pytest.raises(ModelProviderPolicyError):\\n            await component.arequire_model_provider_policy(\\n                ModelProviderPolicyPurpose.CONFIGURE,\\n                user_id=\\\"policy-actor\\\",\\n                parameters=parameters,\\n            )\\n\\n        resolve_policy.assert_awaited_once_with(\\n            user_id=\\\"policy-actor\\\",\\n            providers=[\\\"openai\\\"],\\n            purpose=ModelProviderPolicyPurpose.CONFIGURE,\\n        )\\n        metadata_lookup.assert_not_awaited()\\n\\n    @pytest.mark.parametrize(\\\"mode\\\", [MODE_INGEST, MODE_RETRIEVE])\\n    async def test_saved_kb_provider_uses_owner_metadata_and_explicit_policy_actor(self, monkeypatch, mode) -> None:\\n        from lfx.services.model_provider_policy import ModelProviderPolicyPurpose\\n\\n        component = KnowledgeComponent(knowledge_base=\\\"support_docs\\\", mode=mode, _user_id=self.USER_ID)\\n        snapshot = SimpleNamespace(require=Mock())\\n        resolve_policy = AsyncMock(return_value=snapshot)\\n        metadata_lookup = AsyncMock(\\n            return_value={\\n                \\\"model_selection\\\": {\\\"name\\\": \\\"text-embedding-3-small\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n                \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n            }\\n        )\\n        monkeypatch.setattr(\\\"lfx.services.model_provider_policy.aresolve_model_provider_policy\\\", resolve_policy)\\n        monkeypatch.setattr(component, \\\"_get_kb_metadata\\\", metadata_lookup)\\n\\n        await component.arequire_model_provider_policy(\\n            ModelProviderPolicyPurpose.USE,\\n            user_id=\\\"policy-actor\\\",\\n            parameters={\\\"knowledge_base\\\": \\\"support_docs\\\", \\\"mode\\\": mode},\\n        )\\n\\n        metadata_lookup.assert_awaited_once_with(\\\"support_docs\\\")\\n        resolve_policy.assert_awaited_once_with(\\n            user_id=\\\"policy-actor\\\",\\n            providers=[\\\"openai\\\"],\\n            purpose=ModelProviderPolicyPurpose.USE,\\n        )\\n        snapshot.require.assert_called_once_with(\\\"openai\\\")\\n\\n    async def test_saved_kb_with_unresolvable_provider_fails_closed(self, monkeypatch) -> None:\\n        from lfx.services.model_provider_policy import ModelProviderPolicyError, ModelProviderPolicyPurpose\\n\\n        component = KnowledgeComponent(knowledge_base=\\\"legacy_docs\\\", _user_id=self.USER_ID)\\n        resolve_policy = AsyncMock()\\n        monkeypatch.setattr(\\\"lfx.services.model_provider_policy.aresolve_model_provider_policy\\\", resolve_policy)\\n        monkeypatch.setattr(\\n            component,\\n            \\\"_get_kb_metadata\\\",\\n            AsyncMock(return_value={\\\"model_selection\\\": {\\\"name\\\": \\\"old-model\\\"}, \\\"embedding_provider\\\": \\\"Unknown\\\"}),\\n        )\\n\\n        with pytest.raises(ModelProviderPolicyError):\\n            await component.arequire_model_provider_policy(\\n                ModelProviderPolicyPurpose.USE,\\n                user_id=\\\"policy-actor\\\",\\n                parameters={\\\"knowledge_base\\\": \\\"legacy_docs\\\"},\\n            )\\n\\n        resolve_policy.assert_not_awaited()\\n\\n    async def test_missing_saved_kb_metadata_fails_closed_before_policy_resolution(self, monkeypatch) -> None:\\n        from lfx.services.model_provider_policy import ModelProviderPolicyError, ModelProviderPolicyPurpose\\n\\n        component = KnowledgeComponent(knowledge_base=\\\"missing_docs\\\", _user_id=self.USER_ID)\\n        resolve_policy = AsyncMock()\\n        metadata_lookup = AsyncMock(return_value={})\\n        monkeypatch.setattr(\\\"lfx.services.model_provider_policy.aresolve_model_provider_policy\\\", resolve_policy)\\n        monkeypatch.setattr(component, \\\"_get_kb_metadata\\\", metadata_lookup)\\n\\n        with pytest.raises(ModelProviderPolicyError):\\n            await component.arequire_model_provider_policy(\\n                ModelProviderPolicyPurpose.USE,\\n                user_id=\\\"policy-actor\\\",\\n                parameters={\\\"knowledge_base\\\": \\\"missing_docs\\\"},\\n            )\\n\\n        metadata_lookup.assert_awaited_once_with(\\\"missing_docs\\\")\\n        resolve_policy.assert_not_awaited()\\n\\n\\n# ---------------------------------------------------------------------------\\n# Display name / dropdown UX (matches starter projects + frontend create dialog)\\n# ---------------------------------------------------------------------------\\nclass TestComponentSurface:\\n    def test_display_name_matches_starter_projects(self) -> None:\\n        \\\"\\\"\\\"The component name on the canvas must read 'Knowledge'.\\n\\n        Starter project JSONs (``Knowledge Retrieval.json``,\\n        ``Vector Store RAG.json``) store ``display_name='Knowledge'`` on\\n        the node header. If the class-level default drifts back to\\n        'Knowledge Base', fresh nodes added from the component panel\\n        will disagree with starter-project nodes.\\n        \\\"\\\"\\\"\\n        assert KnowledgeComponent.display_name == \\\"Knowledge\\\"\\n\\n    def test_create_kb_dialog_label_is_user_facing(self) -> None:\\n        \\\"\\\"\\\"The ``+ ...`` shortcut in the KB dropdown must read 'Create new Knowledge Base'.\\n\\n        The frontend renders the dialog node's ``display_name`` as the\\n        dropdown's create-new affordance. The label must be the full,\\n        user-facing phrase so the dropdown reads as a complete CTA.\\n        \\\"\\\"\\\"\\n        knowledge_base_input = next(i for i in KnowledgeComponent.inputs if i.name == \\\"knowledge_base\\\")\\n        dialog_node = knowledge_base_input.dialog_inputs[\\\"fields\\\"][\\\"data\\\"][\\\"node\\\"]\\n        assert dialog_node[\\\"display_name\\\"] == \\\"Create new Knowledge Base\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# source_types extraction (BUG-04)\\n# ---------------------------------------------------------------------------\\nclass TestExtractSourceTypesFromDataFrame:\\n    \\\"\\\"\\\"Flow-driven ingestion (input_df) must stamp the KB with file extensions.\\n\\n    The Knowledge Bases list keys file-type icons off the ``knowledge_base``\\n    row's ``source_types``. Direct upload populates this; flow-driven\\n    ingestion used to leave it empty, leaving the icon blank. The extractor\\n    reads common path/name columns produced by the File / S3 /\\n    cloud-storage components.\\n    \\\"\\\"\\\"\\n\\n    def test_extracts_pdf_from_file_path_column(self) -> None:\\n        import pandas as pd\\n\\n        df = pd.DataFrame({\\\"file_path\\\": [\\\"docs/report.PDF\\\", \\\"docs/notes.txt\\\"]})\\n        extensions = KnowledgeComponent._extract_source_types_from_df(df)\\n        assert extensions == {\\\"pdf\\\", \\\"txt\\\"}\\n\\n    def test_handles_missing_columns(self) -> None:\\n        import pandas as pd\\n\\n        df = pd.DataFrame({\\\"text\\\": [\\\"hello\\\", \\\"world\\\"]})\\n        assert KnowledgeComponent._extract_source_types_from_df(df) == set()\\n\\n    def test_ignores_non_extension_dotted_values(self) -> None:\\n        \\\"\\\"\\\"URLs with paths / version strings shouldn't pollute the extension set.\\\"\\\"\\\"\\n        import pandas as pd\\n\\n        df = pd.DataFrame(\\n            {\\n                \\\"file_name\\\": [\\n                    \\\"doc.pdf\\\",\\n                    \\\"https://example.com/path\\\",\\n                    \\\"v1.2.3\\\",\\n                    \\\"file.this-is-not-an-ext\\\",\\n                ]\\n            }\\n        )\\n        extensions = KnowledgeComponent._extract_source_types_from_df(df)\\n        # Only \\\"pdf\\\" is a short alphanumeric extension on a real filename;\\n        # \\\"v1.2.3\\\" yields \\\"3\\\" which isn't a meaningful icon key but passes\\n        # the cheap shape check \u2014 we accept that as a known false positive\\n        # over building a strict extension whitelist.\\n        assert \\\"pdf\\\" in extensions\\n        assert \\\"com/path\\\" not in extensions\\n\\n    def test_handles_nan_rows_safely(self) -> None:\\n        import numpy as np\\n        import pandas as pd\\n\\n        df = pd.DataFrame({\\\"file_path\\\": [\\\"docs/a.docx\\\", np.nan, None]})\\n        extensions = KnowledgeComponent._extract_source_types_from_df(df)\\n        assert extensions == {\\\"docx\\\"}\\n\\n    def test_extracts_from_mimetype_column(self) -> None:\\n        \\\"\\\"\\\"MIME types like ``application/pdf`` map to ``pdf`` for the icon palette.\\\"\\\"\\\"\\n        import pandas as pd\\n\\n        df = pd.DataFrame({\\\"mimetype\\\": [\\\"application/pdf\\\", \\\"text/plain\\\"]})\\n        extensions = KnowledgeComponent._extract_source_types_from_df(df)\\n        assert \\\"pdf\\\" in extensions\\n        assert \\\"plain\\\" in extensions\\n\\n\\n# ---------------------------------------------------------------------------\\n# source_types extraction from the *raw* component input (BUG-04 follow-up)\\n# ---------------------------------------------------------------------------\\nclass TestExtractSourceTypesFromInput:\\n    \\\"\\\"\\\"Flow-driven ingestion must read file metadata from the raw input value.\\n\\n    When a File component's Raw Content (Message) is wired to ``input_df``,\\n    ``convert_to_dataframe`` projects the Message down to ``{\\\"text\\\": ...}`` \u2014\\n    file_path / filename / mimetype never reach the DataFrame. We must look\\n    at the raw input to keep the KB icon consistent with direct upload.\\n    \\\"\\\"\\\"\\n\\n    def test_extension_from_path_string(self) -> None:\\n        assert KnowledgeComponent._extension_from_value(\\\"docs/report.PDF\\\") == \\\"pdf\\\"\\n\\n    def test_extension_from_mimetype_string(self) -> None:\\n        assert KnowledgeComponent._extension_from_value(\\\"application/pdf\\\") == \\\"pdf\\\"\\n\\n    def test_extension_returns_none_for_garbage(self) -> None:\\n        assert KnowledgeComponent._extension_from_value(None) is None\\n        assert KnowledgeComponent._extension_from_value(\\\"\\\") is None\\n        assert KnowledgeComponent._extension_from_value(\\\"nodotsorslashes\\\") is None\\n\\n    def test_extracts_from_message_data_dict(self) -> None:\\n        \\\"\\\"\\\"Mirror the shape ``BaseFileComponent._extract_file_metadata`` stamps onto a Message.\\\"\\\"\\\"\\n        from lfx.schema.message import Message\\n\\n        msg = Message(text=\\\"hello\\\", file_path=\\\"/uploads/report.pdf\\\", filename=\\\"report.pdf\\\", mimetype=\\\"application/pdf\\\")\\n        assert KnowledgeComponent._extract_source_types_from_input(msg) == {\\\"pdf\\\"}\\n\\n    def test_extracts_from_data_object(self) -> None:\\n        from lfx.schema.data import Data\\n\\n        data = Data(data={\\\"text\\\": \\\"...\\\", \\\"file_path\\\": \\\"/uploads/notes.txt\\\"})\\n        assert KnowledgeComponent._extract_source_types_from_input(data) == {\\\"txt\\\"}\\n\\n    def test_extracts_from_plain_dict(self) -> None:\\n        payload = {\\\"text\\\": \\\"...\\\", \\\"filename\\\": \\\"presentation.PPTX\\\"}\\n        assert KnowledgeComponent._extract_source_types_from_input(payload) == {\\\"pptx\\\"}\\n\\n    def test_extracts_from_list_of_messages(self) -> None:\\n        from lfx.schema.message import Message\\n\\n        msgs = [\\n            Message(text=\\\"a\\\", file_path=\\\"a.pdf\\\"),\\n            Message(text=\\\"b\\\", file_path=\\\"b.docx\\\"),\\n        ]\\n        assert KnowledgeComponent._extract_source_types_from_input(msgs) == {\\\"pdf\\\", \\\"docx\\\"}\\n\\n    def test_returns_empty_for_text_only_message(self) -> None:\\n        \\\"\\\"\\\"A bare ``Message(text=\\\"...\\\")`` carries no file hints \u2014 extractor must not invent any.\\\"\\\"\\\"\\n        from lfx.schema.message import Message\\n\\n        assert KnowledgeComponent._extract_source_types_from_input(Message(text=\\\"just text\\\")) == set()\\n\\n    def test_returns_empty_for_none(self) -> None:\\n        assert KnowledgeComponent._extract_source_types_from_input(None) == set()\\n\\n\\n# ---------------------------------------------------------------------------\\n# Output handle types (BUG-02)\\n# ---------------------------------------------------------------------------\\nclass TestOutputHandleTypesMatchStarterEdges:\\n    \\\"\\\"\\\"Output handle types must stay single-valued to match saved starter edges.\\n\\n    Saved starter-project edges store ``sourceHandle.output_types`` as a\\n    single-element list (``[\\\"Table\\\"]`` / ``[\\\"JSON\\\"]``). React Flow rebuilds\\n    handle IDs from the live API's ``output.types`` and matches by string\\n    equality, so any widening \u2014 e.g. method annotated ``DataFrame | Data``\\n    auto-extending the handle to ``[\\\"Table\\\", \\\"JSON\\\"]`` \u2014 breaks every\\n    pre-saved edge into / out of the Knowledge node (BUG-02).\\n    \\\"\\\"\\\"\\n\\n    def test_retrieve_output_type_is_table_only(self) -> None:\\n        component = KnowledgeComponent()\\n        retrieve = component._outputs_map[\\\"retrieve_data\\\"]\\n        assert retrieve.types == [\\\"Table\\\"], (\\n            \\\"retrieve_data must advertise only ['Table'] so saved starter edges keyed on \\\"\\n            \\\"output_types=['Table'] still resolve. Widening here re-breaks BUG-02.\\\"\\n        )\\n\\n    def test_ingest_output_type_is_json_only(self) -> None:\\n        component = KnowledgeComponent()\\n        ingest = component._outputs_map[\\\"dataframe_output\\\"]\\n        assert ingest.types == [\\\"JSON\\\"]\\n\\n\\nclass TestUpdateFrontendNodeRestoresModeVisibility:\\n    \\\"\\\"\\\"A saved node must come back with the ``show`` flags of *its* mode.\\n\\n    ``update_frontend_node`` rebuilds the template from the class defaults, which\\n    are ingest-shaped. Before the fix it re-synced only the outputs, so a saved\\n    ``mode=Retrieve`` node returned with ``search_query`` hidden and the canvas\\n    silently deleted the edge feeding it.\\n    \\\"\\\"\\\"\\n\\n    async def _updated_template(self, mode: str) -> dict:\\n        component = KnowledgeComponent()\\n        template = _build_config_from_inputs(component)\\n        template[\\\"mode\\\"][\\\"value\\\"] = mode\\n        frontend_node = {\\\"template\\\": template, \\\"outputs\\\": []}\\n        await component.update_frontend_node(frontend_node, {\\\"template\\\": dict(template)})\\n        return frontend_node[\\\"template\\\"]\\n\\n    async def test_saved_retrieve_node_keeps_retrieve_inputs_visible(self) -> None:\\n        component = KnowledgeComponent()\\n        template = await self._updated_template(MODE_RETRIEVE)\\n\\n        assert template[\\\"search_query\\\"][\\\"show\\\"] is True\\n        for fname in component.mode_config[MODE_RETRIEVE]:\\n            assert template[fname][\\\"show\\\"] is True, f\\\"{fname} must stay visible in retrieve mode\\\"\\n        for fname in component.mode_config[MODE_INGEST]:\\n            assert template[fname][\\\"show\\\"] is False, f\\\"{fname} must be hidden in retrieve mode\\\"\\n\\n    async def test_saved_ingest_node_keeps_ingest_inputs_visible(self) -> None:\\n        component = KnowledgeComponent()\\n        template = await self._updated_template(MODE_INGEST)\\n\\n        for fname in component.mode_config[MODE_INGEST]:\\n            assert template[fname][\\\"show\\\"] is True, f\\\"{fname} must stay visible in ingest mode\\\"\\n        for fname in component.mode_config[MODE_RETRIEVE]:\\n            assert template[fname][\\\"show\\\"] is False, f\\\"{fname} must be hidden in ingest mode\\\"\\n\\n    async def test_default_keys_stay_visible_in_both_modes(self) -> None:\\n        component = KnowledgeComponent()\\n        for mode in (MODE_INGEST, MODE_RETRIEVE):\\n            template = await self._updated_template(mode)\\n            for fname in component.default_keys:\\n                assert template[fname][\\\"show\\\"] is True, f\\\"{fname} must stay visible in {mode}\\\"\\n\\n\\nclass TestKbPathsBackwardCompatibleSymbols:\\n    \\\"\\\"\\\"Frozen 1.11.x component code imports these at module scope.\\n\\n    A saved flow embeds the component code it was built with, so removing a name\\n    from ``_kb_paths`` makes every flow holding that code fail to build with\\n    ``ImportError`` \u2014 the node can no longer be opened, edited or updated.\\n    \\\"\\\"\\\"\\n\\n    def test_removed_symbols_are_still_importable(self) -> None:\\n        from lfx.components.files_and_knowledge._kb_paths import (\\n            KBKeyDecryptError,\\n            load_kb_metadata,\\n        )\\n\\n        assert issubclass(KBKeyDecryptError, Exception)\\n        assert callable(load_kb_metadata)\\n\\n    def test_load_kb_metadata_returns_empty_when_sidecar_is_gone(self, tmp_path) -> None:\\n        from lfx.components.files_and_knowledge._kb_paths import load_kb_metadata\\n\\n        assert load_kb_metadata(tmp_path, log_label=\\\"kb\\\") == {}\\n\\n    def test_load_kb_metadata_never_returns_a_stored_api_key(self, tmp_path) -> None:\\n        from lfx.components.files_and_knowledge._kb_paths import load_kb_metadata\\n\\n        (tmp_path / \\\"embedding_metadata.json\\\").write_text(\\n            json.dumps({\\\"model\\\": \\\"text-embedding-3-small\\\", \\\"api_key\\\": \\\"encrypted\\\"}),\\n            encoding=\\\"utf-8\\\",\\n        )\\n\\n        metadata = load_kb_metadata(tmp_path, log_label=\\\"kb\\\")\\n\\n        assert metadata[\\\"model\\\"] == \\\"text-embedding-3-small\\\"\\n        assert metadata[\\\"api_key\\\"] is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/files_and_knowledge/test_memory_retrieval.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c4155ed2e7cdec024a535fcd1171818029385c182e4f5f51d9c9fcb098823aad\",\"content\":\"\\\"\\\"\\\"Unit tests for MemoryBaseComponent.\\n\\nCovers:\\n- Validation: missing session_id, missing flow_id, MB not attached to flow,\\n  unselected MB, missing owner, missing/invalid metadata, KB path traversal.\\n- Where-clause composition (session filter on / off / multi-predicate).\\n- update_build_config dropdown population.\\n- _coerce_uuid input coercion.\\n- retrieve_data behavior: similarity search w/ filter, empty query short-circuit,\\n  filter_by_session=False end-to-end, include_metadata=False output shape.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nimport json\\nimport uuid\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, MagicMock, call, patch\\n\\nimport numpy as np\\nimport pytest\\nfrom langflow.services.memory_base.kb_path_helpers import hash_session_id\\nfrom lfx.components.files_and_knowledge import _kb_paths\\nfrom lfx.components.files_and_knowledge.memory_retrieval import (\\n    MemoryBaseComponent,\\n    _coerce_uuid,\\n    _to_python_scalar,\\n)\\n\\n\\ndef _make_component(\\n    *,\\n    flow_id: uuid.UUID | None,\\n    session_id: str | None,\\n    invoker_user_id: uuid.UUID | None = None,\\n    selected: str | None = \\\"mb-one\\\",\\n    filter_by_session: bool | str = True,\\n    search_query: str = \\\"hello\\\",\\n    include_metadata: bool = True,\\n) -> MemoryBaseComponent:\\n    invoker_user_id = invoker_user_id or uuid.uuid4()\\n    component = MemoryBaseComponent()\\n    component._vertex = MagicMock()\\n    component._vertex.graph = SimpleNamespace(\\n        flow_id=str(flow_id) if flow_id else None,\\n        session_id=session_id,\\n        user_id=str(invoker_user_id),\\n        flow_name=\\\"test-flow\\\",\\n        context={},\\n    )\\n    component._user_id = str(invoker_user_id)\\n    component.memory_base = selected\\n    component.search_query = search_query\\n    component.top_k = 5\\n    component.include_metadata = include_metadata\\n    component.filter_by_session = filter_by_session\\n    return component\\n\\n\\nclass _Scope:\\n    def __init__(self, db):\\n        self._db = db\\n\\n    async def __aenter__(self):\\n        return self._db\\n\\n    async def __aexit__(self, *_):\\n        return False\\n\\n\\ndef _patched_session_scope(db) -> object:\\n    return patch(\\n        \\\"lfx.components.files_and_knowledge.memory_retrieval.session_scope\\\",\\n        return_value=_Scope(db),\\n    )\\n\\n\\ndef _make_mb_row(*, name: str = \\\"mb-one\\\", flow_id: uuid.UUID, owner_id: uuid.UUID, kb_name: str = \\\"mb_one_kb\\\"):\\n    return SimpleNamespace(\\n        id=uuid.uuid4(),\\n        name=name,\\n        flow_id=flow_id,\\n        user_id=owner_id,\\n        kb_name=kb_name,\\n    )\\n\\n\\ndef _exec_returning(value):\\n    \\\"\\\"\\\"Build a mock matching ``(await db.exec(...)).first()`` / ``.all()`` usage.\\\"\\\"\\\"\\n    db = MagicMock()\\n    exec_result = MagicMock()\\n    exec_result.first.return_value = value\\n    exec_result.all.return_value = value if isinstance(value, list) else [value] if value else []\\n    db.exec = AsyncMock(return_value=exec_result)\\n    return db\\n\\n\\ndef _exec_owner_scoped(mb_row):\\n    \\\"\\\"\\\"Model the DB result for an exact ``name + flow + execution user`` lookup.\\n\\n    The legacy vulnerable query omitted ``user_id`` and therefore resolved the\\n    owner's row for every execution principal.  Keeping that behavior when the\\n    predicate is absent makes the non-owner tests below fail for the actual\\n    security reason instead of depending on SQL string assertions alone.\\n    \\\"\\\"\\\"\\n    db = MagicMock()\\n\\n    async def _exec(stmt):\\n        params = stmt.compile().params\\n        requested_user_id = params.get(\\\"user_id_1\\\")\\n        matched = requested_user_id is None or requested_user_id == mb_row.user_id\\n        result = MagicMock()\\n        result.first.return_value = mb_row if matched else None\\n        return result\\n\\n    db.exec = AsyncMock(side_effect=_exec)\\n    return db\\n\\n\\n# ---------------------------------------------------------------------------\\n# Pure helpers\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestCoerceUuid:\\n    def test_uuid_passthrough(self):\\n        u = uuid.uuid4()\\n        assert _coerce_uuid(u) is u\\n\\n    def test_string_coerced(self):\\n        u = uuid.uuid4()\\n        assert _coerce_uuid(str(u)) == u\\n\\n    def test_none_returns_none(self):\\n        assert _coerce_uuid(None) is None\\n\\n    def test_invalid_returns_none(self):\\n        assert _coerce_uuid(\\\"not-a-uuid\\\") is None\\n\\n    def test_unhashable_returns_none(self):\\n        # Falls through TypeError branch.\\n        assert _coerce_uuid(object()) is None\\n\\n\\n# Score normalization is the backend's contract, covered per backend in\\n# tests/unit/base/knowledge_bases; this module only asserts the component\\n# delegates to it.\\n\\n\\ndef test_result_formatting_uses_backend_score_contract():\\n    component = _make_component(flow_id=uuid.uuid4(), session_id=\\\"s1\\\")\\n    backend = MagicMock()\\n    backend.normalize_score.return_value = 0.91\\n    doc = SimpleNamespace(page_content=\\\"match\\\", metadata={})\\n\\n    result = component._format_results([(doc, 7.0)], backend)\\n\\n    assert result.to_dict(orient=\\\"records\\\")[0][\\\"_score\\\"] == 0.91\\n    backend.normalize_score.assert_called_once_with(7.0)\\n\\n\\nclass TestToPythonScalar:\\n    \\\"\\\"\\\"Numpy scalars must be coerced or the Agent tool path fails serialization.\\\"\\\"\\\"\\n\\n    def test_numpy_int64_becomes_python_int(self):\\n        result = _to_python_scalar(np.int64(42))\\n        assert result == 42\\n        assert type(result) is int\\n\\n    def test_numpy_float64_becomes_python_float(self):\\n        result = _to_python_scalar(np.float64(1.5))\\n        assert result == 1.5\\n        assert type(result) is float\\n\\n    def test_numpy_bool_becomes_python_bool(self):\\n        result = _to_python_scalar(np.bool_(True))  # noqa: FBT003\\n        assert result is True\\n        assert type(result) is bool\\n\\n    def test_python_scalar_passes_through(self):\\n        assert _to_python_scalar(\\\"hello\\\") == \\\"hello\\\"\\n        assert _to_python_scalar(7) == 7\\n        assert _to_python_scalar(None) is None\\n\\n    def test_arbitrary_object_passes_through(self):\\n        sentinel = object()\\n        assert _to_python_scalar(sentinel) is sentinel\\n\\n\\nclass TestToolSurface:\\n    \\\"\\\"\\\"Pin the tool-description surface seen by LLM agents.\\n\\n    The component description and output info are surfaced to LLM agents as the\\n    tool description; they must mention the cross-session capability so the agent\\n    knows to call the tool from a fresh session when 'Filter by Session' is off.\\n\\n    Regression guard for: agents ignoring this tool because the description said\\n    'session-scoped' only, defeating ``filter_by_session=False``.\\n    \\\"\\\"\\\"\\n\\n    def test_description_mentions_cross_session(self):\\n        assert \\\"session\\\" in MemoryBaseComponent.description.lower()\\n        assert \\\"across\\\" in MemoryBaseComponent.description.lower()\\n\\n    def test_filter_by_session_input_info_documents_off_state(self):\\n        bool_input = next(i for i in MemoryBaseComponent.inputs if i.name == \\\"filter_by_session\\\")\\n        assert \\\"disable\\\" in bool_input.info.lower()\\n\\n    def test_output_info_advertises_cross_session(self):\\n        output = next(o for o in MemoryBaseComponent.outputs if o.name == \\\"retrieve_data\\\")\\n        assert \\\"across\\\" in (output.info or \\\"\\\").lower()\\n\\n\\nclass TestBuildWhereClause:\\n    def test_session_filter_on_returns_session_predicate(self):\\n        component = _make_component(flow_id=uuid.uuid4(), session_id=\\\"s1\\\", filter_by_session=True)\\n        assert component._build_where_clause(session_id=\\\"s1\\\") == {\\\"session_id\\\": \\\"s1\\\"}\\n\\n    def test_session_filter_off_returns_none(self):\\n        component = _make_component(flow_id=uuid.uuid4(), session_id=\\\"s1\\\", filter_by_session=False)\\n        assert component._build_where_clause(session_id=\\\"s1\\\") is None\\n\\n    def test_no_session_id_returns_none(self):\\n        component = _make_component(flow_id=uuid.uuid4(), session_id=None, filter_by_session=True)\\n        assert component._build_where_clause(session_id=None) is None\\n\\n    @pytest.mark.parametrize(\\\"serialized_false\\\", [\\\"false\\\", \\\"False\\\", \\\" 0 \\\", \\\"no\\\", \\\"off\\\", \\\"\\\"])\\n    def test_serialized_false_values_disable_session_filter(self, serialized_false):\\n        component = _make_component(\\n            flow_id=uuid.uuid4(),\\n            session_id=\\\"s1\\\",\\n            filter_by_session=serialized_false,\\n        )\\n        assert component._build_where_clause(session_id=\\\"s1\\\") is None\\n\\n    def test_unknown_string_keeps_session_filter_enabled(self):\\n        component = _make_component(flow_id=uuid.uuid4(), session_id=\\\"s1\\\", filter_by_session=\\\"unexpected\\\")\\n        assert component._build_where_clause(session_id=\\\"s1\\\") == {\\\"session_id\\\": \\\"s1\\\"}\\n\\n    def test_session_filter_falsy_value_disables_toggle(self):\\n        component = _make_component(flow_id=uuid.uuid4(), session_id=\\\"s1\\\", filter_by_session=False)\\n        component.filter_by_session = \\\"\\\"  # falsy non-bool\\n        assert component._build_where_clause(session_id=\\\"s1\\\") is None\\n\\n    def test_session_filter_off_with_end_user_scopes_to_end_user(self):\\n        # Serving-plane cross-session recall stays within one end user instead of spanning\\n        # every end user's chunks in the shared service-account store.\\n        component = _make_component(flow_id=uuid.uuid4(), session_id=\\\"alice::s1\\\", filter_by_session=False)\\n        assert component._build_where_clause(session_id=\\\"alice::s1\\\", end_user_id=\\\"alice\\\") == {\\\"end_user_id\\\": \\\"alice\\\"}\\n\\n    def test_session_filter_on_ignores_end_user(self):\\n        # The session-id prefix already scopes to the end user, so the session predicate wins.\\n        component = _make_component(flow_id=uuid.uuid4(), session_id=\\\"alice::s1\\\", filter_by_session=True)\\n        assert component._build_where_clause(session_id=\\\"alice::s1\\\", end_user_id=\\\"alice\\\") == {\\\"session_id\\\": \\\"alice::s1\\\"}\\n\\n    def test_session_filter_off_without_end_user_returns_none(self):\\n        # Editor / feature off: no end user, so cross-session recall spans all sessions (unchanged).\\n        component = _make_component(flow_id=uuid.uuid4(), session_id=\\\"s1\\\", filter_by_session=False)\\n        assert component._build_where_clause(session_id=\\\"s1\\\", end_user_id=None) is None\\n\\n\\n# ---------------------------------------------------------------------------\\n# Serving-plane fail-closed: anonymous caller cannot do cross-session recall\\n# ---------------------------------------------------------------------------\\n\\nMR_MODULE = \\\"lfx.components.files_and_knowledge.memory_retrieval\\\"\\n\\n\\nclass TestMemoryBaseProviderPolicyPreflight:\\n    async def test_db_provider_denial_precedes_owner_credentials_and_uses_actor_scope(self, monkeypatch):\\n        \\\"\\\"\\\"Raw MB selection resolves owner metadata but authorizes the current runtime actor.\\\"\\\"\\\"\\n        from lfx.services.model_provider_policy import (\\n            ModelProviderPolicyContext,\\n            ModelProviderPolicyError,\\n            ModelProviderPolicyPurpose,\\n            current_model_provider_policy_context,\\n            reset_current_model_provider_policy_context,\\n            set_current_model_provider_policy_context,\\n        )\\n\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        actor_id = uuid.uuid4()\\n        component = _make_component(\\n            flow_id=flow_id,\\n            session_id=\\\"s1\\\",\\n            invoker_user_id=owner_id,\\n        )\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        db = _exec_owner_scoped(mb_row)\\n        selection_lookup = AsyncMock(return_value=(\\\"OpenAI\\\", \\\"text-embedding-3-small\\\"))\\n        owner_embedding_build = AsyncMock(side_effect=AssertionError(\\\"owner credential read before actor denial\\\"))\\n        denial = ModelProviderPolicyError(\\\"openai\\\", ModelProviderPolicyPurpose.USE)\\n        snapshot = SimpleNamespace(require=MagicMock(side_effect=denial))\\n        observed_contexts = []\\n\\n        async def resolve_policy(**_kwargs):\\n            observed_contexts.append(current_model_provider_policy_context())\\n            return snapshot\\n\\n        monkeypatch.setattr(\\\"lfx.services.model_provider_policy.aresolve_model_provider_policy\\\", resolve_policy)\\n        token = set_current_model_provider_policy_context(\\n            user_id=actor_id,\\n            attributes={\\\"project_id\\\": \\\"project-current\\\", \\\"workspace_id\\\": \\\"workspace-current\\\"},\\n        )\\n        try:\\n            with (\\n                _patched_session_scope(db),\\n                patch(f\\\"{MR_MODULE}.resolve_embedding_selection\\\", selection_lookup),\\n                patch(\\\"langflow.api.utils.kb_helpers.KBIngestionHelper.build_embeddings\\\", owner_embedding_build),\\n                pytest.raises(ModelProviderPolicyError),\\n            ):\\n                await component.arequire_model_provider_policy(\\n                    ModelProviderPolicyPurpose.USE,\\n                    user_id=actor_id,\\n                    parameters={\\\"memory_base\\\": \\\"mb-one\\\"},\\n                )\\n        finally:\\n            reset_current_model_provider_policy_context(token)\\n\\n        selection_lookup.assert_awaited_once_with(user_id=owner_id, kb_name=mb_row.kb_name)\\n        assert observed_contexts == [\\n            ModelProviderPolicyContext(\\n                user_id=actor_id,\\n                attributes={\\\"project_id\\\": \\\"project-current\\\", \\\"workspace_id\\\": \\\"workspace-current\\\"},\\n            )\\n        ]\\n        owner_embedding_build.assert_not_awaited()\\n        stmt_params = db.exec.await_args.args[0].compile().params\\n        assert owner_id in stmt_params.values()\\n        assert actor_id not in stmt_params.values()\\n\\n    async def test_backend_recheck_uses_actor_policy_snapshot_with_owner_credentials(self, monkeypatch):\\n        \\\"\\\"\\\"A fresh actor decision is passed through while model credentials remain owner-scoped.\\\"\\\"\\\"\\n        from lfx.services.model_provider_policy import (\\n            ModelProviderPolicyPurpose,\\n            reset_current_model_provider_policy_context,\\n            set_current_model_provider_policy_context,\\n        )\\n\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        actor_id = uuid.uuid4()\\n        owner = SimpleNamespace(id=owner_id, username=\\\"owner\\\")\\n        component = _make_component(\\n            flow_id=flow_id,\\n            session_id=\\\"s1\\\",\\n            invoker_user_id=owner_id,\\n        )\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        snapshot = SimpleNamespace(require=MagicMock())\\n        resolve_policy = AsyncMock(return_value=snapshot)\\n        selection_lookup = AsyncMock(return_value=(\\\"OpenAI\\\", \\\"text-embedding-3-small\\\"))\\n        owner_embedding_build = AsyncMock(side_effect=AssertionError(\\\"owner policy was re-evaluated\\\"))\\n        embedding = MagicMock()\\n        get_embeddings = MagicMock(return_value=embedding)\\n        backend = AsyncMock()\\n\\n        monkeypatch.setattr(\\\"lfx.services.model_provider_policy.aresolve_model_provider_policy\\\", resolve_policy)\\n        token = set_current_model_provider_policy_context(\\n            user_id=actor_id,\\n            attributes={\\\"project_id\\\": \\\"project-current\\\", \\\"workspace_id\\\": \\\"workspace-current\\\"},\\n        )\\n        try:\\n            with (\\n                _patched_session_scope(_exec_owner_scoped(mb_row)),\\n                patch(f\\\"{MR_MODULE}.resolve_embedding_selection\\\", selection_lookup),\\n                patch(f\\\"{MR_MODULE}.resolve_backend_selection\\\", new=AsyncMock(return_value=(\\\"chroma\\\", {}))),\\n                patch(f\\\"{MR_MODULE}.resolve_local_store_path\\\", return_value=None),\\n                patch(\\\"langflow.api.utils.kb_helpers.KBIngestionHelper.build_embeddings\\\", owner_embedding_build),\\n                patch(\\\"lfx.base.models.unified_models.get_embeddings\\\", get_embeddings),\\n                patch(f\\\"{MR_MODULE}.create_backend\\\", return_value=backend),\\n            ):\\n                await component.arequire_model_provider_policy(\\n                    ModelProviderPolicyPurpose.USE,\\n                    user_id=actor_id,\\n                    parameters={\\\"memory_base\\\": \\\"mb-one\\\"},\\n                )\\n                built_backend = await component._build_backend(owner, owner.username, mb_row.kb_name)\\n        finally:\\n            reset_current_model_provider_policy_context(token)\\n\\n        assert built_backend is backend\\n        assert resolve_policy.await_count == 2\\n        assert all(call.kwargs[\\\"user_id\\\"] == actor_id for call in resolve_policy.await_args_list)\\n        selection_lookup.assert_has_awaits(\\n            [\\n                call(user_id=owner_id, kb_name=mb_row.kb_name),\\n                call(user_id=owner_id, kb_name=mb_row.kb_name),\\n            ]\\n        )\\n        owner_embedding_build.assert_not_awaited()\\n        assert get_embeddings.call_args.kwargs[\\\"user_id\\\"] == owner_id\\n        assert get_embeddings.call_args.kwargs[\\\"provider_policy\\\"] is snapshot\\n        backend.ensure_ready.assert_awaited_once()\\n\\n\\nclass TestServingFailClosed:\\n    async def test_anonymous_cross_session_recall_returns_empty(self):\\n        # Serving on + filter_by_session off + no derivable end user (anonymous) must NOT\\n        # run an unfiltered search over the shared store \u2014 it would return every end user's\\n        # memory. It short-circuits to empty before any owner lookup / backend construction.\\n        component = _make_component(flow_id=uuid.uuid4(), session_id=\\\"anon::deadbeef\\\", filter_by_session=False)\\n        with (\\n            patch(f\\\"{MR_MODULE}.serving_end_user_enabled\\\", return_value=True),\\n            patch(f\\\"{MR_MODULE}.end_user_id_from_scoped_session\\\", return_value=None),\\n        ):\\n            result = await component.retrieve_memory()\\n        assert len(result) == 0\\n\\n    async def test_feature_off_cross_session_recall_not_blocked(self):\\n        # Feature off: the fail-closed guard must not fire \u2014 cross-session recall stays\\n        # available exactly as before (proven by reaching the flow_id validation, not the\\n        # early empty return). end_user_id_from_scoped_session returns None when off.\\n        component = _make_component(flow_id=None, session_id=\\\"s1\\\", filter_by_session=False)\\n        with (\\n            patch(f\\\"{MR_MODULE}.serving_end_user_enabled\\\", return_value=False),\\n            patch(f\\\"{MR_MODULE}.end_user_id_from_scoped_session\\\", return_value=None),\\n            pytest.raises(ValueError, match=\\\"flow_id is not available\\\"),\\n        ):\\n            await component.retrieve_memory()\\n\\n\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestRootPathCache:\\n    def test_reset_cache_picks_up_new_setting(self, tmp_path):\\n        _kb_paths.reset_knowledge_bases_root_path_cache()\\n        first = tmp_path / \\\"first\\\"\\n        second = tmp_path / \\\"second\\\"\\n        with patch(\\\"lfx.components.files_and_knowledge._kb_paths.get_settings_service\\\") as gs:\\n            gs.return_value.settings.knowledge_bases_dir = str(first)\\n            assert _kb_paths.get_knowledge_bases_root_path() == first\\n            # Cached value is returned even if settings change.\\n            gs.return_value.settings.knowledge_bases_dir = str(second)\\n            assert _kb_paths.get_knowledge_bases_root_path() == first\\n            _kb_paths.reset_knowledge_bases_root_path_cache()\\n            assert _kb_paths.get_knowledge_bases_root_path() == second\\n        _kb_paths.reset_knowledge_bases_root_path_cache()\\n\\n    def test_unset_directory_raises(self):\\n        _kb_paths.reset_knowledge_bases_root_path_cache()\\n        with patch(\\\"lfx.components.files_and_knowledge._kb_paths.get_settings_service\\\") as gs:\\n            gs.return_value.settings.knowledge_bases_dir = \\\"\\\"\\n            with pytest.raises(ValueError, match=\\\"Knowledge bases directory\\\"):\\n                _kb_paths.get_knowledge_bases_root_path()\\n        _kb_paths.reset_knowledge_bases_root_path_cache()\\n\\n\\n# ---------------------------------------------------------------------------\\n# update_build_config\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestUpdateBuildConfig:\\n    async def test_other_field_returns_unchanged(self):\\n        component = _make_component(flow_id=uuid.uuid4(), session_id=\\\"s1\\\")\\n        cfg = {\\\"memory_base\\\": {\\\"options\\\": [\\\"existing\\\"], \\\"value\\\": \\\"existing\\\"}}\\n        result = await component.update_build_config(cfg, None, field_name=\\\"other\\\")\\n        assert result is cfg\\n        assert cfg[\\\"memory_base\\\"][\\\"options\\\"] == [\\\"existing\\\"]\\n\\n    async def test_missing_flow_id_clears_options(self):\\n        component = _make_component(flow_id=None, session_id=\\\"s1\\\")\\n        component._get_runtime_or_frontend_node_attr = MagicMock(return_value=None)\\n        cfg = {\\\"memory_base\\\": {\\\"options\\\": [\\\"mb-stale\\\"], \\\"value\\\": \\\"mb-stale\\\"}}\\n        result = await component.update_build_config(cfg, None, field_name=\\\"memory_base\\\")\\n        assert result[\\\"memory_base\\\"][\\\"options\\\"] == []\\n        assert result[\\\"memory_base\\\"][\\\"value\\\"] is None\\n\\n    async def test_options_populated_and_stale_value_cleared(self):\\n        flow_id = uuid.uuid4()\\n        invoker = uuid.uuid4()\\n        component = _make_component(flow_id=flow_id, session_id=\\\"s1\\\", invoker_user_id=invoker)\\n        component._get_runtime_or_frontend_node_attr = MagicMock(return_value=str(flow_id))\\n\\n        rows = [\\n            SimpleNamespace(name=\\\"mb-b\\\"),\\n            SimpleNamespace(name=\\\"mb-a\\\"),\\n        ]\\n        db = _exec_returning(rows)\\n\\n        cfg = {\\\"memory_base\\\": {\\\"options\\\": [], \\\"value\\\": \\\"mb-not-here\\\"}}\\n        with _patched_session_scope(db):\\n            result = await component.update_build_config(cfg, None, field_name=\\\"memory_base\\\")\\n        assert result[\\\"memory_base\\\"][\\\"options\\\"] == [\\\"mb-a\\\", \\\"mb-b\\\"]\\n        assert result[\\\"memory_base\\\"][\\\"value\\\"] is None\\n\\n\\n# ---------------------------------------------------------------------------\\n# retrieve_data \u2014 invariants and full path\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestMemoryBaseRetrievalInvariants:\\n    async def test_missing_session_id_raises_when_filter_enabled(self):\\n        component = _make_component(flow_id=uuid.uuid4(), session_id=None, filter_by_session=True)\\n        with pytest.raises(ValueError, match=\\\"session_id is required\\\"):\\n            await component.retrieve_memory()\\n\\n    @pytest.mark.parametrize(\\\"serialized_false\\\", [\\\"false\\\", \\\"0\\\"])\\n    async def test_serialized_false_does_not_require_session_id(self, serialized_false):\\n        component = _make_component(\\n            flow_id=uuid.uuid4(),\\n            session_id=None,\\n            selected=None,\\n            filter_by_session=serialized_false,\\n        )\\n        with pytest.raises(ValueError, match=\\\"No Memory Base\\\"):\\n            await component.retrieve_memory()\\n\\n    async def test_missing_session_id_allowed_when_filter_disabled(self):\\n        \\\"\\\"\\\"Cross-session retrieval should not require a session_id on the graph.\\\"\\\"\\\"\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        component = _make_component(\\n            flow_id=flow_id,\\n            session_id=None,\\n            filter_by_session=False,\\n        )\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        owner = SimpleNamespace(id=owner_id, username=\\\"alice\\\")\\n\\n        fake_backend = AsyncMock()\\n        fake_backend.similarity_search.return_value = []\\n\\n        with contextlib.ExitStack() as stack:\\n            TestMemoryBaseRetrievalBehavior._enter_full_chain(\\n                stack,\\n                db=_exec_returning(mb_row),\\n                fake_backend=fake_backend,\\n                owner=owner,\\n                metadata={\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"x\\\"},\\n            )\\n            result = await component.retrieve_memory()\\n\\n        assert len(result) == 0\\n        kwargs = fake_backend.similarity_search.call_args.kwargs\\n        assert kwargs[\\\"filter\\\"] is None\\n\\n    async def test_missing_flow_id_raises(self):\\n        component = _make_component(flow_id=None, session_id=\\\"s1\\\")\\n        with pytest.raises(ValueError, match=\\\"flow_id\\\"):\\n            await component.retrieve_memory()\\n\\n    @pytest.mark.parametrize(\\\"runtime_user_id\\\", [None, \\\"not-a-uuid\\\"])\\n    async def test_missing_or_invalid_runtime_user_fails_before_owner_resolution(self, runtime_user_id):\\n        \\\"\\\"\\\"A malformed graph principal must never fall back to the Memory Base owner.\\\"\\\"\\\"\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        component = _make_component(\\n            flow_id=flow_id,\\n            session_id=None,\\n            filter_by_session=False,\\n            invoker_user_id=owner_id,\\n        )\\n        component.graph.user_id = runtime_user_id\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        fake_backend = AsyncMock()\\n        fake_backend.similarity_search.return_value = []\\n\\n        with contextlib.ExitStack() as stack:\\n            TestMemoryBaseRetrievalBehavior._enter_full_chain(\\n                stack,\\n                db=_exec_owner_scoped(mb_row),\\n                fake_backend=fake_backend,\\n                owner=SimpleNamespace(id=owner_id, username=\\\"owner\\\"),\\n                metadata={\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"x\\\"},\\n            )\\n            with pytest.raises(ValueError, match=\\\"user_id\\\"):\\n                await component.retrieve_memory()\\n\\n        fake_backend.ensure_ready.assert_not_awaited()\\n        fake_backend.similarity_search.assert_not_awaited()\\n\\n    async def test_no_memory_base_selected_raises(self):\\n        component = _make_component(flow_id=uuid.uuid4(), session_id=\\\"s1\\\", selected=None)\\n        with pytest.raises(ValueError, match=\\\"No Memory Base\\\"):\\n            await component.retrieve_memory()\\n\\n    async def test_mb_not_attached_to_flow_raises(self):\\n        component = _make_component(flow_id=uuid.uuid4(), session_id=\\\"s1\\\")\\n        db = _exec_returning(None)\\n        with _patched_session_scope(db), pytest.raises(ValueError, match=\\\"not attached to this flow\\\"):\\n            await component.retrieve_memory()\\n\\n    async def test_owner_not_found_raises(self):\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        component = _make_component(flow_id=flow_id, session_id=\\\"s1\\\")\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        db = _exec_returning(mb_row)\\n        with (\\n            _patched_session_scope(db),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.memory_retrieval.get_user_by_id\\\",\\n                new=AsyncMock(return_value=None),\\n            ),\\n            pytest.raises(ValueError, match=\\\"owner account\\\"),\\n        ):\\n            await component.retrieve_memory()\\n\\n    async def test_retrieval_works_without_on_disk_sidecar(self):\\n        \\\"\\\"\\\"A missing on-disk sidecar must NOT block retrieval.\\n\\n        Embedding + backend resolve from the knowledge_base row, so a remote-backed\\n        Memory Base is queryable on a replica whose local disk never held the KB\\n        directory. This is the regression guard for the old hard-fail\\n        (\\\"has no embedding metadata on disk\\\").\\n        \\\"\\\"\\\"\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        component = _make_component(flow_id=flow_id, session_id=\\\"s1\\\")\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        owner = SimpleNamespace(id=owner_id, username=\\\"alice\\\")\\n\\n        fake_backend = AsyncMock()\\n        fake_backend.similarity_search.return_value = []\\n\\n        with contextlib.ExitStack() as stack:\\n            TestMemoryBaseRetrievalBehavior._enter_full_chain(\\n                stack,\\n                db=_exec_returning(mb_row),\\n                fake_backend=fake_backend,\\n                owner=owner,\\n                # No sidecar on disk \u2014 resolver falls back to the default model.\\n                metadata={},\\n            )\\n            result = await component.retrieve_memory()\\n\\n        assert len(result) == 0\\n        fake_backend.similarity_search.assert_awaited_once()\\n\\n    async def test_kb_path_traversal_raises(self):\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        component = _make_component(flow_id=flow_id, session_id=\\\"s1\\\")\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        owner = SimpleNamespace(id=owner_id, username=\\\"../escape\\\")\\n        db = _exec_returning(mb_row)\\n        with (\\n            _patched_session_scope(db),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.memory_retrieval.get_user_by_id\\\",\\n                new=AsyncMock(return_value=owner),\\n            ),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.memory_retrieval.resolve_backend_selection\\\",\\n                new=AsyncMock(return_value=(\\\"chroma\\\", {})),\\n            ),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.memory_retrieval.resolve_local_store_path\\\",\\n                side_effect=ValueError(\\\"KB path escapes root directory\\\"),\\n            ),\\n            pytest.raises(ValueError, match=\\\"not accessible\\\"),\\n        ):\\n            await component.retrieve_memory()\\n\\n\\nclass TestMemoryBaseRetrievalBehavior:\\n    @staticmethod\\n    def _enter_full_chain(stack: contextlib.ExitStack, *, db, fake_backend, owner, metadata):\\n        # Embedding provider/model now come from the DB row via\\n        # resolve_embedding_selection (no on-disk sidecar), so patch that instead\\n        # of the removed sidecar read. The ``metadata`` dict is reused as\\n        # the source of the provider/model the resolver returns.\\n        provider = metadata.get(\\\"embedding_provider\\\", \\\"OpenAI\\\")\\n        model = metadata.get(\\\"embedding_model\\\", \\\"x\\\")\\n        # Stand in for the distance-based backend contract (higher == more similar).\\n        fake_backend.normalize_score = MagicMock(side_effect=lambda score: -float(score))\\n        for cm in (\\n            _patched_session_scope(db),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.memory_retrieval.get_user_by_id\\\",\\n                new=AsyncMock(return_value=owner),\\n            ),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.memory_retrieval.resolve_local_store_path\\\",\\n                return_value=None,\\n            ),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.memory_retrieval.resolve_embedding_selection\\\",\\n                new=AsyncMock(return_value=(provider, model)),\\n            ),\\n            patch(\\\"lfx.base.models.unified_models.get_embeddings\\\", return_value=MagicMock()),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.memory_retrieval.resolve_backend_selection\\\",\\n                new=AsyncMock(return_value=(\\\"chroma\\\", {})),\\n            ),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.memory_retrieval.create_backend\\\",\\n                return_value=fake_backend,\\n            ),\\n        ):\\n            stack.enter_context(cm)\\n\\n    async def test_similarity_search_uses_session_filter_when_enabled(self):\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        component = _make_component(flow_id=flow_id, session_id=\\\"s1\\\", filter_by_session=True)\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        owner = SimpleNamespace(id=owner_id, username=\\\"alice\\\")\\n\\n        fake_backend = AsyncMock()\\n        fake_backend.similarity_search.return_value = []\\n\\n        with contextlib.ExitStack() as stack:\\n            self._enter_full_chain(\\n                stack,\\n                db=_exec_returning(mb_row),\\n                fake_backend=fake_backend,\\n                owner=owner,\\n                metadata={\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"x\\\", \\\"api_key\\\": \\\"k\\\"},\\n            )\\n            await component.retrieve_memory()\\n\\n        kwargs = fake_backend.similarity_search.call_args.kwargs\\n        assert kwargs[\\\"k\\\"] == 5\\n        assert kwargs[\\\"filter\\\"] == {\\\"session_id\\\": \\\"s1\\\"}\\n\\n    async def test_debug_log_redacts_raw_session_id(self):\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        session_id = \\\"private-session-id\\\"\\n        component = _make_component(flow_id=flow_id, session_id=session_id, filter_by_session=True)\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        owner = SimpleNamespace(id=owner_id, username=\\\"alice\\\")\\n        fake_backend = AsyncMock()\\n        fake_backend.similarity_search.return_value = []\\n\\n        with contextlib.ExitStack() as stack:\\n            self._enter_full_chain(\\n                stack,\\n                db=_exec_returning(mb_row),\\n                fake_backend=fake_backend,\\n                owner=owner,\\n                metadata={\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"x\\\"},\\n            )\\n            debug_mock = stack.enter_context(patch(\\\"lfx.components.files_and_knowledge.memory_retrieval.logger.debug\\\"))\\n            await component.retrieve_memory()\\n\\n        logged = repr(debug_mock.call_args_list)\\n        assert session_id not in logged\\n        assert hash_session_id(session_id) in logged\\n\\n    async def test_similarity_search_no_filter_when_disabled(self):\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        component = _make_component(flow_id=flow_id, session_id=\\\"s1\\\", filter_by_session=False)\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        owner = SimpleNamespace(id=owner_id, username=\\\"alice\\\")\\n\\n        fake_backend = AsyncMock()\\n        fake_backend.similarity_search.return_value = []\\n\\n        with contextlib.ExitStack() as stack:\\n            self._enter_full_chain(\\n                stack,\\n                db=_exec_returning(mb_row),\\n                fake_backend=fake_backend,\\n                owner=owner,\\n                metadata={\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"x\\\"},\\n            )\\n            await component.retrieve_memory()\\n\\n        kwargs = fake_backend.similarity_search.call_args.kwargs\\n        assert kwargs[\\\"filter\\\"] is None\\n\\n    async def test_owner_can_retrieve_across_sessions_under_owner_principal(self):\\n        \\\"\\\"\\\"The owner-equivalent execution principal keeps the cross-session feature working.\\\"\\\"\\\"\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        component = _make_component(\\n            flow_id=flow_id,\\n            session_id=None,\\n            filter_by_session=False,\\n            invoker_user_id=owner_id,\\n        )\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        owner = SimpleNamespace(id=owner_id, username=\\\"owner\\\")\\n        fake_backend = AsyncMock()\\n        fake_backend.similarity_search.return_value = []\\n\\n        with contextlib.ExitStack() as stack:\\n            self._enter_full_chain(\\n                stack,\\n                db=_exec_owner_scoped(mb_row),\\n                fake_backend=fake_backend,\\n                owner=owner,\\n                metadata={\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"x\\\"},\\n            )\\n            result = await component.retrieve_memory()\\n\\n        assert len(result) == 0\\n        fake_backend.ensure_ready.assert_awaited_once()\\n        fake_backend.similarity_search.assert_awaited_once()\\n\\n    @pytest.mark.parametrize(\\n        \\\"caller_kind\\\",\\n        [\\\"delegate\\\", \\\"public_v1\\\", \\\"public_v2\\\", \\\"public_a2a_initial\\\", \\\"public_a2a_hitl_resume\\\"],\\n    )\\n    async def test_non_owner_principal_cannot_open_owner_backend_when_session_filter_is_off(self, caller_kind):\\n        \\\"\\\"\\\"Every non-owner route principal fails before owner lookup/backend construction.\\\"\\\"\\\"\\n        from langflow.services.authorization.public_access import PUBLIC_ANONYMOUS_ACTOR_ID\\n\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        caller_id = uuid.uuid4() if caller_kind == \\\"delegate\\\" else PUBLIC_ANONYMOUS_ACTOR_ID\\n        component = _make_component(\\n            flow_id=flow_id,\\n            session_id=None,\\n            filter_by_session=False,\\n            invoker_user_id=caller_id,\\n        )\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        owner = SimpleNamespace(id=owner_id, username=\\\"owner\\\")\\n        fake_backend = AsyncMock()\\n        fake_backend.similarity_search.return_value = []\\n\\n        with contextlib.ExitStack() as stack:\\n            self._enter_full_chain(\\n                stack,\\n                db=_exec_owner_scoped(mb_row),\\n                fake_backend=fake_backend,\\n                owner=owner,\\n                metadata={\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"x\\\"},\\n            )\\n            with pytest.raises(ValueError, match=\\\"not attached to this flow\\\"):\\n                await component.retrieve_memory()\\n\\n        fake_backend.ensure_ready.assert_not_awaited()\\n        fake_backend.similarity_search.assert_not_awaited()\\n\\n    async def test_empty_search_query_returns_empty_dataframe_without_embedding(self):\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        component = _make_component(\\n            flow_id=flow_id,\\n            session_id=\\\"s1\\\",\\n            search_query=\\\"\\\",\\n        )\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        owner = SimpleNamespace(id=owner_id, username=\\\"alice\\\")\\n\\n        fake_backend = AsyncMock()\\n\\n        with contextlib.ExitStack() as stack:\\n            self._enter_full_chain(\\n                stack,\\n                db=_exec_returning(mb_row),\\n                fake_backend=fake_backend,\\n                owner=owner,\\n                metadata={\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"x\\\"},\\n            )\\n            result = await component.retrieve_memory()\\n\\n        assert len(result) == 0\\n        fake_backend.similarity_search.assert_not_called()\\n        fake_backend.similarity_search.assert_not_called()\\n\\n    async def test_include_metadata_false_drops_metadata_keys(self):\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        component = _make_component(\\n            flow_id=flow_id,\\n            session_id=\\\"s1\\\",\\n            include_metadata=False,\\n        )\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        owner = SimpleNamespace(id=owner_id, username=\\\"alice\\\")\\n\\n        doc = SimpleNamespace(page_content=\\\"hello world\\\", metadata={\\\"session_id\\\": \\\"s1\\\", \\\"sender\\\": \\\"user\\\"})\\n        fake_backend = AsyncMock()\\n        fake_backend.similarity_search.return_value = [(doc, 0.25)]\\n\\n        with contextlib.ExitStack() as stack:\\n            self._enter_full_chain(\\n                stack,\\n                db=_exec_returning(mb_row),\\n                fake_backend=fake_backend,\\n                owner=owner,\\n                metadata={\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"x\\\"},\\n            )\\n            df = await component.retrieve_memory()\\n\\n        assert len(df) == 1\\n        row = df.to_dict(orient=\\\"records\\\")[0]\\n        assert row[\\\"content\\\"] == \\\"hello world\\\"\\n        assert row[\\\"_score\\\"] == -0.25\\n        assert \\\"session_id\\\" not in row\\n        assert \\\"sender\\\" not in row\\n\\n    async def test_include_metadata_true_merges_metadata(self):\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        component = _make_component(flow_id=flow_id, session_id=\\\"s1\\\", include_metadata=True)\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        owner = SimpleNamespace(id=owner_id, username=\\\"alice\\\")\\n\\n        doc = SimpleNamespace(page_content=\\\"hi\\\", metadata={\\\"session_id\\\": \\\"s1\\\", \\\"sender\\\": \\\"ai\\\"})\\n        fake_backend = AsyncMock()\\n        fake_backend.similarity_search.return_value = [(doc, 0.1)]\\n\\n        with contextlib.ExitStack() as stack:\\n            self._enter_full_chain(\\n                stack,\\n                db=_exec_returning(mb_row),\\n                fake_backend=fake_backend,\\n                owner=owner,\\n                metadata={\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"x\\\"},\\n            )\\n            df = await component.retrieve_memory()\\n\\n        row = df.to_dict(orient=\\\"records\\\")[0]\\n        assert row[\\\"sender\\\"] == \\\"ai\\\"\\n        assert row[\\\"session_id\\\"] == \\\"s1\\\"\\n\\n    async def test_numpy_metadata_values_are_normalized(self):\\n        \\\"\\\"\\\"Regression: numpy.int64 in Chroma metadata broke Agent tool serialization.\\n\\n        Chroma stores integer metadata (timestamps, ingestion IDs, \u2026) as\\n        numpy.int64 scalars. The Agent's tool-output path then calls\\n        ``vars()`` on / iterates those values, raising TypeError. Confirm\\n        the component coerces to Python primitives before emitting Data rows.\\n        \\\"\\\"\\\"\\n        flow_id = uuid.uuid4()\\n        owner_id = uuid.uuid4()\\n        component = _make_component(flow_id=flow_id, session_id=\\\"s1\\\", include_metadata=True)\\n        mb_row = _make_mb_row(flow_id=flow_id, owner_id=owner_id)\\n        owner = SimpleNamespace(id=owner_id, username=\\\"alice\\\")\\n\\n        doc = SimpleNamespace(\\n            page_content=\\\"hello\\\",\\n            metadata={\\n                \\\"session_id\\\": \\\"s1\\\",\\n                \\\"ingest_seq\\\": np.int64(7),\\n                \\\"timestamp\\\": np.int64(1_700_000_000),\\n                \\\"score_raw\\\": np.float64(0.42),\\n                \\\"is_summary\\\": np.bool_(True),  # noqa: FBT003\\n            },\\n        )\\n        fake_backend = AsyncMock()\\n        fake_backend.similarity_search.return_value = [(doc, np.float64(0.25))]\\n\\n        with contextlib.ExitStack() as stack:\\n            self._enter_full_chain(\\n                stack,\\n                db=_exec_returning(mb_row),\\n                fake_backend=fake_backend,\\n                owner=owner,\\n                metadata={\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"x\\\"},\\n            )\\n            df = await component.retrieve_memory()\\n\\n        row = df.to_dict(orient=\\\"records\\\")[0]\\n        assert row[\\\"ingest_seq\\\"] == 7\\n        assert type(row[\\\"ingest_seq\\\"]) is int\\n        assert row[\\\"timestamp\\\"] == 1_700_000_000\\n        assert type(row[\\\"timestamp\\\"]) is int\\n        assert row[\\\"score_raw\\\"] == 0.42\\n        assert type(row[\\\"score_raw\\\"]) is float\\n        assert row[\\\"is_summary\\\"] is True\\n        assert type(row[\\\"is_summary\\\"]) is bool\\n        # _score derives from the numpy distance; confirm it is also normalized.\\n        assert type(row[\\\"_score\\\"]) is float\\n\\n        # The whole row must JSON-serialize without falling back to a custom encoder.\\n        json.dumps(row)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/files_and_knowledge/test_retrieval.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c5e905a16a2f26d46305c54a8465ee19f2e99fa53dee559e977a38a53545ea07\",\"content\":\"\\\"\\\"\\\"Tests for ``KnowledgeBaseComponent`` after the unified-models port.\\n\\nPre-port this file was ~938 lines and tested a hand-rolled per-\\nprovider ``_build_embeddings`` + ``_resolve_api_key`` +\\n``_resolve_provider_variables`` surface. All three are gone now \u2014\\nretrieval delegates credential resolution to\\n``lfx.base.models.unified_models.get_embeddings`` (same as ingestion)\\nand vector access to the configured backend registry entry.\\n\\nThe rewritten suite covers the actual retrieval contract:\\n\\n* ``_get_kb_metadata`` reading the ``knowledge_base`` row.\\n* ``_resolve_model_selection`` preferring ``model_selection`` over\\n  the legacy string fields, with a clear error when neither is\\n  present and the string doesn't map to a current catalog entry.\\n* ``retrieve_data`` orchestrating ``get_embeddings`` +\\n  backend-registry ``similarity_search`` against the right KB path\\n  (resolved only when the row says local Chroma).\\n* User-scoping + required-field guards that make retrieval safe\\n  across sessions.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport hashlib\\nimport json\\nfrom pathlib import Path\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom langchain_core.documents import Document\\nfrom langchain_core.embeddings import Embeddings\\nfrom lfx.base.knowledge_bases.backends import ChromaLocalBackend\\nfrom lfx.base.knowledge_bases.knowledge_base_utils import get_knowledge_bases\\nfrom lfx.components.files_and_knowledge.retrieval import KnowledgeBaseComponent\\n\\nfrom tests.base import ComponentTestBaseWithClient\\n\\n\\nclass _DeterministicEmbeddings(Embeddings):\\n    \\\"\\\"\\\"Hash-based embedder so the embedding join can be exercised without credentials.\\n\\n    Uses ``hashlib`` (not the builtin ``hash``) so the vector for a given string is\\n    stable across processes \u2014 the ingest pass and the query pass must agree.\\n    \\\"\\\"\\\"\\n\\n    DIMENSION = 8\\n\\n    def _embed(self, text: str) -> list[float]:\\n        digest = int(hashlib.sha256(text.encode()).hexdigest(), 16)\\n        return [((digest >> (i * 4)) & 0xF) / 15.0 for i in range(self.DIMENSION)]\\n\\n    def embed_documents(self, texts: list[str]) -> list[list[float]]:\\n        return [self._embed(t) for t in texts]\\n\\n    def embed_query(self, text: str) -> list[float]:\\n        return self._embed(text)\\n\\n\\nclass TestKnowledgeBaseComponent(ComponentTestBaseWithClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        return KnowledgeBaseComponent\\n\\n    @pytest.fixture(autouse=True)\\n    def mock_knowledge_base_path(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Pin the KB root at a fresh tmp dir for every test.\\n\\n        Local-Chroma path resolution goes through\\n        ``KBStorageHelper.get_root_path``, which reads the setting live, so the\\n        setting is what has to move \u2014 patching the lfx module-level cache alone\\n        would leave the two disagreeing.\\n        \\\"\\\"\\\"\\n        from langflow.services.deps import get_settings_service\\n\\n        monkeypatch.setattr(get_settings_service().settings, \\\"knowledge_bases_dir\\\", str(tmp_path))\\n        with patch(\\\"lfx.components.files_and_knowledge._kb_paths._KNOWLEDGE_BASES_ROOT_PATH\\\", tmp_path):\\n            yield\\n\\n    @pytest.fixture\\n    async def default_kwargs(self, tmp_path, active_user):\\n        \\\"\\\"\\\"Seed the KB's ``knowledge_base`` row \u2014 the sole authority for its config.\\n\\n        The directory is created too because this KB is local-Chroma backed and\\n        that is where its vectors would live; no metadata sidecar is written,\\n        because nothing reads one.\\n        \\\"\\\"\\\"\\n        from langflow.api.utils import knowledge_base_service\\n\\n        kb_name = \\\"test_kb\\\"\\n        (tmp_path / active_user.username / kb_name).mkdir(parents=True, exist_ok=True)\\n\\n        await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=kb_name,\\n            model_selection={\\n                \\\"name\\\": \\\"sentence-transformers/all-MiniLM-L6-v2\\\",\\n                \\\"provider\\\": \\\"HuggingFace\\\",\\n                \\\"metadata\\\": {\\n                    \\\"embedding_class\\\": \\\"HuggingFaceEmbeddings\\\",\\n                    \\\"param_mapping\\\": {\\\"model_name\\\": \\\"model\\\"},\\n                },\\n            },\\n            chunk_size=1000,\\n        )\\n\\n        return {\\n            \\\"knowledge_base\\\": kb_name,\\n            \\\"kb_root_path\\\": str(tmp_path),\\n            \\\"search_query\\\": \\\"\\\",\\n            \\\"top_k\\\": 5,\\n            \\\"include_embeddings\\\": False,\\n            \\\"_user_id\\\": active_user.id,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"New-style component: no legacy filenames.\\\"\\\"\\\"\\n        return []\\n\\n    # ---- update_build_config ----------------------------------------\\n\\n    async def test_get_knowledge_bases_utility(self, tmp_path, active_user):\\n        \\\"\\\"\\\"The dropdown lists rows, not directories.\\\"\\\"\\\"\\n        from langflow.api.utils import knowledge_base_service\\n\\n        # Directories alone are invisible; only rows appear.\\n        (tmp_path / active_user.username / \\\"dir_without_row\\\").mkdir(parents=True, exist_ok=True)\\n        await knowledge_base_service.create_record(user_id=active_user.id, name=\\\"kb1\\\")\\n        await knowledge_base_service.create_record(user_id=active_user.id, name=\\\"kb2\\\")\\n\\n        kb_list = await get_knowledge_bases(user_id=active_user.id)\\n\\n        assert \\\"test_kb\\\" in kb_list\\n        assert \\\"kb1\\\" in kb_list\\n        assert \\\"kb2\\\" in kb_list\\n        assert \\\"dir_without_row\\\" not in kb_list\\n\\n    async def test_get_knowledge_bases_db_first_hides_stale_disk_dirs(self, tmp_path, active_user):\\n        \\\"\\\"\\\"DB-first listing hides on-disk dirs that have no matching DB row.\\n\\n        Regression for the dropdown showing entries (e.g. ``api_baseline_*``,\\n        ``customer_sales_history_*``) that no longer exist on the Knowledge\\n        management page. Before the fix, the lfx helper scanned the disk\\n        unconditionally, so any directory left over from a delete that did\\n        not write the ``.kb_deleted`` sentinel (legacy delete, direct\\n        ``DELETE FROM knowledge_base``, DB reset, etc.) would re-surface in\\n        the canvas dropdown but not on the management page (which is\\n        DB-first). The two surfaces must agree.\\n        \\\"\\\"\\\"\\n        from langflow.api.utils import knowledge_base_service\\n\\n        # Disk has both a \\\"real\\\" KB (with a DB row) and a leftover stale dir.\\n        (tmp_path / active_user.username / \\\"real_kb\\\").mkdir(parents=True, exist_ok=True)\\n        (tmp_path / active_user.username / \\\"stale_dir\\\").mkdir(parents=True, exist_ok=True)\\n        await knowledge_base_service.create_record(user_id=active_user.id, name=\\\"real_kb\\\")\\n\\n        kb_list = await get_knowledge_bases(user_id=active_user.id)\\n\\n        assert \\\"real_kb\\\" in kb_list\\n        # ``stale_dir`` has no DB row \u2192 it's a phantom and must not show up.\\n        assert \\\"stale_dir\\\" not in kb_list\\n\\n    async def test_get_knowledge_bases_skips_memory_base_associated_kbs(self, active_user):\\n        \\\"\\\"\\\"Memory-base-associated KBs are filtered out of the generic KB list.\\n\\n        Matches the listing endpoint's behavior \u2014 those KBs are exposed\\n        through the Memory Base APIs, not the generic KB dropdown.\\n        \\\"\\\"\\\"\\n        from langflow.api.utils import knowledge_base_service\\n\\n        await knowledge_base_service.create_record(user_id=active_user.id, name=\\\"regular_kb\\\")\\n        await knowledge_base_service.create_record(user_id=active_user.id, name=\\\"memory_kb\\\", source_types=[\\\"memory\\\"])\\n\\n        kb_list = await get_knowledge_bases(user_id=active_user.id)\\n\\n        assert \\\"regular_kb\\\" in kb_list\\n        assert \\\"memory_kb\\\" not in kb_list\\n\\n    async def test_update_build_config_populates_options(self, component_class, default_kwargs, active_user):\\n        from langflow.api.utils import knowledge_base_service\\n\\n        component = component_class(**default_kwargs)\\n\\n        await knowledge_base_service.create_record(user_id=active_user.id, name=\\\"kb1\\\")\\n        await knowledge_base_service.create_record(user_id=active_user.id, name=\\\"kb2\\\")\\n\\n        build_config = {\\\"knowledge_base\\\": {\\\"value\\\": \\\"test_kb\\\", \\\"options\\\": []}}\\n        result = await component.update_build_config(build_config, None, \\\"knowledge_base\\\")\\n\\n        assert \\\"test_kb\\\" in result[\\\"knowledge_base\\\"][\\\"options\\\"]\\n        assert \\\"kb1\\\" in result[\\\"knowledge_base\\\"][\\\"options\\\"]\\n        assert \\\"kb2\\\" in result[\\\"knowledge_base\\\"][\\\"options\\\"]\\n\\n    async def test_update_build_config_resets_stale_selection(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        build_config = {\\\"knowledge_base\\\": {\\\"value\\\": \\\"nonexistent_kb\\\", \\\"options\\\": [\\\"test_kb\\\"]}}\\n        result = await component.update_build_config(build_config, None, \\\"knowledge_base\\\")\\n        assert result[\\\"knowledge_base\\\"][\\\"value\\\"] is None\\n\\n    # ---- _get_kb_metadata --------------------------------------------\\n\\n    async def test_get_kb_metadata_happy_path(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        metadata = await component._get_kb_metadata()\\n        assert metadata[\\\"embedding_provider\\\"] == \\\"HuggingFace\\\"\\n        assert metadata[\\\"embedding_model\\\"] == \\\"sentence-transformers/all-MiniLM-L6-v2\\\"\\n        # The row carries the full selection dict so retrieval can pass it\\n        # straight to get_embeddings.\\n        assert \\\"model_selection\\\" in metadata\\n\\n    async def test_get_kb_metadata_without_a_row_returns_empty(\\n        self, component_class, default_kwargs, tmp_path, active_user\\n    ):\\n        \\\"\\\"\\\"A directory with no row yields no metadata \u2014 even with a sidecar present.\\n\\n        The sidecar is legacy data that only ``langflow reconcile-kb-from-disk``\\n        looks at; the component must not resurrect it.\\n        \\\"\\\"\\\"\\n        ghost = tmp_path / active_user.username / \\\"ghost\\\"\\n        ghost.mkdir(parents=True, exist_ok=True)\\n        (ghost / \\\"embedding_metadata.json\\\").write_text(\\n            json.dumps({\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"m\\\"})\\n        )\\n\\n        default_kwargs[\\\"knowledge_base\\\"] = \\\"ghost\\\"\\n        component = component_class(**default_kwargs)\\n        assert await component._get_kb_metadata() == {}\\n\\n    # ---- _resolve_model_selection ------------------------------------\\n\\n    def test_resolve_model_selection_uses_new_format(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        model = {\\\"name\\\": \\\"m\\\", \\\"provider\\\": \\\"p\\\", \\\"metadata\\\": {}}\\n        assert component._resolve_model_selection({\\\"model_selection\\\": model}) == [model]\\n\\n    def test_resolve_model_selection_accepts_list_shape(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        model = [{\\\"name\\\": \\\"m\\\", \\\"provider\\\": \\\"p\\\"}]\\n        assert component._resolve_model_selection({\\\"model_selection\\\": model}) == model\\n\\n    def test_resolve_model_selection_falls_back_to_catalog_lookup(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Fall back to catalog lookup for legacy KBs.\\n\\n        No ``model_selection`` field, just ``embedding_model`` and\\n        ``embedding_provider`` strings \u2014 retrieval has to look the\\n        model up in the current unified-models catalog.\\n        \\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        catalog_entry = {\\n            \\\"name\\\": \\\"text-embedding-3-small\\\",\\n            \\\"provider\\\": \\\"OpenAI\\\",\\n            \\\"metadata\\\": {\\\"embedding_class\\\": \\\"OpenAIEmbeddings\\\"},\\n        }\\n        with patch(\\n            \\\"lfx.components.files_and_knowledge.knowledge.get_embedding_model_options\\\",\\n            return_value=[catalog_entry],\\n        ):\\n            resolved = component._resolve_model_selection(\\n                {\\\"embedding_model\\\": \\\"text-embedding-3-small\\\", \\\"embedding_provider\\\": \\\"OpenAI\\\"}\\n            )\\n        assert resolved == [catalog_entry]\\n\\n    def test_resolve_model_selection_hydrates_missing_embedding_class_from_catalog(\\n        self, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Partial model_selection must be completed from the unified-models catalog.\\n\\n        Regression: KBs created through older frontends or third-party API\\n        clients sometimes persisted ``model_selection`` as just\\n        ``{name, provider}`` with an empty or missing ``metadata`` block.\\n        Retrieval would then fail with\\n        ``\\\"No embedding class defined in metadata for <model>\\\"`` even\\n        though the model is fully supported by the current runtime. The\\n        fix looks the model up by name in the catalog and merges the\\n        missing ``embedding_class`` / ``param_mapping`` entries.\\n        \\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        persisted = {\\\"name\\\": \\\"text-embedding-3-small\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}\\n        catalog_entry = {\\n            \\\"name\\\": \\\"text-embedding-3-small\\\",\\n            \\\"provider\\\": \\\"OpenAI\\\",\\n            \\\"metadata\\\": {\\n                \\\"embedding_class\\\": \\\"OpenAIEmbeddings\\\",\\n                \\\"param_mapping\\\": {\\\"api_key\\\": \\\"<mapped_openai_key>\\\", \\\"model\\\": \\\"model\\\"},\\n            },\\n        }\\n        with patch(\\n            \\\"lfx.components.files_and_knowledge.knowledge.get_embedding_model_options\\\",\\n            return_value=[catalog_entry],\\n        ):\\n            resolved = component._resolve_model_selection({\\\"model_selection\\\": persisted})\\n\\n        assert len(resolved) == 1\\n        resolved_metadata = resolved[0][\\\"metadata\\\"]\\n        # Missing fields were hydrated from the catalog\u2026\\n        assert resolved_metadata[\\\"embedding_class\\\"] == \\\"OpenAIEmbeddings\\\"\\n        assert resolved_metadata[\\\"param_mapping\\\"] == {\\n            \\\"api_key\\\": \\\"<mapped_openai_key>\\\",\\n            \\\"model\\\": \\\"model\\\",\\n        }\\n        # \u2026and the persisted top-level fields stay intact.\\n        assert resolved[0][\\\"name\\\"] == \\\"text-embedding-3-small\\\"\\n        assert resolved[0][\\\"provider\\\"] == \\\"OpenAI\\\"\\n\\n    def test_resolve_model_selection_preserves_existing_metadata_over_catalog(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Persisted metadata wins on conflict \u2014 catalog only fills gaps.\\n\\n        Guards against silent drift for users who customised\\n        ``param_mapping`` or chose a specific ``embedding_class`` per KB.\\n        \\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        persisted = {\\n            \\\"name\\\": \\\"text-embedding-3-small\\\",\\n            \\\"provider\\\": \\\"OpenAI\\\",\\n            \\\"metadata\\\": {\\n                \\\"embedding_class\\\": \\\"CustomOpenAIEmbeddings\\\",\\n                \\\"param_mapping\\\": {\\\"api_key\\\": \\\"<mapped_custom_key>\\\"},\\n            },\\n        }\\n        catalog_entry = {\\n            \\\"name\\\": \\\"text-embedding-3-small\\\",\\n            \\\"provider\\\": \\\"OpenAI\\\",\\n            \\\"metadata\\\": {\\n                \\\"embedding_class\\\": \\\"OpenAIEmbeddings\\\",\\n                \\\"param_mapping\\\": {\\\"api_key\\\": \\\"<mapped_openai_key>\\\"},\\n                \\\"extra_flag\\\": True,\\n            },\\n        }\\n        with patch(\\n            \\\"lfx.components.files_and_knowledge.knowledge.get_embedding_model_options\\\",\\n            return_value=[catalog_entry],\\n        ):\\n            resolved = component._resolve_model_selection({\\\"model_selection\\\": persisted})\\n\\n        # Existing entries win (hydration fills gaps only). Both\\n        # ``has_class`` and ``has_mapping`` are true on the persisted\\n        # side, so ``_hydrate_model_metadata`` short-circuits without\\n        # touching ``extra_flag`` either.\\n        assert resolved[0][\\\"metadata\\\"][\\\"embedding_class\\\"] == \\\"CustomOpenAIEmbeddings\\\"\\n        assert resolved[0][\\\"metadata\\\"][\\\"param_mapping\\\"] == {\\\"api_key\\\": \\\"<mapped_custom_key>\\\"}\\n        assert \\\"extra_flag\\\" not in resolved[0][\\\"metadata\\\"]\\n\\n    def test_resolve_model_selection_raises_when_legacy_model_unavailable(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        with (\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.knowledge.get_embedding_model_options\\\",\\n                return_value=[],\\n            ),\\n            pytest.raises(ValueError, match=\\\"no longer available\\\"),\\n        ):\\n            component._resolve_model_selection(\\n                {\\\"embedding_model\\\": \\\"text-embedding-ada-002\\\", \\\"embedding_provider\\\": \\\"OpenAI\\\"}\\n            )\\n\\n    def test_resolve_model_selection_raises_on_empty_metadata(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        with pytest.raises(ValueError, match=\\\"no embedding model recorded\\\"):\\n            component._resolve_model_selection({})\\n\\n    # ---- retrieve_data orchestration ---------------------------------\\n\\n    async def test_retrieve_data_missing_metadata_raises(self, component_class, default_kwargs, tmp_path, active_user):\\n        \\\"\\\"\\\"A KB with a directory but no row cannot be retrieved from.\\\"\\\"\\\"\\n        (tmp_path / active_user.username / \\\"rowless_kb\\\").mkdir(parents=True, exist_ok=True)\\n        default_kwargs[\\\"knowledge_base\\\"] = \\\"rowless_kb\\\"\\n\\n        component = component_class(**default_kwargs)\\n        with pytest.raises(ValueError, match=\\\"Metadata not found\\\"):\\n            await component.retrieve_data()\\n\\n    async def test_retrieve_data_missing_user_id_raises(self, component_class, default_kwargs):\\n        default_kwargs[\\\"_user_id\\\"] = None\\n        component = component_class(**default_kwargs)\\n        mock_vertex = MagicMock()\\n        mock_vertex.graph.user_id = None\\n        component._vertex = mock_vertex\\n\\n        with patch(\\\"lfx.components.files_and_knowledge.knowledge.session_scope\\\") as mock_session_scope:\\n            mock_session_scope.return_value.__aenter__ = AsyncMock(return_value=AsyncMock())\\n            mock_session_scope.return_value.__aexit__ = AsyncMock(return_value=False)\\n            with pytest.raises(ValueError, match=\\\"User ID is required\\\"):\\n                await component.retrieve_data()\\n\\n    async def test_retrieve_data_missing_user_record_raises(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        with (\\n            patch(\\\"lfx.components.files_and_knowledge.knowledge.session_scope\\\") as mock_session_scope,\\n            patch(\\n                \\\"langflow.services.database.models.user.crud.get_user_by_id\\\",\\n                return_value=None,\\n            ),\\n        ):\\n            mock_session_scope.return_value.__aenter__ = AsyncMock(return_value=AsyncMock())\\n            mock_session_scope.return_value.__aexit__ = AsyncMock(return_value=False)\\n            with pytest.raises(ValueError, match=r\\\"User with ID .* not found\\\"):\\n                await component.retrieve_data()\\n\\n    @pytest.mark.parametrize(\\\"knowledge_base\\\", [\\\"../../outside\\\", \\\"../victim/secret_kb\\\"])\\n    async def test_retrieve_data_rejects_paths_outside_the_current_user_directory(\\n        self, component_class, default_kwargs, active_user, knowledge_base\\n    ):\\n        \\\"\\\"\\\"A traversing KB *name* is refused when its path is resolved.\\n\\n        A name like this has no row, so retrieval normally stops at \\\"no\\n        metadata\\\" without ever building a path. Seeding a row for the traversing\\n        name is what forces path resolution to run \u2014 and it must still refuse.\\n        \\\"\\\"\\\"\\n        from langflow.api.utils import knowledge_base_service\\n\\n        await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=knowledge_base,\\n            model_selection={\\\"name\\\": \\\"m\\\", \\\"provider\\\": \\\"HuggingFace\\\"},\\n        )\\n        default_kwargs[\\\"knowledge_base\\\"] = knowledge_base\\n        component = component_class(**default_kwargs)\\n\\n        with pytest.raises(ValueError, match=\\\"KB path escapes root directory\\\"):\\n            await component.retrieve_data()\\n\\n    async def test_retrieve_data_routes_query_with_scores(\\n        self,\\n        component_class,\\n        default_kwargs,\\n        tmp_path,  # noqa: ARG002 \u2014 reserved for future side-effect assertions\\n        active_user,\\n    ):\\n        \\\"\\\"\\\"Score-carrying search path.\\n\\n        With a search_query set, retrieve_data asks the backend for\\n        scores so the UI can render a relevance column.\\n        \\\"\\\"\\\"\\n        default_kwargs[\\\"search_query\\\"] = \\\"find me\\\"\\n        component = component_class(**default_kwargs)\\n\\n        fake_doc = MagicMock()\\n        fake_doc.page_content = \\\"hit\\\"\\n        fake_doc.metadata = {\\\"source\\\": \\\"s1\\\"}\\n\\n        user_record = MagicMock()\\n        user_record.username = active_user.username\\n\\n        backend_instance = MagicMock()\\n        backend_instance.similarity_search = AsyncMock(return_value=[(fake_doc, 0.42)])\\n        backend_instance.teardown = AsyncMock()\\n\\n        with (\\n            patch(\\\"lfx.components.files_and_knowledge.knowledge.session_scope\\\") as mock_session_scope,\\n            patch(\\n                \\\"langflow.services.database.models.user.crud.get_user_by_id\\\",\\n                return_value=user_record,\\n            ),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.knowledge.get_embeddings\\\",\\n                return_value=MagicMock(),\\n            ),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.knowledge.create_backend\\\",\\n                return_value=backend_instance,\\n            ),\\n        ):\\n            mock_session_scope.return_value.__aenter__ = AsyncMock(return_value=AsyncMock())\\n            mock_session_scope.return_value.__aexit__ = AsyncMock(return_value=False)\\n\\n            result = await component.retrieve_data()\\n\\n        # similarity_search was called with_scores=True because\\n        # search_query is truthy.\\n        call_kwargs = backend_instance.similarity_search.await_args.kwargs\\n        assert call_kwargs[\\\"with_scores\\\"] is True\\n        assert call_kwargs[\\\"query\\\"] == \\\"find me\\\"\\n        assert call_kwargs[\\\"k\\\"] == default_kwargs[\\\"top_k\\\"]\\n        backend_instance.teardown.assert_awaited_once()\\n        assert len(result) == 1\\n\\n    async def test_retrieve_data_no_query_skips_scores(self, component_class, default_kwargs, active_user):\\n        \\\"\\\"\\\"No-query path skips scores.\\n\\n        With search_query empty, retrieve_data asks for a\\n        non-scored search so the sentinel zero isn't surfaced as a\\n        meaningful relevance value.\\n        \\\"\\\"\\\"\\n        default_kwargs[\\\"search_query\\\"] = \\\"\\\"\\n        component = component_class(**default_kwargs)\\n\\n        fake_doc = MagicMock()\\n        fake_doc.page_content = \\\"all\\\"\\n        fake_doc.metadata = {\\\"source\\\": \\\"any\\\"}\\n\\n        user_record = MagicMock()\\n        user_record.username = active_user.username\\n\\n        backend_instance = MagicMock()\\n        backend_instance.similarity_search = AsyncMock(return_value=[(fake_doc, 0.0)])\\n        backend_instance.teardown = AsyncMock()\\n\\n        with (\\n            patch(\\\"lfx.components.files_and_knowledge.knowledge.session_scope\\\") as mock_session_scope,\\n            patch(\\n                \\\"langflow.services.database.models.user.crud.get_user_by_id\\\",\\n                return_value=user_record,\\n            ),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.knowledge.get_embeddings\\\",\\n                return_value=MagicMock(),\\n            ),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.knowledge.create_backend\\\",\\n                return_value=backend_instance,\\n            ),\\n        ):\\n            mock_session_scope.return_value.__aenter__ = AsyncMock(return_value=AsyncMock())\\n            mock_session_scope.return_value.__aexit__ = AsyncMock(return_value=False)\\n\\n            result = await component.retrieve_data()\\n\\n        call_kwargs = backend_instance.similarity_search.await_args.kwargs\\n        assert call_kwargs[\\\"with_scores\\\"] is False\\n        backend_instance.teardown.assert_awaited_once()\\n        assert len(result) == 1\\n\\n    async def test_retrieve_data_tears_down_backend_on_error(self, component_class, default_kwargs, active_user):\\n        \\\"\\\"\\\"Teardown on error.\\n\\n        The backend's ``teardown`` must run even when\\n        ``similarity_search`` blows up \u2014 otherwise Chroma's SQLite\\n        handle leaks between tests.\\n        \\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n\\n        user_record = MagicMock()\\n        user_record.username = active_user.username\\n\\n        backend_instance = MagicMock()\\n        backend_instance.similarity_search = AsyncMock(side_effect=RuntimeError(\\\"boom\\\"))\\n        backend_instance.teardown = AsyncMock()\\n\\n        with (\\n            patch(\\\"lfx.components.files_and_knowledge.knowledge.session_scope\\\") as mock_session_scope,\\n            patch(\\n                \\\"langflow.services.database.models.user.crud.get_user_by_id\\\",\\n                return_value=user_record,\\n            ),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.knowledge.get_embeddings\\\",\\n                return_value=MagicMock(),\\n            ),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.knowledge.create_backend\\\",\\n                return_value=backend_instance,\\n            ),\\n        ):\\n            mock_session_scope.return_value.__aenter__ = AsyncMock(return_value=AsyncMock())\\n            mock_session_scope.return_value.__aexit__ = AsyncMock(return_value=False)\\n\\n            with pytest.raises(RuntimeError, match=\\\"boom\\\"):\\n                await component.retrieve_data()\\n\\n        backend_instance.teardown.assert_awaited_once()\\n\\n    async def test_retrieve_data_passes_model_selection_to_unified_models(\\n        self, component_class, default_kwargs, active_user\\n    ):\\n        \\\"\\\"\\\"Full ``model_selection`` is handed off unchanged.\\n\\n        The dict persisted at ingest time should land in\\n        ``get_embeddings`` exactly as-is \u2014 that's the whole point of\\n        the unified-models port.\\n        \\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n\\n        user_record = MagicMock()\\n        user_record.username = active_user.username\\n\\n        backend_instance = MagicMock()\\n        backend_instance.similarity_search = AsyncMock(return_value=[])\\n        backend_instance.teardown = AsyncMock()\\n\\n        with (\\n            patch(\\\"lfx.components.files_and_knowledge.knowledge.session_scope\\\") as mock_session_scope,\\n            patch(\\n                \\\"langflow.services.database.models.user.crud.get_user_by_id\\\",\\n                return_value=user_record,\\n            ),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.knowledge.get_embeddings\\\",\\n                return_value=MagicMock(),\\n            ) as mock_get_embeddings,\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.knowledge.create_backend\\\",\\n                return_value=backend_instance,\\n            ),\\n        ):\\n            mock_session_scope.return_value.__aenter__ = AsyncMock(return_value=AsyncMock())\\n            mock_session_scope.return_value.__aexit__ = AsyncMock(return_value=False)\\n\\n            await component.retrieve_data()\\n\\n        # get_embeddings receives the full list-wrapped selection +\\n        # the chunk_size persisted alongside it.\\n        call_kwargs = mock_get_embeddings.call_args.kwargs\\n        assert isinstance(call_kwargs[\\\"model\\\"], list)\\n        assert call_kwargs[\\\"model\\\"][0][\\\"name\\\"] == \\\"sentence-transformers/all-MiniLM-L6-v2\\\"\\n        assert call_kwargs[\\\"chunk_size\\\"] == 1000\\n        assert call_kwargs[\\\"user_id\\\"] == default_kwargs[\\\"_user_id\\\"]\\n\\n    # ---- include_embeddings against a real Chroma backend ------------\\n\\n    async def _retrieve_against_real_kb(self, component_class, default_kwargs, active_user, docs):\\n        \\\"\\\"\\\"Populate a real Chroma KB with ``docs`` then run ``retrieve_data``.\\n\\n        Uses an in-process Chroma backend (no mocks for the vector store) so the\\n        embedding-join path \u2014 ``similarity_search`` + ``iter_documents`` \u2014 is\\n        exercised end to end. Only the user/session/path/embedding-config plumbing\\n        is patched, mirroring the other ``retrieve_data`` tests in this module.\\n        \\\"\\\"\\\"\\n        kb_path = Path(default_kwargs[\\\"kb_root_path\\\"]) / active_user.username / default_kwargs[\\\"knowledge_base\\\"]\\n        kb_path.mkdir(parents=True, exist_ok=True)\\n        embeddings = _DeterministicEmbeddings()\\n\\n        # Pre-populate the KB through the real backend, then tear it down so the\\n        # retrieval pass opens its own client (matches production lifecycle).\\n        seed_backend = ChromaLocalBackend(\\n            kb_name=default_kwargs[\\\"knowledge_base\\\"],\\n            kb_path=kb_path,\\n            embedding_function=embeddings,\\n        )\\n        try:\\n            await seed_backend.add_documents(docs)\\n        finally:\\n            await seed_backend.teardown()\\n\\n        def _make_backend(*_args, **kwargs):\\n            return ChromaLocalBackend(\\n                kb_name=kwargs.get(\\\"kb_name\\\", default_kwargs[\\\"knowledge_base\\\"]),\\n                kb_path=kwargs.get(\\\"kb_path\\\", kb_path),\\n                embedding_function=embeddings,\\n            )\\n\\n        user_record = MagicMock()\\n        user_record.username = active_user.username\\n\\n        component = component_class(**default_kwargs)\\n        with (\\n            patch(\\\"lfx.components.files_and_knowledge.knowledge.session_scope\\\") as mock_session_scope,\\n            patch(\\n                \\\"langflow.services.database.models.user.crud.get_user_by_id\\\",\\n                return_value=user_record,\\n            ),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.knowledge.get_embeddings\\\",\\n                return_value=embeddings,\\n            ),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.knowledge.create_backend\\\",\\n                side_effect=_make_backend,\\n            ),\\n        ):\\n            mock_session_scope.return_value.__aenter__ = AsyncMock(return_value=AsyncMock())\\n            mock_session_scope.return_value.__aexit__ = AsyncMock(return_value=False)\\n            return await component.retrieve_data()\\n\\n    async def test_include_embeddings_populates_for_upload_style_kb(self, component_class, default_kwargs, active_user):\\n        \\\"\\\"\\\"Regression: ``include_embeddings`` must work for upload-populated KBs.\\n\\n        Chunks ingested via direct file upload (``KBIngestionHelper``) carry no\\n        ``_id`` metadata key. The retrieval embedding-join used to key solely on\\n        ``_id``, so every such KB returned ``_embeddings: None``. The join now\\n        falls back to page content, so the vectors resolve.\\n        \\\"\\\"\\\"\\n        default_kwargs[\\\"search_query\\\"] = \\\"chunk 1 text\\\"\\n        default_kwargs[\\\"include_embeddings\\\"] = True\\n\\n        # Upload-style metadata \u2014 note the absence of any ``_id`` key.\\n        docs = [\\n            Document(\\n                page_content=f\\\"chunk {i} text\\\",\\n                metadata={\\\"source\\\": \\\"f.txt\\\", \\\"file_name\\\": \\\"f.txt\\\", \\\"chunk_index\\\": i},\\n            )\\n            for i in range(3)\\n        ]\\n\\n        result = await self._retrieve_against_real_kb(component_class, default_kwargs, active_user, docs)\\n\\n        rows = result.to_dict(\\\"records\\\")\\n        assert len(rows) == 3\\n        for row in rows:\\n            assert \\\"_embeddings\\\" in row\\n            assert isinstance(row[\\\"_embeddings\\\"], list)\\n            assert len(row[\\\"_embeddings\\\"]) == _DeterministicEmbeddings.DIMENSION\\n\\n    async def test_include_embeddings_populates_with_id_metadata(self, component_class, default_kwargs, active_user):\\n        \\\"\\\"\\\"The ``_id``-keyed path (component-driven ingestion) keeps working.\\\"\\\"\\\"\\n        default_kwargs[\\\"search_query\\\"] = \\\"chunk 1 text\\\"\\n        default_kwargs[\\\"include_embeddings\\\"] = True\\n\\n        docs = [\\n            Document(\\n                page_content=f\\\"chunk {i} text\\\",\\n                metadata={\\\"_id\\\": hashlib.sha256(f\\\"chunk {i} text\\\".encode()).hexdigest(), \\\"source\\\": \\\"s\\\"},\\n            )\\n            for i in range(3)\\n        ]\\n\\n        result = await self._retrieve_against_real_kb(component_class, default_kwargs, active_user, docs)\\n\\n        rows = result.to_dict(\\\"records\\\")\\n        assert len(rows) == 3\\n        for row in rows:\\n            assert isinstance(row[\\\"_embeddings\\\"], list)\\n            assert len(row[\\\"_embeddings\\\"]) == _DeterministicEmbeddings.DIMENSION\\n\\n    async def test_include_embeddings_disabled_omits_embeddings(self, component_class, default_kwargs, active_user):\\n        \\\"\\\"\\\"With the flag off, no ``_embeddings`` column is added.\\\"\\\"\\\"\\n        default_kwargs[\\\"search_query\\\"] = \\\"chunk 1 text\\\"\\n        default_kwargs[\\\"include_embeddings\\\"] = False\\n\\n        docs = [\\n            Document(page_content=f\\\"chunk {i} text\\\", metadata={\\\"source\\\": \\\"f.txt\\\", \\\"chunk_index\\\": i}) for i in range(3)\\n        ]\\n\\n        result = await self._retrieve_against_real_kb(component_class, default_kwargs, active_user, docs)\\n\\n        rows = result.to_dict(\\\"records\\\")\\n        assert len(rows) == 3\\n        for row in rows:\\n            assert \\\"_embeddings\\\" not in row\\n\\n\\nclass TestEmbeddingMatchKey:\\n    \\\"\\\"\\\"Unit coverage for the ``_id``-or-content join key used by the embedding merge.\\\"\\\"\\\"\\n\\n    def test_prefers_id_when_present(self):\\n        from lfx.components.files_and_knowledge.knowledge import _embedding_match_key\\n\\n        assert _embedding_match_key(\\\"some text\\\", {\\\"_id\\\": \\\"abc\\\", \\\"source\\\": \\\"s\\\"}) == (\\\"id\\\", \\\"abc\\\")\\n\\n    def test_falls_back_to_content_without_id(self):\\n        from lfx.components.files_and_knowledge.knowledge import _embedding_match_key\\n\\n        assert _embedding_match_key(\\\"some text\\\", {\\\"source\\\": \\\"s\\\"}) == (\\\"content\\\", \\\"some text\\\")\\n\\n    def test_handles_missing_metadata(self):\\n        from lfx.components.files_and_knowledge.knowledge import _embedding_match_key\\n\\n        assert _embedding_match_key(\\\"some text\\\", None) == (\\\"content\\\", \\\"some text\\\")\\n\\n    def test_id_and_content_key_spaces_do_not_collide(self):\\n        from lfx.components.files_and_knowledge.knowledge import _embedding_match_key\\n\\n        # A chunk whose content equals another chunk's _id must not cross-match.\\n        id_key = _embedding_match_key(\\\"payload\\\", {\\\"_id\\\": \\\"payload\\\"})\\n        content_key = _embedding_match_key(\\\"payload\\\", {})\\n        assert id_key != content_key\\n\\n\\nclass TestMetadataFilterHelpers:\\n    \\\"\\\"\\\"Direct coverage for the JSON-decode + match helpers.\\n\\n    Kept separate from the orchestration tests because the helpers don't\\n    need a component fixture or DB session \u2014 exercising them in isolation\\n    locks down the \\\"AND across keys, OR within values\\\" contract documented\\n    in the chunks endpoint, which retrieval mirrors.\\n    \\\"\\\"\\\"\\n\\n    def test_parse_returns_empty_when_unset(self):\\n        from lfx.components.files_and_knowledge.retrieval import _parse_metadata_filter\\n\\n        assert _parse_metadata_filter(None) == {}\\n        assert _parse_metadata_filter(\\\"\\\") == {}\\n        assert _parse_metadata_filter(\\\"   \\\") == {}\\n\\n    def test_parse_normalizes_scalar_to_list(self):\\n        from lfx.components.files_and_knowledge.retrieval import _parse_metadata_filter\\n\\n        assert _parse_metadata_filter('{\\\"tag\\\": \\\"invoice\\\"}') == {\\\"tag\\\": [\\\"invoice\\\"]}\\n\\n    def test_parse_preserves_array_values(self):\\n        from lfx.components.files_and_knowledge.retrieval import _parse_metadata_filter\\n\\n        assert _parse_metadata_filter('{\\\"tag\\\": [\\\"a\\\", \\\"b\\\"]}') == {\\\"tag\\\": [\\\"a\\\", \\\"b\\\"]}\\n\\n    def test_parse_swallows_invalid_json(self):\\n        from lfx.components.files_and_knowledge.retrieval import _parse_metadata_filter\\n\\n        # Malformed JSON returns an empty filter so retrieval falls back to\\n        # the unfiltered path rather than blowing up the canvas run.\\n        assert _parse_metadata_filter(\\\"{not-json\\\") == {}\\n\\n    def test_parse_swallows_non_dict(self):\\n        from lfx.components.files_and_knowledge.retrieval import _parse_metadata_filter\\n\\n        assert _parse_metadata_filter(\\\"[1, 2, 3]\\\") == {}\\n\\n    def test_chunk_match_requires_every_key(self):\\n        import json\\n\\n        from lfx.components.files_and_knowledge.retrieval import _chunk_matches_filter\\n\\n        meta = {\\\"source_metadata\\\": json.dumps({\\\"tag\\\": \\\"invoice\\\", \\\"year\\\": \\\"2026\\\"})}\\n        assert _chunk_matches_filter(meta, {\\\"tag\\\": [\\\"invoice\\\"], \\\"year\\\": [\\\"2026\\\"]}) is True\\n        assert _chunk_matches_filter(meta, {\\\"tag\\\": [\\\"report\\\"]}) is False\\n        assert _chunk_matches_filter(meta, {\\\"tag\\\": [\\\"invoice\\\"], \\\"owner\\\": [\\\"alice\\\"]}) is False\\n\\n    def test_chunk_match_array_value(self):\\n        import json\\n\\n        from lfx.components.files_and_knowledge.retrieval import _chunk_matches_filter\\n\\n        meta = {\\\"source_metadata\\\": json.dumps({\\\"tag\\\": [\\\"invoice\\\", \\\"audit\\\"]})}\\n        # Array stored, scalar filter \u2014 overlap returns True.\\n        assert _chunk_matches_filter(meta, {\\\"tag\\\": [\\\"audit\\\"]}) is True\\n        # Array stored, multi-select filter \u2014 any overlap returns True.\\n        assert _chunk_matches_filter(meta, {\\\"tag\\\": [\\\"report\\\", \\\"audit\\\"]}) is True\\n\\n    def test_chunk_match_missing_metadata_is_false(self):\\n        from lfx.components.files_and_knowledge.retrieval import _chunk_matches_filter\\n\\n        assert _chunk_matches_filter({}, {\\\"tag\\\": [\\\"invoice\\\"]}) is False\\n        assert _chunk_matches_filter(None, {\\\"tag\\\": [\\\"invoice\\\"]}) is False\\n\\n    def test_chunk_match_empty_filter_passes_through(self):\\n        from lfx.components.files_and_knowledge.retrieval import _chunk_matches_filter\\n\\n        assert _chunk_matches_filter({\\\"source_metadata\\\": \\\"{}\\\"}, {}) is True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/flow_controls/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/flow_controls/test_conditional_router.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8a13c523a6cdf9b92f1e06fff7347e1e47b7706829d51388e5c374b543bc2b36\",\"content\":\"from unittest.mock import MagicMock, PropertyMock, patch\\n\\nimport pytest\\nfrom lfx.components.flow_controls.conditional_router import ConditionalRouterComponent\\nfrom lfx.schema.message import Message\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestConditionalRouterComponent(ComponentTestBaseWithoutClient):\\n    \\\"\\\"\\\"Test cases for ConditionalRouterComponent.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return ConditionalRouterComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"input_text\\\": \\\"test input\\\",\\n            \\\"operator\\\": \\\"equals\\\",\\n            \\\"match_text\\\": \\\"test input\\\",\\n            \\\"case_sensitive\\\": True,\\n            \\\"true_case_message\\\": Message(text=\\\"true result\\\"),\\n            \\\"false_case_message\\\": Message(text=\\\"false result\\\"),\\n            \\\"max_iterations\\\": 10,\\n            \\\"default_route\\\": \\\"true_result\\\",\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    async def test_component_initialization(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test proper initialization of ConditionalRouterComponent.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert component.display_name == \\\"If-Else\\\"\\n        assert \\\"Routes an input message\\\" in component.description\\n        assert component.name == \\\"ConditionalRouter\\\"\\n        assert component.icon == \\\"split\\\"\\n        # Test private iteration tracking attribute\\n        assert hasattr(component, \\\"_ConditionalRouterComponent__iteration_updated\\\")\\n        assert component._ConditionalRouterComponent__iteration_updated is False\\n\\n    async def test_inputs_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that inputs are properly configured.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        expected_inputs = [\\n            \\\"input_text\\\",\\n            \\\"operator\\\",\\n            \\\"match_text\\\",\\n            \\\"case_sensitive\\\",\\n            \\\"true_case_message\\\",\\n            \\\"false_case_message\\\",\\n            \\\"max_iterations\\\",\\n            \\\"default_route\\\",\\n        ]\\n\\n        assert len(component.inputs) == len(expected_inputs)\\n        input_names = [inp.name for inp in component.inputs]\\n\\n        for expected_input in expected_inputs:\\n            assert expected_input in input_names\\n\\n    async def test_outputs_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that outputs are properly configured.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert len(component.outputs) == 2\\n        output_names = [out.name for out in component.outputs]\\n        assert \\\"true_result\\\" in output_names\\n        assert \\\"false_result\\\" in output_names\\n\\n    async def test_pre_run_setup(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test _pre_run_setup method.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component._ConditionalRouterComponent__iteration_updated = True\\n        component._pre_run_setup()\\n        assert component._ConditionalRouterComponent__iteration_updated is False\\n\\n    @pytest.mark.parametrize(\\n        (\\\"input_text\\\", \\\"match_text\\\", \\\"operator\\\", \\\"case_sensitive\\\", \\\"expected\\\"),\\n        [\\n            # Equals tests\\n            (\\\"hello\\\", \\\"hello\\\", \\\"equals\\\", True, True),\\n            (\\\"hello\\\", \\\"Hello\\\", \\\"equals\\\", True, False),\\n            (\\\"hello\\\", \\\"Hello\\\", \\\"equals\\\", False, True),\\n            (\\\"hello\\\", \\\"world\\\", \\\"equals\\\", False, False),\\n            # Not equals tests\\n            (\\\"hello\\\", \\\"world\\\", \\\"not equals\\\", True, True),\\n            (\\\"hello\\\", \\\"hello\\\", \\\"not equals\\\", True, False),\\n            (\\\"Hello\\\", \\\"hello\\\", \\\"not equals\\\", False, False),\\n            # Contains tests\\n            (\\\"hello world\\\", \\\"world\\\", \\\"contains\\\", True, True),\\n            (\\\"hello world\\\", \\\"World\\\", \\\"contains\\\", True, False),\\n            (\\\"hello world\\\", \\\"World\\\", \\\"contains\\\", False, True),\\n            (\\\"hello world\\\", \\\"foo\\\", \\\"contains\\\", True, False),\\n            # Starts with tests\\n            (\\\"hello world\\\", \\\"hello\\\", \\\"starts with\\\", True, True),\\n            (\\\"hello world\\\", \\\"Hello\\\", \\\"starts with\\\", True, False),\\n            (\\\"hello world\\\", \\\"Hello\\\", \\\"starts with\\\", False, True),\\n            (\\\"hello world\\\", \\\"world\\\", \\\"starts with\\\", True, False),\\n            # Ends with tests\\n            (\\\"hello world\\\", \\\"world\\\", \\\"ends with\\\", True, True),\\n            (\\\"hello world\\\", \\\"World\\\", \\\"ends with\\\", True, False),\\n            (\\\"hello world\\\", \\\"World\\\", \\\"ends with\\\", False, True),\\n            (\\\"hello world\\\", \\\"hello\\\", \\\"ends with\\\", True, False),\\n            # Regex tests - case sensitivity doesn't apply to regex\\n            (\\\"hello123\\\", r\\\"hello\\\\d+\\\", \\\"regex\\\", True, True),\\n            (\\\"hello123\\\", r\\\"Hello\\\\d+\\\", \\\"regex\\\", True, False),\\n            (\\\"hello123\\\", r\\\"Hello\\\\d+\\\", \\\"regex\\\", False, False),  # Still case sensitive for regex\\n            (\\\"hello\\\", r\\\"invalid[regex\\\", \\\"regex\\\", True, False),  # Invalid regex\\n            # Numeric comparison tests\\n            (\\\"10\\\", \\\"5\\\", \\\"greater than\\\", True, True),\\n            (\\\"5\\\", \\\"10\\\", \\\"greater than\\\", True, False),\\n            (\\\"10\\\", \\\"10\\\", \\\"greater than or equal\\\", True, True),\\n            (\\\"5\\\", \\\"10\\\", \\\"greater than or equal\\\", True, False),\\n            (\\\"5\\\", \\\"10\\\", \\\"less than\\\", True, True),\\n            (\\\"10\\\", \\\"5\\\", \\\"less than\\\", True, False),\\n            (\\\"10\\\", \\\"10\\\", \\\"less than or equal\\\", True, True),\\n            (\\\"15\\\", \\\"10\\\", \\\"less than or equal\\\", True, False),\\n            # Invalid numeric comparison\\n            (\\\"abc\\\", \\\"10\\\", \\\"greater than\\\", True, False),\\n            (\\\"10\\\", \\\"abc\\\", \\\"less than\\\", True, False),\\n        ],\\n    )\\n    async def test_evaluate_condition(\\n        self, component_class, default_kwargs, input_text, match_text, operator, case_sensitive, expected\\n    ):\\n        \\\"\\\"\\\"Test evaluate_condition method with various inputs.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        result = component.evaluate_condition(input_text, match_text, operator, case_sensitive=case_sensitive)\\n        assert result == expected\\n\\n    async def test_evaluate_condition_unknown_operator(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test evaluate_condition with unknown operator.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        result = component.evaluate_condition(\\\"hello\\\", \\\"hello\\\", \\\"unknown_operator\\\", case_sensitive=True)\\n        assert result is False\\n\\n    async def test_iterate_and_stop_once_initial_call(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test iterate_and_stop_once method on initial call.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        # Set up component attributes\\n        component.max_iterations = 5\\n        component.default_route = \\\"false_result\\\"\\n\\n        # Mock the graph object with exclude_branch_conditionally method\\n        mock_graph = MagicMock()\\n        mock_exclude = MagicMock()\\n        mock_graph.exclude_branch_conditionally = mock_exclude\\n\\n        # Mock the context property and methods\\n        with (\\n            patch.object(type(component), \\\"ctx\\\", new_callable=dict),\\n            patch.object(component, \\\"_id\\\", \\\"test_id\\\"),\\n            patch.object(component, \\\"update_ctx\\\") as mock_update,\\n            patch.object(component, \\\"stop\\\") as mock_stop,\\n            patch.object(type(component), \\\"graph\\\", new_callable=PropertyMock, return_value=mock_graph),\\n        ):\\n            component.iterate_and_stop_once(\\\"false_result\\\")\\n\\n            mock_update.assert_called_once_with({\\\"test_id_iteration\\\": 1})\\n            mock_stop.assert_called_once_with(\\\"false_result\\\")\\n            mock_exclude.assert_called_once_with(\\\"test_id\\\", output_name=\\\"false_result\\\")\\n            assert component._ConditionalRouterComponent__iteration_updated is True\\n\\n    async def test_iterate_and_stop_once_max_iterations_reached(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test iterate_and_stop_once when max iterations are reached.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        # Set up component attributes\\n        component.max_iterations = 5\\n        component.default_route = \\\"false_result\\\"\\n\\n        # Mock the graph object with conditional exclusion tracking\\n        mock_graph = MagicMock()\\n        mock_graph.conditional_exclusion_sources = {}\\n        mock_graph.conditionally_excluded_vertices = set()\\n        mock_exclude = MagicMock()\\n        mock_graph.exclude_branch_conditionally = mock_exclude\\n\\n        # Mock ctx with existing iterations at the limit\\n        mock_ctx = {\\\"test_id_iteration\\\": 5}\\n        with (\\n            patch.object(type(component), \\\"ctx\\\", new_callable=lambda: mock_ctx),\\n            patch.object(component, \\\"_id\\\", \\\"test_id\\\"),\\n            patch.object(component, \\\"update_ctx\\\") as mock_update,\\n            patch.object(component, \\\"stop\\\") as mock_stop,\\n            patch.object(type(component), \\\"graph\\\", new_callable=PropertyMock, return_value=mock_graph),\\n        ):\\n            component.iterate_and_stop_once(\\\"false_result\\\")\\n\\n            mock_update.assert_called_once_with({\\\"test_id_iteration\\\": 6})\\n            # Should flip to opposite route when max iterations reached\\n            mock_stop.assert_called_once_with(\\\"true_result\\\")\\n            # exclude_branch_conditionally should NOT be called when breaking cycle\\n            mock_exclude.assert_not_called()\\n\\n    async def test_iterate_and_stop_once_already_updated(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test iterate_and_stop_once when already updated in this iteration.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        # Set up component state - when already updated, method should return early\\n        component._ConditionalRouterComponent__iteration_updated = True\\n\\n        # Mock required attributes and methods\\n        with (\\n            patch.object(component, \\\"_id\\\", \\\"test_id\\\"),\\n            patch.object(component, \\\"update_ctx\\\") as mock_update,\\n            patch.object(component, \\\"stop\\\") as mock_stop,\\n        ):\\n            component.iterate_and_stop_once(\\\"false_result\\\")\\n\\n            # When already updated, neither update_ctx nor stop should be called\\n            mock_update.assert_not_called()\\n            mock_stop.assert_not_called()\\n\\n    async def test_true_response_condition_true(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test true_response when condition evaluates to True.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.input_text = \\\"hello\\\"\\n        component.match_text = \\\"hello\\\"\\n        component.operator = \\\"equals\\\"\\n        component.case_sensitive = True\\n        component.true_case_message = Message(text=\\\"True case\\\")\\n\\n        with (\\n            patch.object(component, \\\"iterate_and_stop_once\\\") as mock_iterate,\\n            patch.object(type(component), \\\"ctx\\\", new_callable=dict),\\n            patch.object(component, \\\"_id\\\", \\\"test_id\\\"),\\n        ):\\n            result = component.true_response()\\n\\n            assert result == component.true_case_message\\n            assert component.status == component.true_case_message\\n            mock_iterate.assert_called_once_with(\\\"false_result\\\")\\n\\n    async def test_true_response_condition_false(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test true_response when condition evaluates to False.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.input_text = \\\"hello\\\"\\n        component.match_text = \\\"world\\\"\\n        component.operator = \\\"equals\\\"\\n        component.case_sensitive = True\\n\\n        with (\\n            patch.object(component, \\\"iterate_and_stop_once\\\") as mock_iterate,\\n            patch.object(type(component), \\\"ctx\\\", new_callable=dict),\\n            patch.object(component, \\\"_id\\\", \\\"test_id\\\"),\\n        ):\\n            result = component.true_response()\\n\\n            assert isinstance(result, Message)\\n            assert result.text == \\\"\\\"\\n            mock_iterate.assert_called_once_with(\\\"true_result\\\")\\n\\n    async def test_false_response_condition_false(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test false_response when condition evaluates to False.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.input_text = \\\"hello\\\"\\n        component.match_text = \\\"world\\\"\\n        component.operator = \\\"equals\\\"\\n        component.case_sensitive = True\\n        component.false_case_message = Message(text=\\\"False case\\\")\\n\\n        with patch.object(component, \\\"iterate_and_stop_once\\\") as mock_iterate:\\n            result = component.false_response()\\n\\n            assert result == component.false_case_message\\n            assert component.status == component.false_case_message\\n            mock_iterate.assert_called_once_with(\\\"true_result\\\")\\n\\n    async def test_false_response_condition_true(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test false_response when condition evaluates to True.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.input_text = \\\"hello\\\"\\n        component.match_text = \\\"hello\\\"\\n        component.operator = \\\"equals\\\"\\n        component.case_sensitive = True\\n\\n        with patch.object(component, \\\"iterate_and_stop_once\\\") as mock_iterate:\\n            result = component.false_response()\\n\\n            assert isinstance(result, Message)\\n            assert result.text == \\\"\\\"\\n            mock_iterate.assert_called_once_with(\\\"false_result\\\")\\n\\n    async def test_true_response_blank_case_message_falls_back_to_input_text(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Blank Case True should route the original Text Input on the true branch.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.input_text = \\\"passthrough text\\\"\\n        component.match_text = \\\"passthrough text\\\"\\n        component.operator = \\\"equals\\\"\\n        component.case_sensitive = True\\n        # Unset MessageInput resolves to an empty Message\\n        component.true_case_message = Message(text=\\\"\\\")\\n\\n        with (\\n            patch.object(component, \\\"iterate_and_stop_once\\\") as mock_iterate,\\n            patch.object(type(component), \\\"ctx\\\", new_callable=dict),\\n            patch.object(component, \\\"_id\\\", \\\"test_id\\\"),\\n        ):\\n            result = component.true_response()\\n\\n            assert isinstance(result, Message)\\n            assert result.text == \\\"passthrough text\\\"\\n            mock_iterate.assert_called_once_with(\\\"false_result\\\")\\n\\n    async def test_false_response_blank_case_message_falls_back_to_input_text(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Blank Case False should route the original Text Input on the false branch.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.input_text = \\\"passthrough text\\\"\\n        component.match_text = \\\"no match\\\"\\n        component.operator = \\\"equals\\\"\\n        component.case_sensitive = True\\n        # Unset MessageInput resolves to an empty Message\\n        component.false_case_message = Message(text=\\\"\\\")\\n\\n        with patch.object(component, \\\"iterate_and_stop_once\\\") as mock_iterate:\\n            result = component.false_response()\\n\\n            assert isinstance(result, Message)\\n            assert result.text == \\\"passthrough text\\\"\\n            mock_iterate.assert_called_once_with(\\\"true_result\\\")\\n\\n    async def test_true_response_preserves_override_with_files(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"An override Message with empty text but files must be preserved, not dropped.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.input_text = \\\"passthrough text\\\"\\n        component.match_text = \\\"passthrough text\\\"\\n        component.operator = \\\"equals\\\"\\n        component.case_sensitive = True\\n        # Empty text but a meaningful file payload\\n        override = Message(text=\\\"\\\", files=[\\\"x.png\\\"])\\n        component.true_case_message = override\\n\\n        with (\\n            patch.object(component, \\\"iterate_and_stop_once\\\") as mock_iterate,\\n            patch.object(type(component), \\\"ctx\\\", new_callable=dict),\\n            patch.object(component, \\\"_id\\\", \\\"test_id\\\"),\\n        ):\\n            result = component.true_response()\\n\\n            assert result is override\\n            assert result.files == [\\\"x.png\\\"]\\n            assert result.text != \\\"passthrough text\\\"\\n            mock_iterate.assert_called_once_with(\\\"false_result\\\")\\n\\n    async def test_false_response_preserves_override_with_content_blocks(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"An override Message with empty text but content blocks must be preserved, not dropped.\\\"\\\"\\\"\\n        from lfx.schema.content_block import ContentBlock\\n\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.input_text = \\\"passthrough text\\\"\\n        component.match_text = \\\"no match\\\"\\n        component.operator = \\\"equals\\\"\\n        component.case_sensitive = True\\n        # Empty text but a meaningful content-block payload\\n        override = Message(text=\\\"\\\", content_blocks=[ContentBlock(title=\\\"block\\\", contents=[])])\\n        component.false_case_message = override\\n\\n        with patch.object(component, \\\"iterate_and_stop_once\\\") as mock_iterate:\\n            result = component.false_response()\\n\\n            assert result is override\\n            assert len(result.content_blocks) == 1\\n            assert result.text != \\\"passthrough text\\\"\\n            mock_iterate.assert_called_once_with(\\\"true_result\\\")\\n\\n    async def test_true_response_string_case_message_override(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"A raw string override is wrapped and routed, not dropped.\\n\\n        ``MessageInput`` wraps user input into a ``Message`` on the validated graph path, but a raw\\n        ``str`` can still reach ``_resolve_case_message`` via direct/programmatic assignment (e.g.\\n        ``component.set(true_case_message=\\\"...\\\")``). The ``str`` branch is intentionally retained\\n        rather than dead, so it is exercised here.\\n        \\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.input_text = \\\"passthrough text\\\"\\n        component.match_text = \\\"passthrough text\\\"\\n        component.operator = \\\"equals\\\"\\n        component.case_sensitive = True\\n        component.true_case_message = \\\"literal string override\\\"\\n\\n        with (\\n            patch.object(component, \\\"iterate_and_stop_once\\\") as mock_iterate,\\n            patch.object(type(component), \\\"ctx\\\", new_callable=dict),\\n            patch.object(component, \\\"_id\\\", \\\"test_id\\\"),\\n        ):\\n            result = component.true_response()\\n\\n            assert isinstance(result, Message)\\n            assert result.text == \\\"literal string override\\\"\\n            assert result.text != \\\"passthrough text\\\"\\n            mock_iterate.assert_called_once_with(\\\"false_result\\\")\\n\\n    @pytest.mark.parametrize(\\n        (\\\"case_message\\\", \\\"expected_text\\\"),\\n        [\\n            (\\\"literal string override\\\", \\\"literal string override\\\"),  # non-empty str -> wrapped as Message\\n            (\\\"\\\", \\\"passthrough text\\\"),  # empty str -> falls back to input_text\\n            (None, \\\"passthrough text\\\"),  # unset / None -> falls back to input_text\\n        ],\\n    )\\n    async def test_resolve_case_message_str_and_none_fallback(\\n        self, component_class, default_kwargs, case_message, expected_text\\n    ):\\n        \\\"\\\"\\\"_resolve_case_message handles raw str and None defensively, falling back to input_text when blank.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.input_text = \\\"passthrough text\\\"\\n\\n        result = component._resolve_case_message(case_message)\\n\\n        assert isinstance(result, Message)\\n        assert result.text == expected_text\\n\\n    async def test_update_build_config_regex_operator(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test update_build_config when operator is regex.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        build_config = {\\\"case_sensitive\\\": {\\\"show\\\": True}}\\n\\n        result = component.update_build_config(build_config, \\\"regex\\\", \\\"operator\\\")\\n\\n        assert \\\"case_sensitive\\\" not in result\\n\\n    async def test_update_build_config_non_regex_operator(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test update_build_config when operator is not regex.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        build_config = {}\\n\\n        # Find the actual case_sensitive input in the component\\n        case_sensitive_input = next((inp for inp in component.inputs if inp.name == \\\"case_sensitive\\\"), None)\\n        assert case_sensitive_input is not None  # Ensure it exists\\n\\n        result = component.update_build_config(build_config, \\\"equals\\\", \\\"operator\\\")\\n\\n        # The method should add case_sensitive to build_config if it doesn't exist\\n        assert \\\"case_sensitive\\\" in result\\n        assert isinstance(result[\\\"case_sensitive\\\"], dict)\\n\\n    async def test_update_build_config_non_operator_field(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test update_build_config when field is not operator.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        build_config = {\\\"some_field\\\": \\\"value\\\"}\\n\\n        result = component.update_build_config(build_config, \\\"some_value\\\", \\\"some_field\\\")\\n\\n        assert result == build_config  # Should return unchanged\\n\\n    async def test_regex_error_handling(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that invalid regex patterns are handled gracefully.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        # Test with an invalid regex pattern\\n        result = component.evaluate_condition(\\\"test\\\", \\\"[invalid\\\", \\\"regex\\\", case_sensitive=True)\\n        assert result is False\\n\\n    async def test_numeric_comparison_edge_cases(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test numeric comparison with edge cases.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        # Float comparison\\n        result = component.evaluate_condition(\\\"10.5\\\", \\\"10\\\", \\\"greater than\\\", case_sensitive=True)\\n        assert result is True\\n\\n        # Negative numbers\\n        result = component.evaluate_condition(\\\"-5\\\", \\\"0\\\", \\\"less than\\\", case_sensitive=True)\\n        assert result is True\\n\\n        # Scientific notation - need to be more careful with floating point comparison\\n        result = component.evaluate_condition(\\\"100000.0\\\", \\\"100000.0\\\", \\\"equals\\\", case_sensitive=True)\\n        assert result is True\\n\\n    async def test_case_insensitive_operations(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that case insensitive operations work correctly for string operators.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        test_cases = [\\n            (\\\"Hello\\\", \\\"hello\\\", \\\"equals\\\", False, True),\\n            (\\\"Hello World\\\", \\\"WORLD\\\", \\\"contains\\\", False, True),\\n            (\\\"Hello World\\\", \\\"HELLO\\\", \\\"starts with\\\", False, True),\\n            (\\\"Hello World\\\", \\\"WORLD\\\", \\\"ends with\\\", False, True),\\n        ]\\n\\n        for input_text, match_text, operator, case_sensitive, expected in test_cases:\\n            result = component.evaluate_condition(input_text, match_text, operator, case_sensitive=case_sensitive)\\n            assert result == expected, (\\n                f\\\"Failed for {input_text} {operator} {match_text} (case_sensitive={case_sensitive})\\\"\\n            )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/flow_controls/test_data_conditional_router.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"74d2bd219527d03ae8e035dff71c8f2785a721c34fc14b3b337431426791f431\",\"content\":\"from unittest.mock import patch\\n\\nimport pytest\\nfrom langflow.schema.data import Data\\nfrom lfx.components.flow_controls.data_conditional_router import DataConditionalRouterComponent\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestDataConditionalRouterComponent(ComponentTestBaseWithoutClient):\\n    \\\"\\\"\\\"Test cases for DataConditionalRouterComponent.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return DataConditionalRouterComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"data_input\\\": None,\\n            \\\"key_name\\\": \\\"test_key\\\",\\n            \\\"operator\\\": \\\"equals\\\",\\n            \\\"compare_value\\\": \\\"test_value\\\",\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    async def test_component_initialization(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test proper initialization of DataConditionalRouterComponent.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert component.display_name == \\\"Condition\\\"\\n        assert \\\"Route Data object\\\" in component.description\\n        assert component.name == \\\"DataConditionalRouter\\\"\\n        assert component.icon == \\\"split\\\"\\n        assert component.legacy is True\\n\\n    async def test_inputs_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that inputs are properly configured.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert len(component.inputs) == 4\\n\\n        input_names = [inp.name for inp in component.inputs]\\n        expected_inputs = [\\\"data_input\\\", \\\"key_name\\\", \\\"operator\\\", \\\"compare_value\\\"]\\n        for expected_input in expected_inputs:\\n            assert expected_input in input_names\\n\\n        # Test data_input configuration\\n        data_input = next(inp for inp in component.inputs if inp.name == \\\"data_input\\\")\\n        assert data_input.is_list is True\\n\\n    async def test_outputs_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that outputs are properly configured.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert len(component.outputs) == 2\\n        output_names = [out.name for out in component.outputs]\\n        assert \\\"true_output\\\" in output_names\\n        assert \\\"false_output\\\" in output_names\\n\\n    @pytest.mark.parametrize(\\n        (\\\"item_value\\\", \\\"compare_value\\\", \\\"operator\\\", \\\"expected\\\"),\\n        [\\n            # Equals tests\\n            (\\\"hello\\\", \\\"hello\\\", \\\"equals\\\", True),\\n            (\\\"hello\\\", \\\"world\\\", \\\"equals\\\", False),\\n            # Not equals tests\\n            (\\\"hello\\\", \\\"world\\\", \\\"not equals\\\", True),\\n            (\\\"hello\\\", \\\"hello\\\", \\\"not equals\\\", False),\\n            # Contains tests\\n            (\\\"hello world\\\", \\\"world\\\", \\\"contains\\\", True),\\n            (\\\"hello world\\\", \\\"foo\\\", \\\"contains\\\", False),\\n            # Starts with tests\\n            (\\\"hello world\\\", \\\"hello\\\", \\\"starts with\\\", True),\\n            (\\\"hello world\\\", \\\"world\\\", \\\"starts with\\\", False),\\n            # Ends with tests\\n            (\\\"hello world\\\", \\\"world\\\", \\\"ends with\\\", True),\\n            (\\\"hello world\\\", \\\"hello\\\", \\\"ends with\\\", False),\\n        ],\\n    )\\n    async def test_compare_values(self, component_class, default_kwargs, item_value, compare_value, operator, expected):\\n        \\\"\\\"\\\"Test compare_values method with various operators.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        result = component.compare_values(item_value, compare_value, operator)\\n        assert result == expected\\n\\n    async def test_compare_values_boolean_validator(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test compare_values with boolean validator.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        result = component.compare_values(\\\"true\\\", \\\"\\\", \\\"boolean validator\\\")\\n        assert result is True\\n\\n        result = component.compare_values(\\\"false\\\", \\\"\\\", \\\"boolean validator\\\")\\n        assert result is False\\n\\n    async def test_compare_values_unknown_operator(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test compare_values with unknown operator.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        result = component.compare_values(\\\"hello\\\", \\\"hello\\\", \\\"unknown_operator\\\")\\n        assert result is False\\n\\n    @pytest.mark.parametrize(\\n        (\\\"value\\\", \\\"expected\\\"),\\n        [\\n            # Boolean values\\n            (True, True),\\n            (False, False),\\n            # String values\\n            (\\\"true\\\", True),\\n            (\\\"True\\\", True),\\n            (\\\"TRUE\\\", True),\\n            (\\\"1\\\", True),\\n            (\\\"yes\\\", True),\\n            (\\\"y\\\", True),\\n            (\\\"on\\\", True),\\n            (\\\"false\\\", False),\\n            (\\\"False\\\", False),\\n            (\\\"0\\\", False),\\n            (\\\"no\\\", False),\\n            (\\\"off\\\", False),\\n            # Other values\\n            (1, True),\\n            (0, False),\\n            ([], False),\\n            ([1], True),\\n            (\\\"\\\", False),\\n            (\\\"hello\\\", False),\\n        ],\\n    )\\n    async def test_parse_boolean(self, component_class, default_kwargs, value, expected):\\n        \\\"\\\"\\\"Test parse_boolean method with various input types.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        result = component.parse_boolean(value)\\n        assert result == expected\\n\\n    async def test_validate_input_valid_data(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test validate_input with valid Data object.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.key_name = \\\"test_key\\\"\\n        data_item = Data(data={\\\"test_key\\\": \\\"value\\\"})\\n\\n        result = component.validate_input(data_item)\\n        assert result is True\\n\\n    async def test_validate_input_invalid_type(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test validate_input with non-Data object.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.key_name = \\\"test_key\\\"\\n\\n        result = component.validate_input(\\\"not_data\\\")\\n        assert result is False\\n        assert component.status == \\\"Input is not a Data object\\\"\\n\\n    async def test_validate_input_missing_key(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test validate_input with missing key in Data object.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.key_name = \\\"missing_key\\\"\\n        data_item = Data(data={\\\"other_key\\\": \\\"value\\\"})\\n\\n        result = component.validate_input(data_item)\\n        assert result is False\\n        assert component.status == \\\"Key 'missing_key' not found in Data\\\"\\n\\n    async def test_process_single_data_boolean_validator(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test process_single_data with boolean validator.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.operator = \\\"boolean validator\\\"\\n        component.key_name = \\\"flag\\\"\\n        data_item = Data(data={\\\"flag\\\": True})\\n\\n        result = component.process_single_data(data_item)\\n        assert result is True\\n        assert \\\"Boolean validation of 'flag'\\\" in component.status\\n\\n    async def test_process_single_data_comparison_true(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test process_single_data with comparison that returns True.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.operator = \\\"equals\\\"\\n        component.key_name = \\\"name\\\"\\n        component.compare_value = \\\"test\\\"\\n        data_item = Data(data={\\\"name\\\": \\\"test\\\"})\\n\\n        result = component.process_single_data(data_item)\\n        assert result is True\\n        assert \\\"Condition met: name equals test\\\" in component.status\\n\\n    async def test_process_single_data_comparison_false(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test process_single_data with comparison that returns False.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.operator = \\\"equals\\\"\\n        component.key_name = \\\"name\\\"\\n        component.compare_value = \\\"test\\\"\\n        data_item = Data(data={\\\"name\\\": \\\"other\\\"})\\n\\n        result = component.process_single_data(data_item)\\n        assert result is False\\n        assert \\\"Condition not met: name equals test\\\" in component.status\\n\\n    async def test_process_data_single_valid_input_true(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test process_data with single valid input that evaluates to True.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.data_input = Data(data={\\\"key\\\": \\\"value\\\"})\\n        component.key_name = \\\"key\\\"\\n        component.operator = \\\"equals\\\"\\n        component.compare_value = \\\"value\\\"\\n\\n        with patch.object(component, \\\"stop\\\") as mock_stop:\\n            result = component.process_data()\\n\\n            assert result == component.data_input\\n            mock_stop.assert_called_once_with(\\\"false_output\\\")\\n\\n    async def test_process_data_single_valid_input_false(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test process_data with single valid input that evaluates to False.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.data_input = Data(data={\\\"key\\\": \\\"value\\\"})\\n        component.key_name = \\\"key\\\"\\n        component.operator = \\\"equals\\\"\\n        component.compare_value = \\\"other\\\"\\n\\n        with patch.object(component, \\\"stop\\\") as mock_stop:\\n            result = component.process_data()\\n\\n            assert result == component.data_input\\n            mock_stop.assert_called_once_with(\\\"true_output\\\")\\n\\n    async def test_process_data_single_invalid_input(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test process_data with single invalid input.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.data_input = Data(data={\\\"other_key\\\": \\\"value\\\"})\\n        component.key_name = \\\"key\\\"\\n\\n        result = component.process_data()\\n\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"error\\\"] == \\\"Key 'key' not found in Data\\\"\\n\\n    async def test_process_data_list_input_mixed_results(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test process_data with list input containing mixed results.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.data_input = [\\n            Data(data={\\\"key\\\": \\\"match\\\"}),\\n            Data(data={\\\"key\\\": \\\"no_match\\\"}),\\n            Data(data={\\\"key\\\": \\\"match\\\"}),\\n        ]\\n        component.key_name = \\\"key\\\"\\n        component.operator = \\\"equals\\\"\\n        component.compare_value = \\\"match\\\"\\n\\n        with patch.object(component, \\\"stop\\\") as mock_stop:\\n            result = component.process_data()\\n\\n            # Should return true_output (items that match)\\n            assert len(result) == 2\\n            assert all(item.data[\\\"key\\\"] == \\\"match\\\" for item in result)\\n            mock_stop.assert_called_once_with(\\\"false_output\\\")\\n\\n    async def test_process_data_list_input_no_matches(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test process_data with list input containing no matches.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.data_input = [\\n            Data(data={\\\"key\\\": \\\"no_match1\\\"}),\\n            Data(data={\\\"key\\\": \\\"no_match2\\\"}),\\n        ]\\n        component.key_name = \\\"key\\\"\\n        component.operator = \\\"equals\\\"\\n        component.compare_value = \\\"match\\\"\\n\\n        with patch.object(component, \\\"stop\\\") as mock_stop:\\n            result = component.process_data()\\n\\n            # Should return false_output (items that don't match)\\n            assert len(result) == 2\\n            mock_stop.assert_called_once_with(\\\"true_output\\\")\\n\\n    async def test_process_data_list_input_invalid_items(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test process_data with list input containing invalid items.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.data_input = [\\n            Data(data={\\\"other_key\\\": \\\"value\\\"}),  # Invalid - missing key\\n            Data(data={\\\"key\\\": \\\"match\\\"}),  # Valid\\n        ]\\n        component.key_name = \\\"key\\\"\\n        component.operator = \\\"equals\\\"\\n        component.compare_value = \\\"match\\\"\\n\\n        with patch.object(component, \\\"stop\\\") as mock_stop:\\n            result = component.process_data()\\n\\n            # Should only return the valid matching item\\n            assert len(result) == 1\\n            assert result[0].data[\\\"key\\\"] == \\\"match\\\"\\n            mock_stop.assert_called_once_with(\\\"false_output\\\")\\n\\n    async def test_update_build_config_boolean_validator(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test update_build_config when operator is boolean validator.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        build_config = {\\\"compare_value\\\": {\\\"show\\\": True, \\\"advanced\\\": False, \\\"value\\\": \\\"test\\\"}}\\n\\n        result = component.update_build_config(build_config, \\\"boolean validator\\\", \\\"operator\\\")\\n\\n        assert result[\\\"compare_value\\\"][\\\"show\\\"] is False\\n        assert result[\\\"compare_value\\\"][\\\"advanced\\\"] is True\\n        assert result[\\\"compare_value\\\"][\\\"value\\\"] is None\\n\\n    async def test_update_build_config_non_boolean_validator(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test update_build_config when operator is not boolean validator.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        build_config = {\\\"compare_value\\\": {\\\"show\\\": False, \\\"advanced\\\": True}}\\n\\n        result = component.update_build_config(build_config, \\\"equals\\\", \\\"operator\\\")\\n\\n        assert result[\\\"compare_value\\\"][\\\"show\\\"] is True\\n        assert result[\\\"compare_value\\\"][\\\"advanced\\\"] is False\\n\\n    async def test_update_build_config_non_operator_field(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test update_build_config when field is not operator.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        build_config = {\\\"some_field\\\": \\\"value\\\"}\\n\\n        result = component.update_build_config(build_config, \\\"some_value\\\", \\\"some_field\\\")\\n\\n        assert result == build_config  # Should return unchanged\\n\\n    async def test_process_data_empty_list(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test process_data with empty list input.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.data_input = []\\n        component.key_name = \\\"key\\\"\\n        component.operator = \\\"equals\\\"\\n        component.compare_value = \\\"value\\\"\\n\\n        with patch.object(component, \\\"stop\\\") as mock_stop:\\n            result = component.process_data()\\n\\n            assert result == []\\n            mock_stop.assert_called_once_with(\\\"true_output\\\")\\n\\n    async def test_numeric_value_handling(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that numeric values are properly converted to strings for comparison.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.operator = \\\"equals\\\"\\n        component.key_name = \\\"number\\\"\\n        component.compare_value = \\\"42\\\"\\n        data_item = Data(data={\\\"number\\\": 42})\\n\\n        result = component.process_single_data(data_item)\\n        assert result is True\\n\\n    async def test_none_value_handling(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test handling of None values in data.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.operator = \\\"boolean validator\\\"\\n        component.key_name = \\\"nullable\\\"\\n        data_item = Data(data={\\\"nullable\\\": None})\\n\\n        result = component.process_single_data(data_item)\\n        assert result is False  # None should be falsy\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/flow_controls/test_flow_tool.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c75f32ffc90f38a0b19dc7d06469a8c1f92f5806743b6d91ea742f39b812c541\",\"content\":\"from unittest.mock import patch\\n\\nimport pytest\\nfrom lfx.components.flow_controls.flow_tool import FlowToolComponent\\nfrom lfx.schema.data import Data\\n\\nfrom tests.base import ComponentTestBaseWithClient\\n\\n\\nclass TestFlowToolComponent(ComponentTestBaseWithClient):\\n    \\\"\\\"\\\"Test cases for FlowToolComponent.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return FlowToolComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"flow_name\\\": \\\"test_flow\\\",\\n            \\\"tool_name\\\": \\\"test_tool\\\",\\n            \\\"tool_description\\\": \\\"Test tool description\\\",\\n            \\\"return_direct\\\": False,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    async def test_component_initialization(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test proper initialization of FlowToolComponent.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert component.display_name == \\\"Flow as Tool\\\"\\n        assert \\\"Construct a Tool from a function that runs the loaded Flow\\\" in component.description\\n        assert component.name == \\\"FlowTool\\\"\\n        assert component.icon == \\\"hammer\\\"\\n        assert component.legacy is True\\n        assert component.trace_type == \\\"tool\\\"\\n\\n    async def test_field_order_configuration(self):\\n        \\\"\\\"\\\"Test field_order configuration.\\\"\\\"\\\"\\n        expected_order = [\\\"flow_name\\\", \\\"name\\\", \\\"description\\\", \\\"return_direct\\\"]\\n        # field_order is a class attribute\\n        assert FlowToolComponent.field_order == expected_order\\n\\n    async def test_inputs_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that inputs are properly configured.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        expected_inputs = {\\\"flow_name\\\", \\\"tool_name\\\", \\\"tool_description\\\", \\\"return_direct\\\"}\\n        input_names = {inp.name for inp in component.inputs}\\n\\n        assert expected_inputs.issubset(input_names)\\n\\n        # Test flow_name input configuration\\n        flow_name_input = next(inp for inp in component.inputs if inp.name == \\\"flow_name\\\")\\n        assert flow_name_input.display_name == \\\"Flow Name\\\"\\n        assert flow_name_input.refresh_button is True\\n\\n        # Test return_direct input configuration\\n        return_direct_input = next(inp for inp in component.inputs if inp.name == \\\"return_direct\\\")\\n        assert return_direct_input.advanced is True\\n\\n    async def test_outputs_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that outputs are properly configured.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert len(component.outputs) == 1\\n\\n        output = component.outputs[0]\\n        assert output.name == \\\"api_build_tool\\\"\\n        assert output.display_name == \\\"Tool\\\"\\n        assert output.method == \\\"build_tool\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_get_flow_names(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test get_flow_names method.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        mock_flows = [\\n            Data(data={\\\"name\\\": \\\"Flow 1\\\"}),\\n            Data(data={\\\"name\\\": \\\"Flow 2\\\"}),\\n            Data(data={\\\"name\\\": \\\"Flow 3\\\"}),\\n        ]\\n\\n        with patch.object(component, \\\"alist_flows\\\", return_value=mock_flows):\\n            result = await component.get_flow_names()\\n\\n            assert result == [\\\"Flow 1\\\", \\\"Flow 2\\\", \\\"Flow 3\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_get_flow_names_empty_list(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test get_flow_names with empty flow list.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        with patch.object(component, \\\"alist_flows\\\", return_value=[]):\\n            result = await component.get_flow_names()\\n\\n            assert result == []\\n\\n    @pytest.mark.asyncio\\n    async def test_get_flow_found(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test get_flow method when flow is found.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        mock_flows = [\\n            Data(data={\\\"name\\\": \\\"Flow 1\\\"}),\\n            Data(data={\\\"name\\\": \\\"Target Flow\\\"}),\\n            Data(data={\\\"name\\\": \\\"Flow 3\\\"}),\\n        ]\\n\\n        with patch.object(component, \\\"alist_flows\\\", return_value=mock_flows):\\n            result = await component.get_flow(\\\"Target Flow\\\")\\n\\n            assert result == mock_flows[1]\\n            assert result.data[\\\"name\\\"] == \\\"Target Flow\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_get_flow_not_found(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test get_flow method when flow is not found.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        mock_flows = [\\n            Data(data={\\\"name\\\": \\\"Flow 1\\\"}),\\n            Data(data={\\\"name\\\": \\\"Flow 2\\\"}),\\n        ]\\n\\n        with patch.object(component, \\\"alist_flows\\\", return_value=mock_flows):\\n            result = await component.get_flow(\\\"Nonexistent Flow\\\")\\n\\n            assert result is None\\n\\n    @pytest.mark.asyncio\\n    async def test_get_flow_empty_list(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test get_flow method with empty flow list.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        with patch.object(component, \\\"alist_flows\\\", return_value=[]):\\n            result = await component.get_flow(\\\"Any Flow\\\")\\n\\n            assert result is None\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_flow_name(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test update_build_config when field_name is flow_name.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        build_config = {\\\"flow_name\\\": {\\\"options\\\": []}}\\n\\n        # The implementation assigns get_flow_names() directly (without await)\\n        # This means it assigns a coroutine object, which is actually a bug\\n        result = await component.update_build_config(build_config, \\\"some_value\\\", \\\"flow_name\\\")\\n\\n        # The options will contain a coroutine object due to the bug in the implementation\\n        import inspect\\n\\n        assert inspect.iscoroutine(result[\\\"flow_name\\\"][\\\"options\\\"])\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_other_field(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test update_build_config when field_name is not flow_name.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        build_config = {\\\"some_field\\\": \\\"value\\\"}\\n\\n        result = await component.update_build_config(build_config, \\\"some_value\\\", \\\"other_field\\\")\\n\\n        assert result == build_config  # Should return unchanged\\n\\n    @pytest.mark.asyncio\\n    async def test_build_tool_no_flow_name(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test build_tool raises error when flow_name is not provided.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        from lfx.base.tools.flow_tool import FlowTool\\n\\n        with (\\n            patch.object(component, \\\"_attributes\\\", {}),\\n            patch.object(FlowTool, \\\"model_rebuild\\\"),  # Mock to avoid Graph annotation error\\n            pytest.raises(ValueError, match=\\\"Flow name is required\\\"),\\n        ):\\n            await component.build_tool()\\n\\n    @pytest.mark.asyncio\\n    async def test_build_tool_empty_flow_name(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test build_tool raises error when flow_name is empty.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        from lfx.base.tools.flow_tool import FlowTool\\n\\n        with (\\n            patch.object(component, \\\"_attributes\\\", {\\\"flow_name\\\": \\\"\\\"}),\\n            patch.object(FlowTool, \\\"model_rebuild\\\"),  # Mock to avoid Graph annotation error\\n            pytest.raises(ValueError, match=\\\"Flow name is required\\\"),\\n        ):\\n            await component.build_tool()\\n\\n    @pytest.mark.asyncio\\n    async def test_build_tool_flow_not_found(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test build_tool raises error when flow is not found.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        from lfx.base.tools.flow_tool import FlowTool\\n\\n        with (\\n            patch.object(component, \\\"_attributes\\\", {\\\"flow_name\\\": \\\"Nonexistent Flow\\\"}),\\n            patch.object(component, \\\"get_flow\\\", return_value=None),\\n            patch.object(FlowTool, \\\"model_rebuild\\\"),  # Mock to avoid Graph annotation error\\n            pytest.raises(ValueError, match=\\\"Flow not found\\\"),\\n        ):\\n            await component.build_tool()\\n\\n    async def test_component_inheritance(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that component properly inherits from LCToolComponent.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        from lfx.base.langchain_utilities.model import LCToolComponent\\n\\n        assert isinstance(component, LCToolComponent)\\n\\n    async def test_component_legacy_status(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that component is properly marked as legacy.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert hasattr(component, \\\"legacy\\\")\\n        assert component.legacy is True\\n\\n    @pytest.mark.asyncio\\n    async def test_get_flow_names_handles_missing_name_field(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test get_flow_names handles flows without name field.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        mock_flows = [\\n            Data(data={\\\"name\\\": \\\"Flow 1\\\"}),\\n            Data(data={}),  # Missing name field\\n            Data(data={\\\"name\\\": \\\"Flow 3\\\"}),\\n        ]\\n\\n        with (\\n            patch.object(component, \\\"alist_flows\\\", return_value=mock_flows),\\n            pytest.raises(KeyError),\\n        ):\\n            await component.get_flow_names()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/flow_controls/test_human_input.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e0180a086951850176633d29b32529955613e5c13a794cb5e1fdeb6276aec65a\",\"content\":\"\\\"\\\"\\\"Unit tests for the HumanInput node (LE-1449) \u2014 config, outputs, rendering, registration.\\n\\nThe real background suspend/resume round-trip is covered by the integration test;\\nthese assert the pure component contract that does not need a running graph.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom types import SimpleNamespace\\nfrom unittest.mock import MagicMock\\n\\nimport pytest\\nfrom lfx.components.flow_controls.human_input import HumanInput\\nfrom lfx.schema.message import Message\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\ndef _wired(component, *, decision=None, run_id=\\\"job-1\\\"):\\n    \\\"\\\"\\\"Give the component a minimal graph context (id + injected decision) and a stop spy.\\n\\n    Mirrors the SmartRouter test convention: the framework seams ``stop`` and\\n    ``request_pause`` are mocked so the routing logic is asserted directly.\\n    \\\"\\\"\\\"\\n    component._id = \\\"human\\\"\\n    decisions = {f\\\"human:{run_id}\\\": decision} if decision is not None else {}\\n    graph = SimpleNamespace(\\n        run_id=run_id,\\n        human_input_decisions=decisions,\\n        request_pause=MagicMock(),\\n        # Connected by default: the node feeds a downstream consumer, so it pauses.\\n        successor_map={\\\"human\\\": [\\\"downstream\\\"]},\\n    )\\n    component._vertex = SimpleNamespace(graph=graph)  # self.graph resolves to self._vertex.graph\\n    component.stop = MagicMock()\\n    return component\\n\\n\\nclass TestHumanInputComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        return HumanInput\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\n            \\\"prompt\\\": \\\"Approve this?\\\",\\n            \\\"decisions\\\": [\\\"Approve\\\", \\\"Reject\\\"],\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        return []\\n\\n    def test_default_outputs_expose_branch_handles(self, component_class):\\n        \\\"\\\"\\\"A freshly created node must already carry branch outputs so handles render on drag.\\\"\\\"\\\"\\n        component = component_class()\\n        assert [o.name for o in component.outputs] == [\\\"branch_approve\\\", \\\"branch_reject\\\"]\\n\\n    def test_hitl_search_keywords_are_registered(self, component_class):\\n        \\\"\\\"\\\"The sidebar's metadata search does substring matching on ``metadata[\\\"keywords\\\"]``.\\n\\n        Fuse alone cannot surface this node for \\\"HITL\\\": its location penalty rejects\\n        matches deep inside the description (score ~0.4 > 0.2 threshold), so the\\n        keywords list is the mechanism that makes \\\"hitl\\\" find Human Input.\\n        \\\"\\\"\\\"\\n        keywords = component_class.metadata[\\\"keywords\\\"]\\n        assert \\\"hitl\\\" in keywords\\n        assert \\\"human-in-the-loop\\\" in keywords\\n\\n    def test_decisions_has_no_options_so_outputs_rebuild_on_load(self, component_class):\\n        \\\"\\\"\\\"Decisions must serialize with empty options so the frontend rebuilds outputs on load.\\n\\n        useFetchDataOnMount fires for a real_time_refresh field only when its options are\\n        empty-but-defined; re-adding options reintroduces the 'outputs revert to defaults\\n        after page refresh' bug.\\n        \\\"\\\"\\\"\\n        component = component_class()\\n        decisions = next(i for i in component.inputs if i.name == \\\"decisions\\\")\\n        assert decisions.options == []\\n        assert decisions.real_time_refresh is True\\n\\n    async def test_update_frontend_node_resyncs_branches_from_saved_decisions(self, component_class):\\n        \\\"\\\"\\\"Loading a saved flow rebuilds the branch outputs from the persisted User Choices.\\\"\\\"\\\"\\n        component = component_class()\\n        new_frontend_node = {\\n            \\\"template\\\": {\\n                \\\"decisions\\\": {\\\"value\\\": [\\\"Approve\\\", \\\"Reject\\\", \\\"Escalate\\\"]},\\n                \\\"enable_fallback\\\": {\\\"value\\\": True},\\n            },\\n            \\\"outputs\\\": [],\\n        }\\n        node = await component.update_frontend_node(new_frontend_node, dict(new_frontend_node))\\n        assert [o.name for o in node[\\\"outputs\\\"]] == [\\n            \\\"branch_approve\\\",\\n            \\\"branch_reject\\\",\\n            \\\"branch_escalate\\\",\\n            \\\"branch_fallback\\\",\\n        ]\\n\\n    def test_timeout_hidden_until_fallback_enabled(self, component_class):\\n        \\\"\\\"\\\"Timeout only matters with a fallback branch to reroute to, so it follows the toggle.\\\"\\\"\\\"\\n        component = component_class()\\n        build_config = {\\\"timeout\\\": {\\\"show\\\": False}}\\n        component.update_build_config(build_config, field_value=True, field_name=\\\"enable_fallback\\\")\\n        assert build_config[\\\"timeout\\\"][\\\"show\\\"] is True\\n        component.update_build_config(build_config, field_value=False, field_name=\\\"enable_fallback\\\")\\n        assert build_config[\\\"timeout\\\"][\\\"show\\\"] is False\\n\\n    @pytest.mark.parametrize(\\\"fallback_on\\\", [True, False])\\n    async def test_update_frontend_node_syncs_timeout_visibility(self, component_class, fallback_on):\\n        component = component_class()\\n        new_frontend_node = {\\n            \\\"template\\\": {\\n                \\\"decisions\\\": {\\\"value\\\": [\\\"Approve\\\"]},\\n                \\\"enable_fallback\\\": {\\\"value\\\": fallback_on},\\n                \\\"timeout\\\": {\\\"show\\\": not fallback_on},\\n            },\\n            \\\"outputs\\\": [],\\n        }\\n        node = await component.update_frontend_node(new_frontend_node, dict(new_frontend_node))\\n        assert node[\\\"template\\\"][\\\"timeout\\\"][\\\"show\\\"] is fallback_on\\n\\n    def test_two_decisions_yield_two_branches(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        node = component.update_outputs({\\\"outputs\\\": []}, \\\"decisions\\\", default_kwargs[\\\"decisions\\\"])\\n        assert [o.name for o in node[\\\"outputs\\\"]] == [\\\"branch_approve\\\", \\\"branch_reject\\\"]\\n\\n    def test_adding_an_action_adds_a_branch(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        actions = [\\\"Approve\\\", \\\"Reject\\\", \\\"Escalate\\\"]\\n        node = component.update_outputs({\\\"outputs\\\": []}, \\\"decisions\\\", actions)\\n        assert [o.name for o in node[\\\"outputs\\\"]] == [\\n            \\\"branch_approve\\\",\\n            \\\"branch_reject\\\",\\n            \\\"branch_escalate\\\",\\n        ]\\n\\n    def test_multiword_action_slugifies_branch_name(self, component_class):\\n        component = component_class(prompt=\\\"ok?\\\", decisions=[\\\"Request Changes\\\"])\\n        node = component.update_outputs({\\\"outputs\\\": []}, \\\"decisions\\\", component.decisions)\\n        assert node[\\\"outputs\\\"][0].name == \\\"branch_request_changes\\\"\\n        assert node[\\\"outputs\\\"][0].display_name == \\\"Request Changes\\\"\\n\\n    def test_y_n_and_menu_use_the_same_node(self, component_class):\\n        yn = component_class(prompt=\\\"ok?\\\", decisions=[\\\"Yes\\\", \\\"No\\\"])\\n        menu = component_class(prompt=\\\"pick\\\", decisions=[f\\\"Opt{i}\\\" for i in range(4)])\\n        yn_node = yn.update_outputs({\\\"outputs\\\": []}, \\\"decisions\\\", yn.decisions)\\n        menu_node = menu.update_outputs({\\\"outputs\\\": []}, \\\"decisions\\\", menu.decisions)\\n        assert len(yn_node[\\\"outputs\\\"]) == 2  # 2 branches\\n        assert len(menu_node[\\\"outputs\\\"]) == 4  # 4 branches\\n        assert all(o.method == \\\"route_branch\\\" for o in menu_node[\\\"outputs\\\"])\\n\\n    def test_enable_fallback_adds_a_fallback_branch(self, component_class):\\n        component = component_class(prompt=\\\"ok?\\\", decisions=[\\\"Approve\\\"], enable_fallback=True)\\n        node = component.update_outputs({\\\"outputs\\\": []}, \\\"enable_fallback\\\", True)  # noqa: FBT003\\n        assert [o.name for o in node[\\\"outputs\\\"]] == [\\\"branch_approve\\\", \\\"branch_fallback\\\"]\\n\\n    def test_timeout_seconds_from_value_and_unit(self, component_class):\\n        days = component_class(decisions=[\\\"Approve\\\"], timeout={\\\"value\\\": 3, \\\"unit\\\": \\\"Days\\\"})\\n        minutes = component_class(decisions=[\\\"Approve\\\"], timeout={\\\"value\\\": 10, \\\"unit\\\": \\\"Minutes\\\"})\\n        assert days._timeout_seconds() == 259200\\n        assert minutes._timeout_seconds() == 600\\n\\n    def test_pause_request_payload_shape(self, component_class):\\n        component = component_class(\\n            prompt=\\\"Refund this?\\\",\\n            decisions=[\\\"Approve\\\", \\\"Reject\\\"],\\n            timeout={\\\"value\\\": 2, \\\"unit\\\": \\\"Hours\\\"},\\n            enable_fallback=True,\\n        )\\n        request = component._pause_request()\\n        assert request[\\\"kind\\\"] == \\\"node_input\\\"\\n        assert request[\\\"prompt\\\"] == \\\"Refund this?\\\"\\n        assert request[\\\"allowed_decisions\\\"] == [\\\"approve\\\", \\\"reject\\\", \\\"fallback\\\"]\\n        assert [o[\\\"action_id\\\"] for o in request[\\\"options\\\"]] == [\\\"approve\\\", \\\"reject\\\"]\\n        assert request[\\\"timeout_seconds\\\"] == 7200\\n        assert request[\\\"fallback_action\\\"] == \\\"fallback\\\"\\n\\n    def test_registered_in_both_import_paths_same_class(self):\\n        from lfx.components.flow_controls import HumanInput as FlowControlsHumanInput\\n        from lfx.components.logic import HumanInput as LogicHumanInput\\n\\n        assert FlowControlsHumanInput is LogicHumanInput\\n        assert FlowControlsHumanInput.__name__ == \\\"HumanInput\\\"\\n\\n    def test_listed_in_component_index(self):\\n        import json\\n        from pathlib import Path\\n\\n        import lfx\\n\\n        index_path = Path(lfx.__file__).parent / \\\"_assets\\\" / \\\"component_index.json\\\"\\n        index = json.loads(index_path.read_text(encoding=\\\"utf-8\\\"))\\n        assert \\\"HumanInput\\\" in json.dumps(index)\\n\\n    def test_route_branch_with_decision_returns_content_and_stops_others(self, component_class):\\n        component = _wired(\\n            component_class(prompt=\\\"payload\\\", decisions=[\\\"Approve\\\", \\\"Reject\\\"]),\\n            decision={\\\"action_id\\\": \\\"approve\\\", \\\"values\\\": {}},\\n        )\\n        result = component.route_branch()\\n        assert isinstance(result, Message)\\n        assert result.text == \\\"payload\\\"\\n        component.stop.assert_any_call(\\\"branch_reject\\\")  # the non-chosen branch is stopped\\n        assert (\\\"branch_approve\\\",) not in [c.args for c in component.stop.call_args_list]\\n\\n    def test_reject_decision_stops_approve(self, component_class):\\n        component = _wired(\\n            component_class(prompt=\\\"x\\\", decisions=[\\\"Approve\\\", \\\"Reject\\\"]),\\n            decision={\\\"action_id\\\": \\\"reject\\\", \\\"values\\\": {}},\\n        )\\n        component.route_branch()\\n        component.stop.assert_any_call(\\\"branch_approve\\\")\\n\\n    def test_fallback_decision_routes_to_fallback_branch(self, component_class):\\n        component = _wired(\\n            component_class(prompt=\\\"x\\\", decisions=[\\\"Approve\\\", \\\"Reject\\\"], enable_fallback=True),\\n            decision={\\\"action_id\\\": \\\"fallback\\\", \\\"values\\\": {}},\\n        )\\n        component.route_branch()\\n        component.stop.assert_any_call(\\\"branch_approve\\\")\\n        component.stop.assert_any_call(\\\"branch_reject\\\")\\n        assert (\\\"branch_fallback\\\",) not in [c.args for c in component.stop.call_args_list]\\n\\n    def test_expired_decision_stops_every_branch(self, component_class):\\n        \\\"\\\"\\\"A timed-out answer with no fallback routes to the expired sentinel, so no branch survives.\\\"\\\"\\\"\\n        from lfx.run.hitl import EXPIRED_ACTION\\n\\n        component = _wired(\\n            component_class(prompt=\\\"x\\\", decisions=[\\\"Approve\\\", \\\"Reject\\\"]),\\n            decision={\\\"action_id\\\": EXPIRED_ACTION, \\\"values\\\": {}},\\n        )\\n        component.route_branch()\\n        stopped = {c.args[0] for c in component.stop.call_args_list}\\n        assert stopped == {\\\"branch_approve\\\", \\\"branch_reject\\\"}\\n\\n    def test_route_branch_without_decision_requests_pause(self, component_class):\\n        component = _wired(component_class(prompt=\\\"ok?\\\", decisions=[\\\"Approve\\\"]))\\n        result = component.route_branch()\\n        assert result.text == \\\"\\\"\\n        component.graph.request_pause.assert_called_once()\\n        _args, kwargs = component.graph.request_pause.call_args\\n        assert kwargs[\\\"reason\\\"] == \\\"human_input_required\\\"\\n        assert kwargs[\\\"data\\\"][\\\"kind\\\"] == \\\"node_input\\\"\\n\\n    def test_route_branch_disconnected_node_does_not_pause(self, component_class):\\n        \\\"\\\"\\\"A Human Input whose branches route nowhere must not pause the whole flow.\\n\\n        A node with no outgoing edges runs as an isolated start vertex; pausing it would\\n        suspend the entire run for a decision that goes nowhere \u2014 and, when an Agent in the\\n        same run has its own tool-approval pause, leave that pause unresolved on resume.\\n        \\\"\\\"\\\"\\n        component = _wired(component_class(prompt=\\\"ok?\\\", decisions=[\\\"Approve\\\"]))\\n        component.graph.successor_map = {}  # node feeds nothing downstream\\n        result = component.route_branch()\\n        component.graph.request_pause.assert_not_called()\\n        assert isinstance(result, Message)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/flow_controls/test_listen.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"40f9bb9fc277041fbcfd12260f1f0d35c37b8afc435b6bfa8c99baa479ff67b5\",\"content\":\"from unittest.mock import patch\\n\\nimport pytest\\nfrom langflow.schema.data import Data\\nfrom lfx.components.flow_controls.listen import ListenComponent\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestListenComponent(ComponentTestBaseWithoutClient):\\n    \\\"\\\"\\\"Test cases for ListenComponent.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return ListenComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"context_key\\\": \\\"test_key\\\",\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    async def test_component_initialization(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test proper initialization of ListenComponent.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert component.display_name == \\\"Listen\\\"\\n        assert component.description == \\\"A component to listen for a notification.\\\"\\n        assert component.name == \\\"Listen\\\"\\n        assert component.icon == \\\"Radio\\\"\\n        assert component.beta is True\\n\\n    async def test_inputs_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that inputs are properly configured.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert len(component.inputs) == 1\\n\\n        context_key_input = component.inputs[0]\\n        assert context_key_input.name == \\\"context_key\\\"\\n        assert context_key_input.display_name == \\\"Context Key\\\"\\n        assert context_key_input.required is True\\n        assert \\\"Message\\\" in context_key_input.input_types\\n\\n    async def test_outputs_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that outputs are properly configured.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert len(component.outputs) == 1\\n\\n        output = component.outputs[0]\\n        assert output.name == \\\"data\\\"\\n        assert output.display_name == \\\"JSON\\\"\\n        assert output.method == \\\"listen_for_data\\\"\\n        assert output.cache is False\\n\\n    async def test_listen_for_data_key_exists(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test listen_for_data when context key exists.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.context_key = \\\"test_key\\\"\\n        expected_data = Data(text=\\\"Hello World\\\")\\n\\n        with patch.object(type(component), \\\"ctx\\\", new_callable=lambda: {\\\"test_key\\\": expected_data}):\\n            result = component.listen_for_data()\\n\\n            assert result == expected_data\\n\\n    async def test_listen_for_data_key_does_not_exist(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test listen_for_data when context key does not exist.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.context_key = \\\"nonexistent_key\\\"\\n\\n        with patch.object(type(component), \\\"ctx\\\", new_callable=lambda: {\\\"other_key\\\": Data(text=\\\"Other data\\\")}):\\n            result = component.listen_for_data()\\n\\n            assert isinstance(result, Data)\\n            assert result.text == \\\"\\\"\\n\\n    async def test_listen_for_data_empty_context(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test listen_for_data with empty context.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.context_key = \\\"any_key\\\"\\n\\n        with patch.object(type(component), \\\"ctx\\\", new_callable=dict):\\n            result = component.listen_for_data()\\n\\n            assert isinstance(result, Data)\\n            assert result.text == \\\"\\\"\\n\\n    async def test_listen_for_data_none_context(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test listen_for_data with None context value.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.context_key = \\\"test_key\\\"\\n\\n        # When ctx contains the key but value is None, get() returns None\\n        with patch.object(type(component), \\\"ctx\\\", new_callable=lambda: {\\\"test_key\\\": None}):\\n            result = component.listen_for_data()\\n\\n            assert result is None\\n\\n    async def test_listen_for_data_with_text_data(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test listen_for_data with Data containing text.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.context_key = \\\"test_key\\\"\\n        test_data = Data(text=\\\"String content\\\")\\n\\n        with patch.object(type(component), \\\"ctx\\\", new_callable=lambda: {\\\"test_key\\\": test_data}):\\n            result = component.listen_for_data()\\n\\n            assert result == test_data\\n            assert result.text == \\\"String content\\\"\\n\\n    async def test_listen_for_data_with_dict_data(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test listen_for_data with Data containing dict.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.context_key = \\\"test_key\\\"\\n        test_data = Data(data={\\\"key\\\": \\\"value\\\"})\\n\\n        with patch.object(type(component), \\\"ctx\\\", new_callable=lambda: {\\\"test_key\\\": test_data}):\\n            result = component.listen_for_data()\\n\\n            assert result == test_data\\n            assert result.data == {\\\"key\\\": \\\"value\\\"}\\n\\n    async def test_listen_for_data_with_underscore_key(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test listen_for_data with underscore key names.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.context_key = \\\"key_with_underscores\\\"\\n        test_data = Data(text=\\\"Underscore data\\\")\\n\\n        with patch.object(type(component), \\\"ctx\\\", new_callable=lambda: {\\\"key_with_underscores\\\": test_data}):\\n            result = component.listen_for_data()\\n\\n            assert result == test_data\\n            assert result.text == \\\"Underscore data\\\"\\n\\n    async def test_listen_for_data_with_dash_key(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test listen_for_data with dash key names.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.context_key = \\\"key-with-dashes\\\"\\n        test_data = Data(text=\\\"Dash data\\\")\\n\\n        with patch.object(type(component), \\\"ctx\\\", new_callable=lambda: {\\\"key-with-dashes\\\": test_data}):\\n            result = component.listen_for_data()\\n\\n            assert result == test_data\\n            assert result.text == \\\"Dash data\\\"\\n\\n    async def test_listen_for_data_multiple_context_keys(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test listen_for_data retrieves only the specified key.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        mock_ctx = {\\n            \\\"key1\\\": Data(text=\\\"Data 1\\\"),\\n            \\\"key2\\\": Data(text=\\\"Data 2\\\"),\\n            \\\"key3\\\": Data(text=\\\"Data 3\\\"),\\n        }\\n\\n        component.context_key = \\\"key2\\\"  # Request specific key\\n\\n        with patch.object(type(component), \\\"ctx\\\", new_callable=lambda: mock_ctx):\\n            result = component.listen_for_data()\\n\\n            assert result == mock_ctx[\\\"key2\\\"]\\n            assert result.text == \\\"Data 2\\\"\\n\\n    async def test_listen_for_data_method_signature(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that listen_for_data method has correct signature and docstring.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert hasattr(component, \\\"listen_for_data\\\")\\n        assert callable(component.listen_for_data)\\n\\n        # Check docstring exists and contains key information\\n        docstring = component.listen_for_data.__doc__\\n        assert docstring is not None\\n        assert \\\"context key\\\" in docstring.lower()\\n        assert \\\"Data object\\\" in docstring\\n\\n    async def test_component_beta_status(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that component is properly marked as beta.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert hasattr(component, \\\"beta\\\")\\n        assert component.beta is True\\n\\n    async def test_component_inheritance(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that component properly inherits from Component base class.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        from langflow.custom import Component\\n\\n        assert isinstance(component, Component)\\n\\n    async def test_context_key_input_details(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test detailed configuration of context_key input.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        context_key_input = next(inp for inp in component.inputs if inp.name == \\\"context_key\\\")\\n\\n        assert context_key_input.display_name == \\\"Context Key\\\"\\n        assert \\\"key of the context to listen for\\\" in context_key_input.info\\n        assert context_key_input.required is True\\n        assert context_key_input.input_types == [\\\"Message\\\"]\\n\\n    async def test_output_method_mapping(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that output is correctly mapped to listen_for_data method.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        output = component.outputs[0]\\n        assert output.method == \\\"listen_for_data\\\"\\n        assert hasattr(component, output.method)\\n        assert callable(getattr(component, output.method))\\n\\n    async def test_empty_string_context_key(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test behavior with empty string context key.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.context_key = \\\"\\\"\\n\\n        # Mock the ctx property\\n        with patch.object(type(component), \\\"ctx\\\", new_callable=lambda: {\\\"\\\": Data(text=\\\"Empty key data\\\")}):\\n            result = component.listen_for_data()\\n            assert result.text == \\\"Empty key data\\\"\\n\\n    async def test_whitespace_context_key(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test behavior with whitespace context key.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.context_key = \\\"   \\\"\\n\\n        # Mock the ctx property\\n        with patch.object(type(component), \\\"ctx\\\", new_callable=lambda: {\\\"   \\\": Data(text=\\\"Whitespace key data\\\")}):\\n            result = component.listen_for_data()\\n            assert result.text == \\\"Whitespace key data\\\"\\n\\n    @pytest.mark.parametrize(\\n        \\\"context_value\\\",\\n        [\\n            Data(text=\\\"\\\"),  # Empty Data object\\n            Data(data={}),  # Empty data dict\\n            Data(),  # Default Data object\\n        ],\\n    )\\n    async def test_listen_for_data_empty_data_objects(self, component_class, default_kwargs, context_value):\\n        \\\"\\\"\\\"Test listen_for_data with various empty Data objects.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.context_key = \\\"test_key\\\"\\n\\n        # Mock the ctx property\\n        with patch.object(type(component), \\\"ctx\\\", new_callable=lambda: {\\\"test_key\\\": context_value}):\\n            result = component.listen_for_data()\\n            assert result == context_value\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/flow_controls/test_loop.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1ab47414628e2035ee4703d4eb8f090b6aaad5ec8175b678b9febd1628aac1ff\",\"content\":\"import json\\nfrom uuid import UUID\\n\\nimport orjson\\nimport pytest\\nfrom httpx import AsyncClient\\nfrom langflow.memory import aget_messages\\nfrom langflow.services.database.models.flow import FlowCreate\\nfrom lfx.components.data_source.url import URLComponent\\nfrom lfx.components.flow_controls import LoopComponent\\nfrom lfx.components.input_output import ChatOutput\\nfrom lfx.components.llm_operations import StructuredOutputComponent\\nfrom lfx.components.models import LanguageModelComponent\\nfrom lfx.components.models_and_agents import PromptComponent\\nfrom lfx.components.processing import ParserComponent, SplitTextComponent\\nfrom lfx.graph import Graph\\nfrom lfx.schema.data import Data\\n\\nfrom tests.base import ComponentTestBaseWithClient\\nfrom tests.unit.build_utils import build_flow, get_build_events\\n\\nTEXT = (\\n    \\\"lorem ipsum dolor sit amet lorem ipsum dolor sit amet lorem ipsum dolor sit amet. \\\"\\n    \\\"lorem ipsum dolor sit amet lorem ipsum dolor sit amet lorem ipsum dolor sit amet. \\\"\\n    \\\"lorem ipsum dolor sit amet lorem ipsum dolor sit amet lorem ipsum dolor sit amet.\\\"\\n)\\n\\n\\nclass TestLoopComponentWithAPI(ComponentTestBaseWithClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return LoopComponent\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"data\\\": [[Data(text=\\\"Hello World\\\")]],\\n            \\\"loop_input\\\": [Data(text=TEXT)],\\n        }\\n\\n    def test_latest_version(self, component_class, default_kwargs) -> None:\\n        \\\"\\\"\\\"Test that the component works with the latest version.\\\"\\\"\\\"\\n        result = component_class(**default_kwargs)\\n        assert result is not None, \\\"Component returned None for the latest version.\\\"\\n\\n    async def _create_flow(self, client, json_loop_test, logged_in_headers):\\n        vector_store = orjson.loads(json_loop_test)\\n        data = vector_store[\\\"data\\\"]\\n        vector_store = FlowCreate(name=\\\"Flow\\\", description=\\\"description\\\", data=data, endpoint_name=\\\"f\\\")\\n        response = await client.post(\\\"api/v1/flows/\\\", json=vector_store.model_dump(), headers=logged_in_headers)\\n        response.raise_for_status()\\n        return response.json()[\\\"id\\\"]\\n\\n    async def check_messages(self, flow_id):\\n        messages = await aget_messages(flow_id=UUID(flow_id), order=\\\"ASC\\\")\\n        assert len(messages) == 1\\n        assert messages[0].session_id == flow_id\\n        assert messages[0].sender == \\\"Machine\\\"\\n        assert messages[0].sender_name == \\\"AI\\\"\\n        assert len(messages[0].text) > 0\\n        return messages\\n\\n    async def test_build_flow_loop(self, client, json_loop_test, logged_in_headers):\\n        \\\"\\\"\\\"Test building a flow with a loop component.\\\"\\\"\\\"\\n        # Create the flow\\n        flow_id = await self._create_flow(client, json_loop_test, logged_in_headers)\\n\\n        # Start the build and get job_id\\n        build_response = await build_flow(client, flow_id, logged_in_headers)\\n        job_id = build_response[\\\"job_id\\\"]\\n        assert job_id is not None\\n\\n        # Get the events stream\\n        events_response = await get_build_events(client, job_id, logged_in_headers)\\n        assert events_response.status_code == 200\\n\\n        # Process the events stream\\n        chat_output = None\\n        lines = []\\n        async for line in events_response.aiter_lines():\\n            if not line:  # Skip empty lines\\n                continue\\n            lines.append(line)\\n            if \\\"ChatOutput\\\" in line:\\n                chat_output = json.loads(line)\\n            # Process events if needed\\n            # We could add specific assertions here for loop-related events\\n        assert chat_output is not None\\n        messages = await self.check_messages(flow_id)\\n        ai_message = messages[0].text\\n        json_data = orjson.loads(ai_message)\\n\\n        # Use a for loop for better debugging\\n        found = []\\n        json_data = [(data[\\\"text\\\"], q_dict) for data, q_dict in json_data]\\n        for text, q_dict in json_data:\\n            expected_text = f\\\"==> {q_dict['q']}\\\"\\n            assert expected_text in text, (\\n                f\\\"Found {found} until now, but expected '{expected_text}' not found in '{text}',\\\"\\n                f\\\"and the json_data is {json_data}\\\"\\n            )\\n            found.append(expected_text)\\n\\n    async def test_run_flow_loop(self, client: AsyncClient, created_api_key, json_loop_test, logged_in_headers):\\n        flow_id = await self._create_flow(client, json_loop_test, logged_in_headers)\\n        headers = {\\\"x-api-key\\\": created_api_key.api_key}\\n        payload = {\\n            \\\"input_value\\\": TEXT,\\n            \\\"input_type\\\": \\\"chat\\\",\\n            \\\"session_id\\\": f\\\"{flow_id}run\\\",\\n            \\\"output_type\\\": \\\"chat\\\",\\n            \\\"tweaks\\\": {},\\n        }\\n        response = await client.post(f\\\"/api/v1/run/{flow_id}\\\", json=payload, headers=headers)\\n        data = response.json()\\n        assert \\\"outputs\\\" in data\\n        assert \\\"session_id\\\" in data\\n        assert len(data[\\\"outputs\\\"][-1][\\\"outputs\\\"]) > 0\\n\\n\\ndef loop_flow():\\n    \\\"\\\"\\\"Complete loop flow that processes multiple URLs through a loop.\\\"\\\"\\\"\\n    # Create URL component to fetch content from multiple sources\\n    url_component = URLComponent()\\n    url_component.set(urls=[\\\"https://docs.langflow.org/\\\"])\\n\\n    # Create SplitText component to chunk the content\\n    split_text_component = SplitTextComponent()\\n    split_text_component.set(\\n        data_inputs=url_component.fetch_content,\\n        chunk_size=1000,\\n        chunk_overlap=200,\\n        separator=\\\"\\\\n\\\\n\\\",\\n    )\\n\\n    # Create Loop component to iterate through the chunks\\n    loop_component = LoopComponent()\\n    loop_component.set(data=split_text_component.split_text)\\n\\n    # Create Parser component to format the current loop item\\n    parser_component = ParserComponent()\\n    parser_component.set(\\n        input_data=loop_component.item_output,\\n        pattern=\\\"Content: {text}\\\",\\n        sep=\\\"\\\\n\\\",\\n    )\\n\\n    # Create Prompt component to create processing instructions\\n    prompt_component = PromptComponent()\\n    prompt_component.set(\\n        template=\\\"Analyze and summarize this content: {context}\\\",\\n        input_text=parser_component.parse_combined_text,\\n    )\\n\\n    # Create a generic language model component for processing.\\n    language_model_component = LanguageModelComponent()\\n    language_model_component.set(temperature=0.7)\\n\\n    # Create StructuredOutput component to process content\\n    structured_output = StructuredOutputComponent()\\n    structured_output.set(\\n        llm=language_model_component.build_model,\\n        input_value=prompt_component.build_prompt,\\n        schema_name=\\\"ProcessedContent\\\",\\n        system_prompt=(  # Added missing system_prompt - this was causing the \\\"Multiple structured outputs\\\" error\\n            \\\"You are an AI that extracts one structured JSON object from unstructured text. \\\"\\n            \\\"Use a predefined schema with expected types (str, int, float, bool, dict). \\\"\\n            \\\"If multiple structures exist, extract only the first most complete one. \\\"\\n            \\\"Fill missing or ambiguous values with defaults: null for missing values. \\\"\\n            \\\"Ignore duplicates and partial repeats. \\\"\\n            \\\"Always return one valid JSON, never throw errors or return multiple objects.\\\"\\n            \\\"Output: A single well-formed JSON object, and nothing else.\\\"\\n        ),\\n        output_schema=[  # Fixed schema types to match expected format\\n            {\\\"name\\\": \\\"summary\\\", \\\"type\\\": \\\"str\\\", \\\"description\\\": \\\"Key summary of the content\\\", \\\"multiple\\\": False},\\n            {\\\"name\\\": \\\"topics\\\", \\\"type\\\": \\\"list\\\", \\\"description\\\": \\\"Main topics covered\\\", \\\"multiple\\\": False},\\n            {\\\"name\\\": \\\"source_url\\\", \\\"type\\\": \\\"str\\\", \\\"description\\\": \\\"Source URL of the content\\\", \\\"multiple\\\": False},\\n        ],\\n    )\\n\\n    # Connect the feedback loop - StructuredOutput back to Loop item input\\n    # Note: 'item' is a special dynamic input for LoopComponent feedback loops\\n    loop_component.set(item=structured_output.build_structured_output)\\n    # Create ChatOutput component to display final results\\n    chat_output = ChatOutput()\\n    chat_output.set(input_value=loop_component.done_output)\\n\\n    return Graph(start=url_component, end=chat_output)\\n\\n\\n@pytest.mark.xfail\\nasync def test_loop_flow():\\n    \\\"\\\"\\\"Test that loop_flow creates a working graph with proper loop feedback connection.\\\"\\\"\\\"\\n    flow = loop_flow()\\n    assert flow is not None\\n    assert flow._start is not None\\n    assert flow._end is not None\\n\\n    # Verify all expected components are present\\n    expected_vertices = {\\n        \\\"URLComponent\\\",\\n        \\\"SplitTextComponent\\\",\\n        \\\"LoopComponent\\\",\\n        \\\"ParserComponent\\\",\\n        \\\"PromptComponent\\\",\\n        \\\"LanguageModelComponent\\\",\\n        \\\"StructuredOutputComponent\\\",\\n        \\\"ChatOutput\\\",\\n    }\\n\\n    assert all(vertex.id.split(\\\"-\\\")[0] in expected_vertices for vertex in flow.vertices)\\n\\n    expected_execution_order = [\\n        \\\"LanguageModelComponent\\\",\\n        \\\"URLComponent\\\",\\n        \\\"SplitTextComponent\\\",\\n        \\\"LoopComponent\\\",\\n        \\\"ParserComponent\\\",\\n        \\\"PromptComponent\\\",\\n        \\\"StructuredOutputComponent\\\",\\n        \\\"LoopComponent\\\",\\n        \\\"ParserComponent\\\",\\n        \\\"PromptComponent\\\",\\n        \\\"StructuredOutputComponent\\\",\\n        \\\"LoopComponent\\\",\\n        \\\"ParserComponent\\\",\\n        \\\"PromptComponent\\\",\\n        \\\"StructuredOutputComponent\\\",\\n        \\\"LoopComponent\\\",\\n        \\\"ChatOutput\\\",\\n    ]\\n    results = [result async for result in flow.async_start()]\\n    result_order = [result.vertex.id.split(\\\"-\\\")[0] for result in results if hasattr(result, \\\"vertex\\\")]\\n    assert result_order == expected_execution_order\\n\\n\\nclass TestLoopComponentSubgraphExecution:\\n    \\\"\\\"\\\"Tests for the new subgraph-based loop execution implementation.\\\"\\\"\\\"\\n\\n    def test_loop_component_initialization(self):\\n        \\\"\\\"\\\"Test that LoopComponent initializes correctly with data.\\\"\\\"\\\"\\n        from lfx.schema.dataframe import DataFrame\\n\\n        data_list = [Data(text=\\\"item1\\\"), Data(text=\\\"item2\\\"), Data(text=\\\"item3\\\")]\\n        loop = LoopComponent()\\n        loop.set(data=DataFrame(data_list))\\n\\n        assert hasattr(loop, \\\"initialize_data\\\")\\n        assert hasattr(loop, \\\"get_loop_body_vertices\\\")\\n\\n    def test_validate_data_with_dataframe(self):\\n        \\\"\\\"\\\"Test that _validate_data correctly handles DataFrame input.\\\"\\\"\\\"\\n        from lfx.schema.dataframe import DataFrame\\n\\n        data_list = [Data(text=\\\"item1\\\"), Data(text=\\\"item2\\\")]\\n        df = DataFrame(data_list)\\n\\n        loop = LoopComponent()\\n        validated = loop._validate_data(df)\\n\\n        assert isinstance(validated, list)\\n        assert len(validated) == 2\\n        assert all(isinstance(item, Data) for item in validated)\\n\\n    def test_validate_data_with_single_data(self):\\n        \\\"\\\"\\\"Test that _validate_data correctly handles single Data input.\\\"\\\"\\\"\\n        single_data = Data(text=\\\"single item\\\")\\n\\n        loop = LoopComponent()\\n        validated = loop._validate_data(single_data)\\n\\n        assert isinstance(validated, list)\\n        assert len(validated) == 1\\n        assert validated[0] == single_data\\n\\n    def test_validate_data_with_list(self):\\n        \\\"\\\"\\\"Test that _validate_data correctly handles list of Data input.\\\"\\\"\\\"\\n        data_list = [Data(text=\\\"item1\\\"), Data(text=\\\"item2\\\")]\\n\\n        loop = LoopComponent()\\n        validated = loop._validate_data(data_list)\\n\\n        assert isinstance(validated, list)\\n        assert len(validated) == 2\\n        assert validated == data_list\\n\\n    def test_validate_data_with_invalid_input(self):\\n        \\\"\\\"\\\"Test that _validate_data raises TypeError for invalid input.\\\"\\\"\\\"\\n        loop = LoopComponent()\\n\\n        with pytest.raises(TypeError, match=\\\"must be a DataFrame\\\"):\\n            loop._validate_data(\\\"invalid input\\\")\\n\\n        with pytest.raises(TypeError, match=\\\"must be a DataFrame\\\"):\\n            loop._validate_data([1, 2, 3])\\n\\n    def test_get_loop_body_vertices_without_vertex(self):\\n        \\\"\\\"\\\"Test that get_loop_body_vertices returns empty set when no vertex context.\\\"\\\"\\\"\\n        loop = LoopComponent()\\n\\n        # Without _vertex attribute, should return empty set\\n        result = loop.get_loop_body_vertices()\\n\\n        assert result == set()\\n\\n    def test_get_loop_body_start_vertex_without_vertex(self):\\n        \\\"\\\"\\\"Test that _get_loop_body_start_vertex returns None when no vertex context.\\\"\\\"\\\"\\n        loop = LoopComponent()\\n\\n        # Without _vertex attribute, should return None\\n        result = loop._get_loop_body_start_vertex()\\n\\n        assert result is None\\n\\n    def test_extract_loop_output_with_empty_results(self):\\n        \\\"\\\"\\\"Test that _extract_loop_output handles empty results.\\\"\\\"\\\"\\n        from unittest.mock import patch\\n\\n        loop = LoopComponent()\\n\\n        # Mock get_incoming_edge_by_target_param to return None\\n        with patch.object(loop, \\\"get_incoming_edge_by_target_param\\\", return_value=None):\\n            result = loop._extract_loop_output([])\\n\\n            assert isinstance(result, Data)\\n            assert result.text == \\\"\\\"\\n\\n    def test_component_has_subgraph_methods(self):\\n        \\\"\\\"\\\"Test that LoopComponent has the new subgraph execution methods.\\\"\\\"\\\"\\n        loop = LoopComponent()\\n\\n        # Check that new methods exist\\n        assert hasattr(loop, \\\"get_loop_body_vertices\\\")\\n        assert hasattr(loop, \\\"execute_loop_body\\\")\\n        assert hasattr(loop, \\\"_get_loop_body_start_vertex\\\")\\n        assert hasattr(loop, \\\"_extract_loop_output\\\")\\n\\n        # Check that methods are callable\\n        assert callable(loop.get_loop_body_vertices)\\n        assert callable(loop.execute_loop_body)\\n        assert callable(loop._get_loop_body_start_vertex)\\n        assert callable(loop._extract_loop_output)\\n\\n    async def test_event_manager_passed_to_subgraph(self):\\n        \\\"\\\"\\\"Test that event_manager is properly passed to subgraph execution.\\\"\\\"\\\"\\n        from contextlib import asynccontextmanager\\n        from unittest.mock import MagicMock, patch\\n\\n        from lfx.schema.dataframe import DataFrame\\n\\n        # Create a mock event manager\\n        mock_event_manager = MagicMock()\\n\\n        # Create loop component with data\\n        loop = LoopComponent()\\n        data_list = [Data(text=\\\"item1\\\"), Data(text=\\\"item2\\\")]\\n        loop.set(data=DataFrame(data_list))\\n        loop._id = \\\"test_loop\\\"\\n\\n        # Mock the graph and vertex to simulate proper context\\n        mock_graph = MagicMock()\\n        mock_vertex = MagicMock()\\n        mock_vertex.outgoing_edges = []\\n        loop._vertex = mock_vertex\\n        loop._graph = mock_graph\\n\\n        # Mock get_loop_body_vertices to return empty set (no loop body)\\n        with patch.object(loop, \\\"get_loop_body_vertices\\\", return_value=set()):\\n            result = await loop.execute_loop_body(data_list, event_manager=mock_event_manager)\\n\\n            # Should return empty list when no loop body vertices\\n            assert result == []\\n\\n        # Now test with actual loop body vertices\\n        # Track whether event_manager was passed correctly\\n        event_manager_received = []\\n\\n        # Create an async generator that yields mock results\\n        async def mock_async_start(event_manager=None, **_kwargs):\\n            event_manager_received.append(event_manager)\\n            yield MagicMock(valid=True, result_dict={\\\"outputs\\\": {}})\\n\\n        mock_subgraph = MagicMock()\\n        mock_subgraph.prepare = MagicMock()\\n        mock_subgraph.async_start = mock_async_start\\n        mock_subgraph._vertices = []  # Empty list for iteration\\n        mock_subgraph.get_vertex = MagicMock(return_value=MagicMock(update_raw_params=MagicMock()))\\n\\n        # Create async context manager for create_subgraph\\n        @asynccontextmanager\\n        async def mock_create_subgraph(vertex_ids):  # noqa: ARG001\\n            yield mock_subgraph\\n\\n        with (\\n            patch.object(loop, \\\"get_loop_body_vertices\\\", return_value={\\\"vertex1\\\"}),\\n            patch.object(loop, \\\"_get_loop_body_start_vertex\\\", return_value=\\\"vertex1\\\"),\\n            patch.object(loop.graph, \\\"create_subgraph\\\", mock_create_subgraph),\\n        ):\\n            result = await loop.execute_loop_body(data_list, event_manager=mock_event_manager)\\n\\n            # Should have processed all items (one call per item)\\n            assert len(event_manager_received) == 2\\n            # Verify event_manager was passed correctly to each iteration\\n            assert all(em is mock_event_manager for em in event_manager_received)\\n\\n    async def test_done_output_passes_event_manager(self):\\n        \\\"\\\"\\\"Test that done_output properly passes event_manager to execute_loop_body.\\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, MagicMock, PropertyMock, patch\\n\\n        from lfx.schema.dataframe import DataFrame\\n\\n        # Create a mock event manager\\n        mock_event_manager = MagicMock()\\n\\n        # Create loop component\\n        loop = LoopComponent()\\n        data_list = [Data(text=\\\"item1\\\")]\\n        loop.set(data=DataFrame(data_list))\\n        loop._id = \\\"test_loop\\\"\\n        # Set the event manager as an instance attribute (this is how it's accessed in done_output)\\n        loop._event_manager = mock_event_manager\\n\\n        # Mock execute_loop_body to return expected data\\n        mock_execute = AsyncMock(return_value=[Data(text=\\\"result\\\")])\\n\\n        # Mock initialize_data to set up the context with data\\n        def mock_initialize_data():\\n            # Simulate what initialize_data does - set up context with data\\n            pass\\n\\n        # Create a mock context that returns data_list when get is called\\n        mock_ctx = MagicMock()\\n        mock_ctx.get = MagicMock(\\n            side_effect=lambda key, default=None: data_list if key == f\\\"{loop._id}_data\\\" else default\\n        )\\n\\n        with (\\n            patch.object(loop, \\\"execute_loop_body\\\", mock_execute),\\n            patch.object(loop, \\\"initialize_data\\\", mock_initialize_data),\\n            patch.object(type(loop), \\\"ctx\\\", new_callable=PropertyMock, return_value=mock_ctx),\\n        ):\\n            result = await loop.done_output()\\n\\n            # Verify execute_loop_body was called with the event_manager\\n            mock_execute.assert_called_once()\\n            call_args = mock_execute.call_args\\n\\n            # Check that event_manager was passed as keyword argument\\n            assert \\\"event_manager\\\" in call_args.kwargs\\n            assert call_args.kwargs[\\\"event_manager\\\"] is mock_event_manager\\n            assert isinstance(result, DataFrame)\\n\\n    def test_get_loop_body_vertices_simple_loop(self):\\n        \\\"\\\"\\\"Test get_loop_body_vertices with a simple loop structure.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock, PropertyMock, patch\\n\\n        # Create loop component\\n        loop = LoopComponent()\\n\\n        # Mock the vertex and graph structure for a simple loop:\\n        # Loop -> ComponentA -> ComponentB -> back to Loop\\n        mock_vertex = MagicMock()\\n        mock_edge = MagicMock()\\n        mock_edge.source_handle.name = \\\"item\\\"\\n        mock_edge.target_id = \\\"component_a\\\"\\n        mock_vertex.outgoing_edges = [mock_edge]\\n\\n        mock_graph = MagicMock()\\n        mock_graph.successor_map = {\\\"component_a\\\": [\\\"component_b\\\"], \\\"component_b\\\": [\\\"loop_end\\\"], \\\"loop_end\\\": []}\\n\\n        loop._vertex = mock_vertex\\n\\n        # Mock get_incoming_edge_by_target_param to return the end vertex\\n        with (\\n            patch.object(loop, \\\"get_incoming_edge_by_target_param\\\", return_value=\\\"loop_end\\\"),\\n            patch.object(type(loop), \\\"graph\\\", new_callable=PropertyMock, return_value=mock_graph),\\n        ):\\n            result = loop.get_loop_body_vertices()\\n\\n            # Should include all vertices in the loop body\\n            assert \\\"component_a\\\" in result\\n            assert \\\"component_b\\\" in result\\n            assert \\\"loop_end\\\" in result\\n            assert len(result) == 3\\n\\n    def test_get_loop_body_vertices_complex_loop(self):\\n        \\\"\\\"\\\"Test get_loop_body_vertices with a complex loop structure with branches.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock, PropertyMock, patch\\n\\n        # Create loop component\\n        loop = LoopComponent()\\n\\n        # Mock a complex loop structure:\\n        # Loop -> A -> B -> D -> End\\n        #           -> C -> D\\n        mock_vertex = MagicMock()\\n        mock_edge = MagicMock()\\n        mock_edge.source_handle.name = \\\"item\\\"\\n        mock_edge.target_id = \\\"component_a\\\"\\n        mock_vertex.outgoing_edges = [mock_edge]\\n\\n        mock_graph = MagicMock()\\n        mock_graph.successor_map = {\\n            \\\"component_a\\\": [\\\"component_b\\\", \\\"component_c\\\"],\\n            \\\"component_b\\\": [\\\"component_d\\\"],\\n            \\\"component_c\\\": [\\\"component_d\\\"],\\n            \\\"component_d\\\": [\\\"loop_end\\\"],\\n            \\\"loop_end\\\": [],\\n        }\\n\\n        loop._vertex = mock_vertex\\n\\n        # Mock get_incoming_edge_by_target_param to return the end vertex\\n        with (\\n            patch.object(loop, \\\"get_incoming_edge_by_target_param\\\", return_value=\\\"loop_end\\\"),\\n            patch.object(type(loop), \\\"graph\\\", new_callable=PropertyMock, return_value=mock_graph),\\n        ):\\n            result = loop.get_loop_body_vertices()\\n\\n            # Should include all vertices in the loop body including branches\\n            assert \\\"component_a\\\" in result\\n            assert \\\"component_b\\\" in result\\n            assert \\\"component_c\\\" in result\\n            assert \\\"component_d\\\" in result\\n            assert \\\"loop_end\\\" in result\\n            assert len(result) == 5\\n\\n    def test_get_loop_body_vertices_no_outgoing_edges(self):\\n        \\\"\\\"\\\"Test get_loop_body_vertices when loop has no outgoing edges.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock\\n\\n        # Create loop component\\n        loop = LoopComponent()\\n\\n        # Mock vertex with no outgoing edges\\n        mock_vertex = MagicMock()\\n        mock_vertex.outgoing_edges = []\\n\\n        loop._vertex = mock_vertex\\n\\n        result = loop.get_loop_body_vertices()\\n\\n        # Should return empty set\\n        assert result == set()\\n\\n    def test_get_loop_body_vertices_no_end_vertex(self):\\n        \\\"\\\"\\\"Test get_loop_body_vertices when there's no vertex feeding back to item input.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock, patch\\n\\n        # Create loop component\\n        loop = LoopComponent()\\n\\n        # Mock vertex with outgoing edges\\n        mock_vertex = MagicMock()\\n        mock_edge = MagicMock()\\n        mock_edge.source_handle.name = \\\"item\\\"\\n        mock_edge.target_id = \\\"component_a\\\"\\n        mock_vertex.outgoing_edges = [mock_edge]\\n\\n        loop._vertex = mock_vertex\\n\\n        # Mock get_incoming_edge_by_target_param to return None (no end vertex)\\n        with patch.object(loop, \\\"get_incoming_edge_by_target_param\\\", return_value=None):\\n            result = loop.get_loop_body_vertices()\\n\\n            # Should return empty set\\n            assert result == set()\\n\\n    def test_get_loop_body_vertices_with_cycle(self):\\n        \\\"\\\"\\\"Test get_loop_body_vertices with a cycle in the loop body.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock, PropertyMock, patch\\n\\n        # Create loop component\\n        loop = LoopComponent()\\n\\n        # Mock a loop structure with internal cycle:\\n        # Loop -> A -> B -> C -> B (cycle) -> D -> End\\n        mock_vertex = MagicMock()\\n        mock_edge = MagicMock()\\n        mock_edge.source_handle.name = \\\"item\\\"\\n        mock_edge.target_id = \\\"component_a\\\"\\n        mock_vertex.outgoing_edges = [mock_edge]\\n\\n        mock_graph = MagicMock()\\n        mock_graph.successor_map = {\\n            \\\"component_a\\\": [\\\"component_b\\\"],\\n            \\\"component_b\\\": [\\\"component_c\\\"],\\n            \\\"component_c\\\": [\\\"component_b\\\", \\\"component_d\\\"],  # Cycle back to B\\n            \\\"component_d\\\": [\\\"loop_end\\\"],\\n            \\\"loop_end\\\": [],\\n        }\\n\\n        loop._vertex = mock_vertex\\n\\n        # Mock get_incoming_edge_by_target_param to return the end vertex\\n        with (\\n            patch.object(loop, \\\"get_incoming_edge_by_target_param\\\", return_value=\\\"loop_end\\\"),\\n            patch.object(type(loop), \\\"graph\\\", new_callable=PropertyMock, return_value=mock_graph),\\n        ):\\n            result = loop.get_loop_body_vertices()\\n\\n            # Should handle cycle correctly and include all vertices\\n            assert \\\"component_a\\\" in result\\n            assert \\\"component_b\\\" in result\\n            assert \\\"component_c\\\" in result\\n            assert \\\"component_d\\\" in result\\n            assert \\\"loop_end\\\" in result\\n            assert len(result) == 5\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/flow_controls/test_loop_freeze.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"db860ca2ffe4d9925c37ec5c1882c5e340034bf8b7147c6a48af2a9b192c8f44\",\"content\":\"\\\"\\\"\\\"Tests for Loop component behavior when frozen.\\n\\nThis module tests the fix for the issue where frozen Loop components\\nwould run infinitely instead of iterating correctly through their data.\\n\\nThe fix ensures that Loop components always execute their build() method\\neven when frozen, because they need to iterate through their data correctly.\\n\\\"\\\"\\\"\\n\\nfrom unittest.mock import Mock\\n\\nimport pytest\\n\\n\\nclass TestVertexIsLoopProperty:\\n    \\\"\\\"\\\"Tests for the vertex is_loop property detection logic.\\\"\\\"\\\"\\n\\n    def test_is_loop_returns_true_for_loop_component(self):\\n        \\\"\\\"\\\"Test that is_loop returns True for Loop component vertices.\\\"\\\"\\\"\\n        outputs = [\\n            {\\\"name\\\": \\\"item\\\", \\\"allows_loop\\\": True},\\n            {\\\"name\\\": \\\"done\\\", \\\"allows_loop\\\": False},\\n        ]\\n\\n        # Call the actual property logic\\n        is_loop = any(output.get(\\\"allows_loop\\\", False) for output in outputs)\\n        assert is_loop is True\\n\\n    def test_is_loop_returns_false_for_regular_component(self):\\n        \\\"\\\"\\\"Test that is_loop returns False for regular component vertices.\\\"\\\"\\\"\\n        outputs = [\\n            {\\\"name\\\": \\\"output\\\", \\\"allows_loop\\\": False},\\n        ]\\n\\n        is_loop = any(output.get(\\\"allows_loop\\\", False) for output in outputs)\\n        assert is_loop is False\\n\\n    def test_is_loop_returns_false_for_empty_outputs(self):\\n        \\\"\\\"\\\"Test that is_loop returns False when outputs is empty.\\\"\\\"\\\"\\n        outputs = []\\n\\n        is_loop = any(output.get(\\\"allows_loop\\\", False) for output in outputs)\\n        assert is_loop is False\\n\\n    def test_is_loop_handles_missing_allows_loop_key(self):\\n        \\\"\\\"\\\"Test that is_loop handles outputs without allows_loop key.\\\"\\\"\\\"\\n        outputs = [\\n            {\\\"name\\\": \\\"output\\\"},  # No allows_loop key\\n        ]\\n\\n        is_loop = any(output.get(\\\"allows_loop\\\", False) for output in outputs)\\n        assert is_loop is False\\n\\n    def test_is_loop_with_multiple_loop_outputs(self):\\n        \\\"\\\"\\\"Test is_loop with multiple outputs that allow looping.\\\"\\\"\\\"\\n        outputs = [\\n            {\\\"name\\\": \\\"item1\\\", \\\"allows_loop\\\": True},\\n            {\\\"name\\\": \\\"item2\\\", \\\"allows_loop\\\": True},\\n            {\\\"name\\\": \\\"done\\\", \\\"allows_loop\\\": False},\\n        ]\\n\\n        is_loop = any(output.get(\\\"allows_loop\\\", False) for output in outputs)\\n        assert is_loop is True\\n\\n\\nclass TestBuildVertexLoopException:\\n    \\\"\\\"\\\"Tests for build_vertex Loop exception in graph/base.py.\\n\\n    This tests the logic: if not vertex.frozen or is_loop_component\\n    \\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def mock_loop_vertex(self):\\n        \\\"\\\"\\\"Create a mock Loop vertex.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.id = \\\"test-vertex-id\\\"\\n        vertex.frozen = True\\n        vertex.built = True\\n        vertex.is_loop = True\\n        vertex.display_name = \\\"Loop\\\"\\n        vertex.result = Mock()\\n        vertex.artifacts = {}\\n        return vertex\\n\\n    @pytest.fixture\\n    def mock_non_loop_vertex(self):\\n        \\\"\\\"\\\"Create a mock non-loop vertex.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.id = \\\"test-vertex-id\\\"\\n        vertex.frozen = True\\n        vertex.built = True\\n        vertex.is_loop = False\\n        vertex.display_name = \\\"Parser\\\"\\n        vertex.result = Mock()\\n        vertex.artifacts = {}\\n        return vertex\\n\\n    def test_loop_component_detected_by_is_loop(self, mock_loop_vertex):\\n        \\\"\\\"\\\"Test that Loop component is detected by is_loop property.\\\"\\\"\\\"\\n        vertex = mock_loop_vertex\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n        assert is_loop_component is True\\n\\n    def test_loop_component_detected_by_display_name(self):\\n        \\\"\\\"\\\"Test that Loop component is detected by display_name.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.display_name = \\\"Loop\\\"\\n        vertex.is_loop = False  # Even if is_loop is False\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n        assert is_loop_component is True\\n\\n    def test_non_loop_component_not_detected(self, mock_non_loop_vertex):\\n        \\\"\\\"\\\"Test that non-Loop component is not detected as loop.\\\"\\\"\\\"\\n        vertex = mock_non_loop_vertex\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n        assert is_loop_component is False\\n\\n    def test_frozen_loop_should_build(self, mock_loop_vertex):\\n        \\\"\\\"\\\"Test that frozen Loop should still build.\\n\\n        This is the key test for our fix: frozen Loop components\\n        must always build because they need to iterate through data.\\n        \\\"\\\"\\\"\\n        vertex = mock_loop_vertex\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n\\n        # This is the logic from build_vertex in graph/base.py\\n        should_build = not vertex.frozen or is_loop_component\\n        assert should_build is True\\n\\n    def test_frozen_non_loop_should_not_build(self, mock_non_loop_vertex):\\n        \\\"\\\"\\\"Test that frozen non-Loop should NOT build (use cache).\\\"\\\"\\\"\\n        vertex = mock_non_loop_vertex\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n\\n        should_build = not vertex.frozen or is_loop_component\\n        assert should_build is False\\n\\n    def test_non_frozen_loop_should_build(self):\\n        \\\"\\\"\\\"Test that non-frozen Loop should build.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.frozen = False\\n        vertex.is_loop = True\\n        vertex.display_name = \\\"Loop\\\"\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n        should_build = not vertex.frozen or is_loop_component\\n        assert should_build is True\\n\\n    def test_non_frozen_non_loop_should_build(self, mock_non_loop_vertex):\\n        \\\"\\\"\\\"Test that non-frozen non-Loop should build.\\\"\\\"\\\"\\n        vertex = mock_non_loop_vertex\\n        vertex.frozen = False\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n        should_build = not vertex.frozen or is_loop_component\\n        assert should_build is True\\n\\n    def test_custom_loop_component_name_detected(self):\\n        \\\"\\\"\\\"Test that custom component with is_loop=True is detected.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.display_name = \\\"CustomIterator\\\"  # Not \\\"Loop\\\"\\n        vertex.is_loop = True\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n        assert is_loop_component is True\\n\\n    def test_all_frozen_states_for_loop(self):\\n        \\\"\\\"\\\"Test all combinations of frozen states for Loop component.\\\"\\\"\\\"\\n        test_cases = [\\n            # (frozen, is_loop, expected_should_build)\\n            (False, False, True),  # Not frozen, not loop -> build\\n            (False, True, True),  # Not frozen, loop -> build\\n            (True, False, False),  # Frozen, not loop -> don't build (use cache)\\n            (True, True, True),  # Frozen, loop -> build (our fix!)\\n        ]\\n\\n        for frozen, is_loop, expected in test_cases:\\n            vertex = Mock()\\n            vertex.frozen = frozen\\n            vertex.is_loop = is_loop\\n            vertex.display_name = \\\"Loop\\\" if is_loop else \\\"Other\\\"\\n\\n            is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n            should_build = not vertex.frozen or is_loop_component\\n\\n            assert should_build == expected, (\\n                f\\\"Failed for frozen={frozen}, is_loop={is_loop}: expected {expected}, got {should_build}\\\"\\n            )\\n\\n\\nclass TestVertexBuildLoopException:\\n    \\\"\\\"\\\"Tests for vertex.build() Loop exception in vertex/base.py.\\n\\n    This tests the logic: if self.frozen and self.built and not is_loop_component\\n    \\\"\\\"\\\"\\n\\n    def test_frozen_built_loop_should_continue_build(self):\\n        \\\"\\\"\\\"Test that frozen+built Loop should NOT return cached result.\\n\\n        This is the key test: even when frozen AND built, Loop components\\n        must continue to build() so they can iterate through their data.\\n        \\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.frozen = True\\n        vertex.built = True\\n        vertex.is_loop = True\\n        vertex.display_name = \\\"Loop\\\"\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n\\n        # This is the condition from vertex.build() in vertex/base.py\\n        should_return_cached = vertex.frozen and vertex.built and not is_loop_component\\n        assert should_return_cached is False\\n\\n    def test_frozen_built_non_loop_should_return_cached(self):\\n        \\\"\\\"\\\"Test that frozen+built non-Loop SHOULD return cached result.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.frozen = True\\n        vertex.built = True\\n        vertex.is_loop = False\\n        vertex.display_name = \\\"Parser\\\"\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n\\n        should_return_cached = vertex.frozen and vertex.built and not is_loop_component\\n        assert should_return_cached is True\\n\\n    def test_not_frozen_loop_should_not_return_cached(self):\\n        \\\"\\\"\\\"Test that non-frozen Loop should NOT return cached result.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.frozen = False\\n        vertex.built = True\\n        vertex.is_loop = True\\n        vertex.display_name = \\\"Loop\\\"\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n\\n        should_return_cached = vertex.frozen and vertex.built and not is_loop_component\\n        assert should_return_cached is False\\n\\n    def test_frozen_not_built_loop_should_not_return_cached(self):\\n        \\\"\\\"\\\"Test that frozen but not built Loop should NOT return cached.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.frozen = True\\n        vertex.built = False\\n        vertex.is_loop = True\\n        vertex.display_name = \\\"Loop\\\"\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n\\n        should_return_cached = vertex.frozen and vertex.built and not is_loop_component\\n        assert should_return_cached is False\\n\\n    def test_all_frozen_built_states_for_vertex_build(self):\\n        \\\"\\\"\\\"Test all combinations for vertex.build() cache decision.\\\"\\\"\\\"\\n        test_cases = [\\n            # (frozen, built, is_loop, expected_return_cached)\\n            (False, False, False, False),  # Not frozen, not built -> continue\\n            (False, False, True, False),  # Not frozen, not built, loop -> continue\\n            (False, True, False, False),  # Not frozen, built -> continue\\n            (False, True, True, False),  # Not frozen, built, loop -> continue\\n            (True, False, False, False),  # Frozen, not built -> continue\\n            (True, False, True, False),  # Frozen, not built, loop -> continue\\n            (True, True, False, True),  # Frozen, built, not loop -> return cached\\n            (True, True, True, False),  # Frozen, built, loop -> continue (our fix!)\\n        ]\\n\\n        for frozen, built, is_loop, expected in test_cases:\\n            vertex = Mock()\\n            vertex.frozen = frozen\\n            vertex.built = built\\n            vertex.is_loop = is_loop\\n            vertex.display_name = \\\"Loop\\\" if is_loop else \\\"Other\\\"\\n\\n            is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n            should_return_cached = vertex.frozen and vertex.built and not is_loop_component\\n\\n            assert should_return_cached == expected, (\\n                f\\\"Failed for frozen={frozen}, built={built}, is_loop={is_loop}: \\\"\\n                f\\\"expected {expected}, got {should_return_cached}\\\"\\n            )\\n\\n\\nclass TestLoopComponentOutputsConfig:\\n    \\\"\\\"\\\"Tests for Loop component outputs configuration.\\\"\\\"\\\"\\n\\n    def test_loop_component_has_allows_loop_output(self):\\n        \\\"\\\"\\\"Test that Loop component has allows_loop=True on item output.\\\"\\\"\\\"\\n        from lfx.components.flow_controls import LoopComponent\\n\\n        component = LoopComponent()\\n        outputs = component.outputs\\n\\n        # Find the item output\\n        item_output = next((o for o in outputs if o.name == \\\"item\\\"), None)\\n\\n        assert item_output is not None\\n        assert item_output.allows_loop is True\\n\\n    def test_loop_component_done_output_no_loop(self):\\n        \\\"\\\"\\\"Test that Loop component done output does NOT allow loop.\\\"\\\"\\\"\\n        from lfx.components.flow_controls import LoopComponent\\n\\n        component = LoopComponent()\\n        outputs = component.outputs\\n\\n        # Find the done output\\n        done_output = next((o for o in outputs if o.name == \\\"done\\\"), None)\\n\\n        assert done_output is not None\\n        # done output should not have allows_loop=True\\n        assert getattr(done_output, \\\"allows_loop\\\", False) is False\\n\\n\\nclass TestLoopEvaluateStopLoop:\\n    \\\"\\\"\\\"Tests for Loop component evaluate_stop_loop logic.\\\"\\\"\\\"\\n\\n    def test_evaluate_stop_loop_logic(self):\\n        \\\"\\\"\\\"Test the evaluate_stop_loop logic directly.\\\"\\\"\\\"\\n        # The logic is: current_index > data_length\\n\\n        test_cases = [\\n            # (current_index, data_length, expected_stop)\\n            (0, 3, False),  # At start, don't stop\\n            (1, 3, False),  # In middle, don't stop\\n            (2, 3, False),  # At last item, don't stop\\n            (3, 3, False),  # At length, don't stop (equal, not greater)\\n            (4, 3, True),  # Past length, stop\\n            (0, 0, False),  # Empty data, index 0, don't stop\\n            (1, 0, True),  # Empty data, index 1, stop\\n            (0, 1, False),  # Single item, at start\\n            (1, 1, False),  # Single item, at length\\n            (2, 1, True),  # Single item, past length\\n        ]\\n\\n        for current_index, data_length, expected_stop in test_cases:\\n            # This is the logic from evaluate_stop_loop\\n            result = current_index > data_length\\n\\n            assert result == expected_stop, (\\n                f\\\"Failed for index={current_index}, length={data_length}: expected {expected_stop}, got {result}\\\"\\n            )\\n\\n\\nclass TestFrozenLoopScenarios:\\n    \\\"\\\"\\\"Integration-style tests for frozen Loop scenarios.\\\"\\\"\\\"\\n\\n    def test_frozen_loop_first_execution_should_build(self):\\n        \\\"\\\"\\\"Test that first execution of frozen Loop should build.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.frozen = True\\n        vertex.built = False  # First time, not built yet\\n        vertex.is_loop = True\\n        vertex.display_name = \\\"Loop\\\"\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n\\n        # In build_vertex: should_build\\n        should_build_vertex = not vertex.frozen or is_loop_component\\n        assert should_build_vertex is True\\n\\n        # In vertex.build: should NOT return cached (not built yet)\\n        should_return_cached = vertex.frozen and vertex.built and not is_loop_component\\n        assert should_return_cached is False\\n\\n    def test_frozen_loop_subsequent_iteration_should_build(self):\\n        \\\"\\\"\\\"Test that subsequent iterations of frozen Loop should build.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.frozen = True\\n        vertex.built = True  # Already built in previous iteration\\n        vertex.is_loop = True\\n        vertex.display_name = \\\"Loop\\\"\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n\\n        # In build_vertex: should_build\\n        should_build_vertex = not vertex.frozen or is_loop_component\\n        assert should_build_vertex is True\\n\\n        # In vertex.build: should NOT return cached (it's a loop!)\\n        should_return_cached = vertex.frozen and vertex.built and not is_loop_component\\n        assert should_return_cached is False\\n\\n    def test_frozen_non_loop_should_use_cache(self):\\n        \\\"\\\"\\\"Test that frozen non-Loop component uses cache.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.frozen = True\\n        vertex.built = True\\n        vertex.is_loop = False\\n        vertex.display_name = \\\"TextSplitter\\\"\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n\\n        # In build_vertex: should NOT build\\n        should_build_vertex = not vertex.frozen or is_loop_component\\n        assert should_build_vertex is False\\n\\n    def test_multiple_loop_components_all_detected(self):\\n        \\\"\\\"\\\"Test that multiple Loop components are all detected correctly.\\\"\\\"\\\"\\n        loops = []\\n        for _ in range(5):\\n            vertex = Mock()\\n            vertex.frozen = True\\n            vertex.built = True\\n            vertex.is_loop = True\\n            vertex.display_name = \\\"Loop\\\"\\n            loops.append(vertex)\\n\\n        for vertex in loops:\\n            is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n            should_build = not vertex.frozen or is_loop_component\\n            assert should_build is True\\n\\n\\nclass TestEdgeCasesForLoopDetection:\\n    \\\"\\\"\\\"Edge case tests for Loop component detection.\\\"\\\"\\\"\\n\\n    def test_loop_with_unusual_display_name(self):\\n        \\\"\\\"\\\"Test Loop detection with unusual display name but is_loop=True.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.display_name = \\\"My Custom Iterator 123\\\"\\n        vertex.is_loop = True\\n        vertex.frozen = True\\n        vertex.built = True\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n        should_build_result = not vertex.frozen or is_loop_component\\n\\n        assert is_loop_component is True\\n        assert should_build_result is True\\n\\n    def test_component_named_loop_but_is_loop_false(self):\\n        \\\"\\\"\\\"Test component named 'Loop' but is_loop=False.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.display_name = \\\"Loop\\\"\\n        vertex.is_loop = False  # Somehow is_loop is False\\n        vertex.frozen = True\\n        vertex.built = True\\n\\n        # Should still be detected by display_name\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n        should_build = not vertex.frozen or is_loop_component\\n\\n        assert is_loop_component is True\\n        assert should_build is True\\n\\n    def test_none_values_handled(self):\\n        \\\"\\\"\\\"Test that None values are handled gracefully.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.display_name = None\\n        vertex.is_loop = None\\n        vertex.frozen = True\\n        vertex.built = True\\n\\n        # Should not crash, should not be detected as loop\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n        should_build = not vertex.frozen or is_loop_component\\n\\n        assert is_loop_component is None  # None or None = None\\n        assert should_build is None  # False or None = None\\n        # But in boolean context, None is falsy\\n        should_build_bool = not vertex.frozen or bool(is_loop_component)\\n        assert should_build_bool is False\\n\\n    def test_empty_string_display_name(self):\\n        \\\"\\\"\\\"Test empty string display name.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.display_name = \\\"\\\"\\n        vertex.is_loop = False\\n        vertex.frozen = True\\n        vertex.built = True\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n        should_build = not vertex.frozen or is_loop_component\\n\\n        assert is_loop_component is False\\n        assert should_build is False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/flow_controls/test_notify_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"123f0607485743bcd5510d2ab5fb9e004d89d7a237c73d9b52385f6ecf16b734\",\"content\":\"import pytest\\nfrom langflow.schema.data import Data\\nfrom lfx.components.flow_controls.notify import NotifyComponent\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestNotifyComponent(ComponentTestBaseWithoutClient):\\n    \\\"\\\"\\\"Test cases for NotifyComponent.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return NotifyComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"context_key\\\": \\\"test_key\\\",\\n            \\\"input_value\\\": None,\\n            \\\"append\\\": False,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    async def test_component_initialization(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test proper initialization of NotifyComponent.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert component.display_name == \\\"Notify\\\"\\n        assert component.description == \\\"A component to generate a notification to Get Notified component.\\\"\\n        assert component.icon == \\\"Notify\\\"\\n        assert component.name == \\\"Notify\\\"\\n        assert component.beta is True\\n\\n    async def test_inputs_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that inputs are properly configured.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        expected_input_names = {\\\"context_key\\\", \\\"input_value\\\", \\\"append\\\"}\\n        input_names = {inp.name for inp in component.inputs}\\n\\n        assert expected_input_names.issubset(input_names)\\n        assert len(component.inputs) >= 3\\n\\n    async def test_context_key_input_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test context_key input configuration.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        context_key_input = next((inp for inp in component.inputs if inp.name == \\\"context_key\\\"), None)\\n\\n        assert context_key_input is not None\\n        assert context_key_input.display_name == \\\"Context Key\\\"\\n        assert context_key_input.required is True\\n\\n    async def test_input_value_input_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test input_value input configuration.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        input_value_input = next((inp for inp in component.inputs if inp.name == \\\"input_value\\\"), None)\\n\\n        assert input_value_input is not None\\n        assert input_value_input.display_name == \\\"Input Data\\\"\\n        assert input_value_input.required is False\\n        # JSON is the new name for Data, Table is the new name for DataFrame (backward compatible)\\n        assert input_value_input.input_types == [\\\"Data\\\", \\\"JSON\\\", \\\"Message\\\", \\\"DataFrame\\\", \\\"Table\\\"]\\n\\n    async def test_append_input_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test append input configuration.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        append_input = next((inp for inp in component.inputs if inp.name == \\\"append\\\"), None)\\n        assert append_input is not None\\n\\n    async def test_outputs_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that outputs are properly configured.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert len(component.outputs) >= 1\\n\\n        result_output = next(out for out in component.outputs if out.name == \\\"result\\\")\\n        assert result_output.method == \\\"notify_components\\\"\\n        assert result_output.cache is False\\n\\n    async def test_component_beta_status(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that component is marked as beta.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert hasattr(component, \\\"beta\\\")\\n        assert component.beta is True\\n\\n    async def test_component_inheritance(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that component properly inherits from Component base class.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        from langflow.custom import Component\\n\\n        assert isinstance(component, Component)\\n\\n    @pytest.mark.asyncio\\n    async def test_notify_components_method_exists(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that notify_components method exists and is callable.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert hasattr(component, \\\"notify_components\\\")\\n        assert callable(component.notify_components)\\n\\n    @pytest.mark.asyncio\\n    async def test_notify_components_no_vertex_raises_error(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test notify_components raises ValueError when component not in graph.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.context_key = \\\"test_key\\\"\\n        component.input_value = Data(text=\\\"test\\\")\\n        component.append = False\\n        component._vertex = None\\n\\n        with pytest.raises(ValueError, match=\\\"Notify component must be used in a graph\\\"):\\n            await component.notify_components()\\n\\n    async def test_notify_components_is_async(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that notify_components is properly defined as async.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        import inspect\\n\\n        assert inspect.iscoroutinefunction(component.notify_components)\\n\\n    async def test_output_method_mapping(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that output is correctly mapped to notify_components method.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        result_output = next(out for out in component.outputs if out.name == \\\"result\\\")\\n        assert result_output.method == \\\"notify_components\\\"\\n        assert result_output.cache is False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/flow_controls/test_pass_message.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ac1986e58f3d22bd720bfee96ca039dbec6ad3f8772e23f382ebc17c79c1bb03\",\"content\":\"import pytest\\nfrom langflow.schema.message import Message\\nfrom lfx.components.flow_controls.pass_message import PassMessageComponent\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestPassMessageComponent(ComponentTestBaseWithoutClient):\\n    \\\"\\\"\\\"Test cases for PassMessageComponent.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return PassMessageComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"input_message\\\": None,\\n            \\\"ignored_message\\\": None,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    async def test_component_initialization(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test proper initialization of PassMessageComponent.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert component.display_name == \\\"Pass\\\"\\n        assert component.description == \\\"Forwards the input message, unchanged.\\\"\\n        assert component.name == \\\"Pass\\\"\\n        assert component.icon == \\\"arrow-right\\\"\\n        assert component.legacy is True\\n\\n    async def test_inputs_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that inputs are properly configured.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert len(component.inputs) == 2\\n\\n        input_names = [inp.name for inp in component.inputs]\\n        assert \\\"input_message\\\" in input_names\\n        assert \\\"ignored_message\\\" in input_names\\n\\n        # Test input_message configuration\\n        input_message = next(inp for inp in component.inputs if inp.name == \\\"input_message\\\")\\n        assert input_message.display_name == \\\"Input Message\\\"\\n        assert input_message.required is True\\n        assert \\\"message to be passed forward\\\" in input_message.info\\n\\n        # Test ignored_message configuration\\n        ignored_message = next(inp for inp in component.inputs if inp.name == \\\"ignored_message\\\")\\n        assert ignored_message.display_name == \\\"Ignored Message\\\"\\n        assert ignored_message.advanced is True\\n        assert \\\"workaround for continuity\\\" in ignored_message.info\\n\\n    async def test_outputs_configuration(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that outputs are properly configured.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert len(component.outputs) == 1\\n\\n        output = component.outputs[0]\\n        assert output.name == \\\"output_message\\\"\\n        assert output.display_name == \\\"Output Message\\\"\\n        assert output.method == \\\"pass_message\\\"\\n\\n    async def test_pass_message_basic_functionality(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test pass_message method basic functionality.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        # Setup\\n        test_message = Message(content=\\\"Hello World\\\")\\n        component.input_message = test_message\\n\\n        # Execute\\n        result = component.pass_message()\\n\\n        # Assert\\n        assert result == test_message\\n        assert result is test_message  # Should be the same object, not a copy\\n        assert component.status == test_message\\n\\n    async def test_pass_message_different_message_types(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test pass_message with different message content types.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        test_cases = [\\n            Message(content=\\\"Simple text\\\"),\\n            Message(content=\\\"\\\"),  # Empty content\\n            Message(content=\\\"Multi\\\\nline\\\\ntext\\\"),\\n            Message(content=\\\"Special chars: !@#$%^&*()\\\"),\\n            Message(content=\\\"Unicode: \u4f60\u597d\u4e16\u754c \ud83c\udf0d\\\"),\\n            Message(content=None),  # None content\\n        ]\\n\\n        for test_message in test_cases:\\n            component.input_message = test_message\\n\\n            result = component.pass_message()\\n\\n            assert result == test_message\\n            assert result.content == test_message.content\\n            assert component.status == test_message\\n\\n    async def test_pass_message_with_ignored_message(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that ignored_message parameter is truly ignored.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        # Setup\\n        input_msg = Message(content=\\\"This should be returned\\\")\\n        ignored_msg = Message(content=\\\"This should be ignored\\\")\\n\\n        component.input_message = input_msg\\n        component.ignored_message = ignored_msg\\n\\n        # Execute\\n        result = component.pass_message()\\n\\n        # Assert - only input_message should be returned, ignored_message should not affect result\\n        assert result == input_msg\\n        assert result != ignored_msg\\n        assert component.status == input_msg\\n\\n    async def test_pass_message_status_assignment(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that status is properly assigned.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        test_message = Message(content=\\\"Status test\\\")\\n        component.input_message = test_message\\n\\n        # Initially status might be different\\n\\n        result = component.pass_message()\\n\\n        # After calling pass_message, status should be set to input_message\\n        assert component.status == test_message\\n        assert component.status == result\\n\\n    async def test_pass_message_no_side_effects(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that pass_message doesn't modify the input message.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        original_content = \\\"Original content\\\"\\n        test_message = Message(content=original_content)\\n        component.input_message = test_message\\n\\n        # Store original properties\\n        original_id = test_message.id if hasattr(test_message, \\\"id\\\") else None\\n\\n        result = component.pass_message()\\n\\n        # Message should be unchanged\\n        assert test_message.content == original_content\\n        if original_id is not None and hasattr(test_message, \\\"id\\\"):\\n            assert test_message.id == original_id\\n\\n        # Result should be identical\\n        assert result == test_message\\n\\n    async def test_pass_message_method_signature(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that pass_message method has correct signature.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        import inspect\\n\\n        sig = inspect.signature(component.pass_message)\\n\\n        # Should have no parameters except self\\n        assert len(sig.parameters) == 0\\n\\n        # Should have Message return annotation\\n        assert (\\n            sig.return_annotation == Message\\n            or str(sig.return_annotation) == \\\"<class 'langflow.schema.message.Message'>\\\"\\n        )\\n\\n    async def test_component_legacy_status(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that component is properly marked as legacy.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        assert hasattr(component, \\\"legacy\\\")\\n        assert component.legacy is True\\n\\n    async def test_component_inheritance(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that component properly inherits from Component base class.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        from langflow.custom.custom_component.component import Component\\n\\n        assert isinstance(component, Component)\\n\\n    async def test_output_method_mapping(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that output is correctly mapped to pass_message method.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        output = component.outputs[0]\\n        assert hasattr(component, output.method)\\n        assert callable(getattr(component, output.method))\\n\\n    async def test_message_attributes_preservation(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that all message attributes are preserved through pass_message.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        # Create a message with various attributes\\n        test_message = Message(\\n            content=\\\"Test content\\\", sender=\\\"Test Sender\\\", sender_name=\\\"Test Name\\\", session_id=\\\"test_session\\\"\\n        )\\n\\n        component.input_message = test_message\\n        result = component.pass_message()\\n\\n        # All attributes should be preserved\\n        assert result.content == test_message.content\\n        assert result.sender == test_message.sender\\n        assert result.sender_name == test_message.sender_name\\n        assert result.session_id == test_message.session_id\\n\\n    async def test_pass_message_multiple_calls(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test calling pass_message multiple times with different inputs.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        messages = [\\n            Message(content=\\\"First message\\\"),\\n            Message(content=\\\"Second message\\\"),\\n            Message(content=\\\"Third message\\\"),\\n        ]\\n\\n        results = []\\n        for msg in messages:\\n            component.input_message = msg\\n            result = component.pass_message()\\n            results.append(result)\\n\\n            # Each call should return the correct message\\n            assert result == msg\\n            assert component.status == msg\\n\\n        # All results should be different and correct\\n        for i, (msg, result) in enumerate(zip(messages, results, strict=False)):\\n            assert result == msg\\n            assert result.content == f\\\"{['First', 'Second', 'Third'][i]} message\\\"\\n\\n    async def test_pass_message_with_none_input(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test pass_message behavior with None input.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        component.input_message = None\\n\\n        result = component.pass_message()\\n\\n        assert result is None\\n        assert component.status is None\\n\\n    async def test_ignored_message_truly_ignored(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that ignored_message has no impact on the result regardless of its value.\\\"\\\"\\\"\\n        component = await self.component_setup(component_class, default_kwargs)\\n        input_msg = Message(content=\\\"Input\\\")\\n\\n        # Test with different ignored message values\\n        ignored_values = [\\n            Message(content=\\\"Ignored\\\"),\\n            None,\\n            Message(content=\\\"Different ignored content\\\"),\\n        ]\\n\\n        for ignored_value in ignored_values:\\n            component.input_message = input_msg\\n            component.ignored_message = ignored_value\\n\\n            result = component.pass_message()\\n\\n            # Result should always be the input_message, regardless of ignored_message\\n            assert result == input_msg\\n            assert result.content == \\\"Input\\\"\\n            assert component.status == input_msg\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/logic/test_run_flow_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"562da5b5b1944593835bb5513ad88cc262915c4c02578b374f6ef766a15902b5\",\"content\":\"from copy import deepcopy\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom lfx.base.tools.run_flow import RunFlowBaseComponent\\nfrom lfx.components.flow_controls.run_flow import RunFlowComponent\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dotdict import dotdict\\nfrom lfx.schema.message import Message\\n\\n\\nclass TestRunFlowComponentInitialization:\\n    \\\"\\\"\\\"Test RunFlowComponent initialization.\\\"\\\"\\\"\\n\\n    def test_component_has_correct_metadata(self):\\n        \\\"\\\"\\\"Test that component has correct display name, description, etc.\\\"\\\"\\\"\\n        assert RunFlowComponent.display_name == \\\"Run Flow\\\"\\n        assert \\\"Executes another flow from within the same project.\\\" in RunFlowComponent.description\\n        assert RunFlowComponent.name == \\\"RunFlow\\\"\\n        assert RunFlowComponent.icon == \\\"Workflow\\\"\\n        assert RunFlowComponent.beta is True\\n\\n    def test_flow_tweak_data_is_isolated_per_instance(self):\\n        \\\"\\\"\\\"flow_tweak_data should not be shared by reference across Run Flow instances.\\\"\\\"\\\"\\n        first = RunFlowComponent()\\n        second = RunFlowComponent()\\n\\n        assert first.flow_tweak_data is not second.flow_tweak_data\\n        assert not isinstance(vars(RunFlowBaseComponent)[\\\"flow_tweak_data\\\"], dict)\\n\\n        first.flow_tweak_data[\\\"TextInput-AAA\\\"] = {\\\"input_value\\\": \\\"LEAK\\\"}\\n\\n        assert \\\"TextInput-AAA\\\" not in second.flow_tweak_data\\n\\n    def test_tool_added_flow_tweak_input_does_not_mutate_class_inputs(self):\\n        \\\"\\\"\\\"Fallback inputs created by tool calls must stay on that component instance.\\\"\\\"\\\"\\n        component = deepcopy(RunFlowComponent())\\n\\n        component.set(flow_tweak_data={\\\"TextInput-XYZ\\\": {\\\"input_value\\\": \\\"from-A\\\"}})\\n        fresh = RunFlowComponent()\\n\\n        assert any(input_.name == \\\"flow_tweak_data\\\" for input_ in component.inputs)\\n        assert not any(input_.name == \\\"flow_tweak_data\\\" for input_ in fresh.inputs)\\n        assert not any(input_.name == \\\"flow_tweak_data\\\" for input_ in RunFlowComponent.inputs)\\n\\n\\nclass TestRunFlowComponentHelperMethods:\\n    \\\"\\\"\\\"Test helper methods in RunFlowComponent.\\\"\\\"\\\"\\n\\n    def test_get_selected_flow_meta_returns_metadata_field(self):\\n        \\\"\\\"\\\"Test that get_selected_flow_meta extracts the correct metadata field.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n\\n        flow_id = str(uuid4())\\n        updated_at = \\\"2024-01-01T12:00:00Z\\\"\\n\\n        build_config = dotdict({\\\"flow_name_selected\\\": {\\\"selected_metadata\\\": {\\\"id\\\": flow_id, \\\"updated_at\\\": updated_at}}})\\n\\n        result_id = component.get_selected_flow_meta(build_config, \\\"id\\\")\\n        result_updated_at = component.get_selected_flow_meta(build_config, \\\"updated_at\\\")\\n\\n        assert result_id == flow_id\\n        assert result_updated_at == updated_at\\n\\n    def test_get_selected_flow_meta_returns_none_when_missing(self):\\n        \\\"\\\"\\\"Test that get_selected_flow_meta returns None for missing metadata.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n\\n        build_config = dotdict({\\\"flow_name_selected\\\": {\\\"selected_metadata\\\": {}}})\\n\\n        result = component.get_selected_flow_meta(build_config, \\\"nonexistent\\\")\\n\\n        assert result is None\\n\\n    def test_get_selected_flow_meta_returns_none_when_no_metadata(self):\\n        \\\"\\\"\\\"Test that get_selected_flow_meta returns None when no metadata exists.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n\\n        build_config = dotdict({})\\n\\n        result = component.get_selected_flow_meta(build_config, \\\"id\\\")\\n\\n        assert result is None\\n\\n    @pytest.mark.asyncio\\n    async def test_load_graph_and_update_cfg_loads_graph_and_updates_config(self):\\n        \\\"\\\"\\\"Test that load_graph_and_update_cfg loads graph and updates build config.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n        component._user_id = str(uuid4())\\n\\n        flow_id = str(uuid4())\\n        updated_at = \\\"2024-01-01T12:00:00Z\\\"\\n        build_config = dotdict({})\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.vertices = []\\n\\n        with (\\n            patch.object(component, \\\"get_graph\\\", new_callable=AsyncMock) as mock_get_graph,\\n            patch.object(component, \\\"update_build_config_from_graph\\\") as mock_update_cfg,\\n        ):\\n            mock_get_graph.return_value = mock_graph\\n\\n            await component.load_graph_and_update_cfg(build_config=build_config, flow_id=flow_id, updated_at=updated_at)\\n\\n            mock_get_graph.assert_called_once_with(flow_id_selected=flow_id, updated_at=updated_at)\\n            mock_update_cfg.assert_called_once_with(build_config, mock_graph)\\n\\n    @pytest.mark.asyncio\\n    async def test_load_graph_and_update_cfg_handles_datetime_object(self):\\n        \\\"\\\"\\\"Test that load_graph_and_update_cfg handles datetime objects.\\\"\\\"\\\"\\n        from datetime import datetime\\n\\n        component = RunFlowComponent()\\n        component._user_id = str(uuid4())\\n\\n        flow_id = str(uuid4())\\n        updated_at = datetime.fromisoformat(\\\"2024-01-01T12:00:00+00:00\\\")\\n        build_config = dotdict({})\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.vertices = []\\n\\n        with (\\n            patch.object(component, \\\"get_graph\\\", new_callable=AsyncMock) as mock_get_graph,\\n            patch.object(component, \\\"update_build_config_from_graph\\\") as mock_update_cfg,\\n        ):\\n            mock_get_graph.return_value = mock_graph\\n\\n            await component.load_graph_and_update_cfg(build_config=build_config, flow_id=flow_id, updated_at=updated_at)\\n\\n            # Should convert datetime to ISO format string\\n            mock_get_graph.assert_called_once_with(flow_id_selected=flow_id, updated_at=updated_at.isoformat())\\n            mock_update_cfg.assert_called_once_with(build_config, mock_graph)\\n\\n    def test_should_update_stale_flow_returns_true_when_flow_is_stale(self):\\n        \\\"\\\"\\\"Test that should_update_stale_flow returns True when flow is outdated.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n\\n        flow = Data(\\n            data={\\n                \\\"id\\\": str(uuid4()),\\n                \\\"updated_at\\\": \\\"2024-01-02T12:00:00Z\\\",  # Newer\\n            }\\n        )\\n\\n        build_config = dotdict(\\n            {\\n                \\\"flow_name_selected\\\": {\\n                    \\\"selected_metadata\\\": {\\n                        \\\"updated_at\\\": \\\"2024-01-01T12:00:00Z\\\"  # Older\\n                    }\\n                }\\n            }\\n        )\\n\\n        result = component.should_update_stale_flow(flow, build_config)\\n\\n        assert result is True\\n\\n    def test_should_update_stale_flow_returns_false_when_flow_is_current(self):\\n        \\\"\\\"\\\"Test that should_update_stale_flow returns False when flow is current.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n\\n        flow = Data(\\n            data={\\n                \\\"id\\\": str(uuid4()),\\n                \\\"updated_at\\\": \\\"2024-01-01T12:00:00Z\\\",  # Same\\n            }\\n        )\\n\\n        build_config = dotdict(\\n            {\\n                \\\"flow_name_selected\\\": {\\n                    \\\"selected_metadata\\\": {\\n                        \\\"updated_at\\\": \\\"2024-01-01T12:00:00Z\\\"  # Same\\n                    }\\n                }\\n            }\\n        )\\n\\n        result = component.should_update_stale_flow(flow, build_config)\\n\\n        assert result is False\\n\\n    def test_should_update_stale_flow_returns_false_when_no_updated_at_in_flow(self):\\n        \\\"\\\"\\\"Test that should_update_stale_flow returns falsey value when flow has no updated_at.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n\\n        flow = Data(data={\\\"id\\\": str(uuid4()), \\\"updated_at\\\": None})\\n\\n        build_config = dotdict({\\\"flow_name_selected\\\": {\\\"selected_metadata\\\": {\\\"updated_at\\\": \\\"2024-01-01T12:00:00Z\\\"}}})\\n\\n        result = component.should_update_stale_flow(flow, build_config)\\n\\n        assert not result  # Should return falsey (None or False)\\n\\n    def test_should_update_stale_flow_returns_false_when_no_metadata_updated_at(self):\\n        \\\"\\\"\\\"Test that should_update_stale_flow returns falsey value when metadata has no updated_at.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n\\n        flow = Data(data={\\\"id\\\": str(uuid4()), \\\"updated_at\\\": \\\"2024-01-01T12:00:00Z\\\"})\\n\\n        build_config = dotdict({\\\"flow_name_selected\\\": {\\\"selected_metadata\\\": {}}})\\n\\n        result = component.should_update_stale_flow(flow, build_config)\\n\\n        assert not result  # Should return falsey (None or False)\\n\\n    @pytest.mark.asyncio\\n    async def test_check_and_update_stale_flow_updates_when_stale(self):\\n        \\\"\\\"\\\"Test that check_and_update_stale_flow updates config when flow is stale.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n        component._user_id = str(uuid4())\\n\\n        flow_id = str(uuid4())\\n        flow = Data(data={\\\"id\\\": flow_id, \\\"updated_at\\\": \\\"2024-01-02T12:00:00Z\\\"})\\n\\n        build_config = dotdict({\\\"flow_name_selected\\\": {\\\"selected_metadata\\\": {\\\"updated_at\\\": \\\"2024-01-01T12:00:00Z\\\"}}})\\n\\n        with (\\n            patch.object(component, \\\"should_update_stale_flow\\\", return_value=True),\\n            patch.object(component, \\\"load_graph_and_update_cfg\\\", new_callable=AsyncMock) as mock_load,\\n        ):\\n            await component.check_and_update_stale_flow(flow, build_config)\\n\\n            mock_load.assert_called_once_with(build_config, flow_id, \\\"2024-01-02T12:00:00Z\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_check_and_update_stale_flow_does_nothing_when_current(self):\\n        \\\"\\\"\\\"Test that check_and_update_stale_flow does nothing when flow is current.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n\\n        flow = Data(data={\\\"id\\\": str(uuid4()), \\\"updated_at\\\": \\\"2024-01-01T12:00:00Z\\\"})\\n\\n        build_config = dotdict({})\\n\\n        with (\\n            patch.object(component, \\\"should_update_stale_flow\\\", return_value=False),\\n            patch.object(component, \\\"load_graph_and_update_cfg\\\", new_callable=AsyncMock) as mock_load,\\n        ):\\n            await component.check_and_update_stale_flow(flow, build_config)\\n\\n            mock_load.assert_not_called()\\n\\n\\nclass TestRunFlowComponentUpdateBuildConfig:\\n    \\\"\\\"\\\"Test update_build_config method.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_adds_missing_keys(self):\\n        \\\"\\\"\\\"Test that update_build_config automatically adds missing required keys with defaults.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n        build_config = dotdict({})  # Empty config\\n\\n        result = await component.update_build_config(\\n            build_config=build_config, field_value=None, field_name=\\\"flow_name_selected\\\"\\n        )\\n\\n        # Verify that all default keys are now present\\n        for key in component.default_keys:\\n            assert key in result, f\\\"Expected key '{key}' to be added to build_config\\\"\\n\\n        # Verify specific default values\\n        assert result[\\\"flow_name_selected\\\"][\\\"options\\\"] == []\\n        assert result[\\\"flow_name_selected\\\"][\\\"options_metadata\\\"] == []\\n        assert result[\\\"flow_name_selected\\\"][\\\"value\\\"] is None\\n        assert result[\\\"flow_id_selected\\\"][\\\"value\\\"] is None\\n        assert result[\\\"cache_flow\\\"][\\\"value\\\"] is False\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_refreshes_flow_list_with_none_value(self):\\n        \\\"\\\"\\\"Test that update_build_config refreshes flow list when field_value is None.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n        component._user_id = str(uuid4())\\n        component._flow_id = str(uuid4())\\n\\n        build_config = dotdict(\\n            {\\n                \\\"code\\\": {},\\n                \\\"_type\\\": {},\\n                \\\"flow_name_selected\\\": {\\\"options\\\": [], \\\"options_metadata\\\": []},\\n                \\\"flow_id_selected\\\": {},\\n                \\\"session_id\\\": {},\\n                \\\"cache_flow\\\": {},\\n            }\\n        )\\n\\n        mock_flows = [\\n            Data(data={\\\"name\\\": \\\"Flow 1\\\", \\\"id\\\": str(uuid4()), \\\"updated_at\\\": \\\"2024-01-01T12:00:00Z\\\"}),\\n            Data(data={\\\"name\\\": \\\"Flow 2\\\", \\\"id\\\": str(uuid4()), \\\"updated_at\\\": \\\"2024-01-01T12:00:00Z\\\"}),\\n        ]\\n\\n        with patch.object(component, \\\"alist_flows_by_flow_folder\\\", new_callable=AsyncMock) as mock_list:\\n            mock_list.return_value = mock_flows\\n\\n            result = await component.update_build_config(\\n                build_config=build_config,\\n                field_value=None,  # Triggers refresh\\n                field_name=\\\"flow_name_selected\\\",\\n            )\\n\\n            assert \\\"Flow 1\\\" in result[\\\"flow_name_selected\\\"][\\\"options\\\"]\\n            assert \\\"Flow 2\\\" in result[\\\"flow_name_selected\\\"][\\\"options\\\"]\\n            assert len(result[\\\"flow_name_selected\\\"][\\\"options_metadata\\\"]) == 2\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_refreshes_with_is_refresh_flag(self):\\n        \\\"\\\"\\\"Test that update_build_config refreshes flow list when is_refresh is True.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n        component._user_id = str(uuid4())\\n        component._flow_id = str(uuid4())\\n\\n        build_config = dotdict(\\n            {\\n                \\\"code\\\": {},\\n                \\\"_type\\\": {},\\n                \\\"flow_name_selected\\\": {\\\"options\\\": [], \\\"options_metadata\\\": []},\\n                \\\"flow_id_selected\\\": {},\\n                \\\"session_id\\\": {},\\n                \\\"cache_flow\\\": {},\\n                \\\"is_refresh\\\": True,\\n            }\\n        )\\n\\n        mock_flows = [\\n            Data(data={\\\"name\\\": \\\"Flow 1\\\", \\\"id\\\": str(uuid4()), \\\"updated_at\\\": \\\"2024-01-01T12:00:00Z\\\"}),\\n            Data(data={\\\"name\\\": \\\"Flow 2\\\", \\\"id\\\": str(uuid4()), \\\"updated_at\\\": \\\"2024-01-01T12:00:00Z\\\"}),\\n        ]\\n\\n        with patch.object(component, \\\"alist_flows_by_flow_folder\\\", new_callable=AsyncMock) as mock_list:\\n            mock_list.return_value = mock_flows\\n\\n            result = await component.update_build_config(\\n                build_config=build_config,\\n                field_value=None,  # Change to None to test refresh path\\n                field_name=\\\"flow_name_selected\\\",\\n            )\\n\\n            assert \\\"Flow 1\\\" in result[\\\"flow_name_selected\\\"][\\\"options\\\"]\\n            assert \\\"Flow 2\\\" in result[\\\"flow_name_selected\\\"][\\\"options\\\"]\\n            assert len(result[\\\"flow_name_selected\\\"][\\\"options_metadata\\\"]) == 2\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_updates_graph_on_flow_selection(self):\\n        \\\"\\\"\\\"Test that update_build_config updates graph when flow is selected.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n        component._user_id = str(uuid4())\\n        component._flow_id = str(uuid4())\\n\\n        flow_id = str(uuid4())\\n        flow_name = \\\"Test Flow\\\"\\n        updated_at = \\\"2024-01-01T12:00:00Z\\\"\\n\\n        build_config = dotdict(\\n            {\\n                \\\"code\\\": {},\\n                \\\"_type\\\": {},\\n                \\\"flow_name_selected\\\": {\\n                    \\\"options\\\": [flow_name],\\n                    \\\"options_metadata\\\": [{\\\"id\\\": flow_id}],\\n                    \\\"selected_metadata\\\": {\\\"id\\\": flow_id, \\\"updated_at\\\": updated_at},\\n                },\\n                \\\"flow_id_selected\\\": {\\\"value\\\": None},\\n                \\\"session_id\\\": {},\\n                \\\"cache_flow\\\": {},\\n            }\\n        )\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.vertices = []\\n\\n        with patch.object(component, \\\"load_graph_and_update_cfg\\\", new_callable=AsyncMock) as mock_load:\\n            result = await component.update_build_config(\\n                build_config=build_config, field_value=flow_name, field_name=\\\"flow_name_selected\\\"\\n            )\\n\\n            mock_load.assert_called_once_with(build_config, flow_id, updated_at)\\n            assert result[\\\"flow_id_selected\\\"][\\\"value\\\"] == flow_id\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_handles_error_gracefully(self):\\n        \\\"\\\"\\\"Test that update_build_config handles errors gracefully.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n        component._user_id = str(uuid4())\\n        component._flow_id = str(uuid4())\\n\\n        flow_name = \\\"Test Flow\\\"\\n        flow_id = str(uuid4())\\n\\n        build_config = dotdict(\\n            {\\n                \\\"code\\\": {},\\n                \\\"_type\\\": {},\\n                \\\"flow_name_selected\\\": {\\n                    \\\"options\\\": [flow_name],\\n                    \\\"selected_metadata\\\": {\\\"id\\\": flow_id, \\\"updated_at\\\": \\\"2024-01-01T12:00:00Z\\\"},\\n                },\\n                \\\"flow_id_selected\\\": {\\\"value\\\": None},\\n                \\\"session_id\\\": {},\\n                \\\"cache_flow\\\": {},\\n            }\\n        )\\n\\n        with patch.object(component, \\\"load_graph_and_update_cfg\\\", new_callable=AsyncMock) as mock_load:\\n            mock_load.side_effect = Exception(\\\"Test error\\\")\\n\\n            with pytest.raises(RuntimeError, match=\\\"Error building graph for flow\\\"):\\n                await component.update_build_config(\\n                    build_config=build_config, field_value=flow_name, field_name=\\\"flow_name_selected\\\"\\n                )\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_returns_unchanged_for_other_fields(self):\\n        \\\"\\\"\\\"Test that update_build_config returns unchanged config for non-flow_name_selected fields.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n\\n        build_config = dotdict(\\n            {\\n                \\\"code\\\": {},\\n                \\\"_type\\\": {},\\n                \\\"flow_name_selected\\\": {},\\n                \\\"flow_id_selected\\\": {},\\n                \\\"session_id\\\": {},\\n                \\\"cache_flow\\\": {},\\n            }\\n        )\\n\\n        result = await component.update_build_config(\\n            build_config=build_config, field_value=\\\"some_value\\\", field_name=\\\"session_id\\\"\\n        )\\n\\n        assert result == build_config\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_does_not_refresh_without_conditions(self):\\n        \\\"\\\"\\\"Test that update_build_config does NOT refresh when is_refresh is False and field_value is not None.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n        component._user_id = str(uuid4())\\n        component._flow_id = str(uuid4())\\n\\n        flow_id = str(uuid4())\\n        flow_name = \\\"Test Flow\\\"\\n        updated_at = \\\"2024-01-01T12:00:00Z\\\"\\n\\n        build_config = dotdict(\\n            {\\n                \\\"code\\\": {},\\n                \\\"_type\\\": {},\\n                \\\"flow_name_selected\\\": {\\n                    \\\"options\\\": [\\\"Old Flow\\\"],\\n                    \\\"options_metadata\\\": [{\\\"id\\\": \\\"old_id\\\"}],\\n                    \\\"selected_metadata\\\": {\\\"id\\\": flow_id, \\\"updated_at\\\": updated_at},\\n                },\\n                \\\"flow_id_selected\\\": {\\\"value\\\": flow_id},\\n                \\\"session_id\\\": {},\\n                \\\"cache_flow\\\": {},\\n                \\\"is_refresh\\\": False,  # Not refreshing\\n            }\\n        )\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.vertices = []\\n\\n        with (\\n            patch.object(component, \\\"alist_flows_by_flow_folder\\\", new_callable=AsyncMock) as mock_list,\\n            patch.object(component, \\\"load_graph_and_update_cfg\\\", new_callable=AsyncMock) as mock_load,\\n        ):\\n            await component.update_build_config(\\n                build_config=build_config,\\n                field_value=flow_name,  # Non-None value\\n                field_name=\\\"flow_name_selected\\\",\\n            )\\n\\n            # Should NOT have called list flows (no refresh)\\n            mock_list.assert_not_called()\\n\\n            # Should have called load_graph_and_update_cfg instead (normal flow selection)\\n            mock_load.assert_called_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_run_flow_runtime_uses_selected_metadata_updated_at(self):\\n        \\\"\\\"\\\"Ensure runtime fetch passes cached metadata updated_at to get_graph.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n        component._user_id = str(uuid4())\\n        component._flow_id = str(uuid4())\\n\\n        flow_id = str(uuid4())\\n        flow_name = \\\"Cached Flow\\\"\\n        updated_at = \\\"2024-10-01T12:34:56Z\\\"\\n\\n        component._inputs[\\\"cache_flow\\\"].value = True\\n        component._inputs[\\\"flow_id_selected\\\"].value = flow_id\\n        component._inputs[\\\"flow_name_selected\\\"].value = flow_name\\n        component._inputs[\\\"session_id\\\"].value = Message(text=\\\"session\\\")\\n\\n        component._vertex = SimpleNamespace(\\n            data={\\n                \\\"node\\\": {\\n                    \\\"template\\\": {\\n                        \\\"flow_name_selected\\\": {\\n                            \\\"selected_metadata\\\": {\\n                                \\\"id\\\": flow_id,\\n                                \\\"updated_at\\\": updated_at,\\n                            }\\n                        }\\n                    }\\n                }\\n            }\\n        )\\n\\n        component._pre_run_setup()\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.vertices = []\\n\\n        component.get_graph = AsyncMock(return_value=mock_graph)\\n\\n        with patch(\\\"lfx.base.tools.run_flow.run_flow\\\", new=AsyncMock(return_value=[])) as mock_run_flow:\\n            await component._run_flow_with_cached_graph(\\n                user_id=component.user_id,\\n                output_type=\\\"any\\\",\\n            )\\n\\n        component.get_graph.assert_awaited_once_with(\\n            flow_name_selected=flow_name,\\n            flow_id_selected=flow_id,\\n            updated_at=updated_at,\\n        )\\n        mock_run_flow.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_handles_flow_id_selected_field(self):\\n        \\\"\\\"\\\"Test that update_build_config handles flow_id_selected field changes.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n        component._user_id = str(uuid4())\\n        component._flow_id = str(uuid4())\\n\\n        flow_id = str(uuid4())\\n        flow_name = \\\"Test Flow\\\"\\n        updated_at = \\\"2024-01-01T12:00:00Z\\\"\\n\\n        build_config = dotdict(\\n            {\\n                \\\"code\\\": {},\\n                \\\"_type\\\": {},\\n                \\\"flow_name_selected\\\": {\\n                    \\\"options\\\": [flow_name],\\n                    \\\"selected_metadata\\\": {\\\"id\\\": flow_id, \\\"updated_at\\\": updated_at},\\n                },\\n                \\\"flow_id_selected\\\": {\\\"value\\\": flow_id},\\n                \\\"session_id\\\": {},\\n                \\\"cache_flow\\\": {},\\n            }\\n        )\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.vertices = []\\n\\n        with patch.object(component, \\\"load_graph_and_update_cfg\\\", new_callable=AsyncMock) as mock_load:\\n            await component.update_build_config(\\n                build_config=build_config, field_value=flow_id, field_name=\\\"flow_id_selected\\\"\\n            )\\n\\n            # Should call load_graph_and_update_cfg with the flow_id\\n            mock_load.assert_called_once_with(build_config, flow_id, updated_at)\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_derives_flow_id_from_metadata(self):\\n        \\\"\\\"\\\"Test that flow_id is derived from selected_metadata when available.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n        component._user_id = str(uuid4())\\n        component._flow_id = str(uuid4())\\n\\n        flow_id = str(uuid4())\\n        flow_name = \\\"Test Flow\\\"\\n        updated_at = \\\"2024-01-01T12:00:00Z\\\"\\n\\n        build_config = dotdict(\\n            {\\n                \\\"code\\\": {},\\n                \\\"_type\\\": {},\\n                \\\"flow_name_selected\\\": {\\n                    \\\"options\\\": [flow_name],\\n                    \\\"selected_metadata\\\": {\\\"id\\\": flow_id, \\\"updated_at\\\": updated_at},\\n                },\\n                \\\"flow_id_selected\\\": {\\\"value\\\": None},  # No existing value\\n                \\\"session_id\\\": {},\\n                \\\"cache_flow\\\": {},\\n            }\\n        )\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.vertices = []\\n\\n        with patch.object(component, \\\"load_graph_and_update_cfg\\\", new_callable=AsyncMock) as mock_load:\\n            result = await component.update_build_config(\\n                build_config=build_config, field_value=flow_name, field_name=\\\"flow_name_selected\\\"\\n            )\\n\\n            # Should have derived the flow_id from selected_metadata\\n            assert result[\\\"flow_id_selected\\\"][\\\"value\\\"] == flow_id\\n            mock_load.assert_called_once_with(build_config, flow_id, updated_at)\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_uses_existing_flow_id_when_no_metadata(self):\\n        \\\"\\\"\\\"Test that existing flow_id is used when selected_metadata is unavailable.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n        component._user_id = str(uuid4())\\n        component._flow_id = str(uuid4())\\n\\n        existing_flow_id = str(uuid4())\\n        flow_name = \\\"Test Flow\\\"\\n\\n        build_config = dotdict(\\n            {\\n                \\\"code\\\": {},\\n                \\\"_type\\\": {},\\n                \\\"flow_name_selected\\\": {\\n                    \\\"options\\\": [flow_name],\\n                    # No selected_metadata\\n                },\\n                \\\"flow_id_selected\\\": {\\\"value\\\": existing_flow_id},\\n                \\\"session_id\\\": {},\\n                \\\"cache_flow\\\": {},\\n            }\\n        )\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.vertices = []\\n\\n        with patch.object(component, \\\"load_graph_and_update_cfg\\\", new_callable=AsyncMock) as mock_load:\\n            result = await component.update_build_config(\\n                build_config=build_config, field_value=flow_name, field_name=\\\"flow_name_selected\\\"\\n            )\\n\\n            # Should have kept the existing flow_id\\n            assert result[\\\"flow_id_selected\\\"][\\\"value\\\"] == existing_flow_id\\n            mock_load.assert_called_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_checks_stale_flow_during_refresh(self):\\n        \\\"\\\"\\\"Test that update_build_config checks and updates stale flows during refresh.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n        component._user_id = str(uuid4())\\n        component._flow_id = str(uuid4())\\n\\n        flow_id = str(uuid4())\\n        component.flow_id_selected = flow_id\\n\\n        build_config = dotdict(\\n            {\\n                \\\"code\\\": {},\\n                \\\"_type\\\": {},\\n                \\\"flow_name_selected\\\": {\\\"options\\\": [], \\\"options_metadata\\\": []},\\n                \\\"flow_id_selected\\\": {},\\n                \\\"session_id\\\": {},\\n                \\\"cache_flow\\\": {},\\n            }\\n        )\\n\\n        mock_flows = [\\n            Data(data={\\\"name\\\": \\\"Flow 1\\\", \\\"id\\\": flow_id, \\\"updated_at\\\": \\\"2024-01-02T12:00:00Z\\\"}),\\n        ]\\n\\n        with (\\n            patch.object(component, \\\"alist_flows_by_flow_folder\\\", new_callable=AsyncMock) as mock_list,\\n            patch.object(component, \\\"check_and_update_stale_flow\\\", new_callable=AsyncMock) as mock_check,\\n        ):\\n            mock_list.return_value = mock_flows\\n\\n            await component.update_build_config(\\n                build_config=build_config, field_value=None, field_name=\\\"flow_name_selected\\\"\\n            )\\n\\n            # Should have checked if flow is stale\\n            mock_check.assert_called_once_with(mock_flows[0], build_config)\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_uses_get_selected_flow_meta(self):\\n        \\\"\\\"\\\"Test that update_build_config uses get_selected_flow_meta to derive flow_id.\\\"\\\"\\\"\\n        component = RunFlowComponent()\\n        component._user_id = str(uuid4())\\n        component._flow_id = str(uuid4())\\n\\n        flow_id = str(uuid4())\\n        flow_name = \\\"Test Flow\\\"\\n        updated_at = \\\"2024-01-01T12:00:00Z\\\"\\n\\n        build_config = dotdict(\\n            {\\n                \\\"code\\\": {},\\n                \\\"_type\\\": {},\\n                \\\"flow_name_selected\\\": {\\n                    \\\"options\\\": [flow_name],\\n                    \\\"selected_metadata\\\": {\\\"id\\\": flow_id, \\\"updated_at\\\": updated_at},\\n                },\\n                \\\"flow_id_selected\\\": {\\\"value\\\": None},\\n                \\\"session_id\\\": {},\\n                \\\"cache_flow\\\": {},\\n            }\\n        )\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.vertices = []\\n\\n        with patch.object(component, \\\"load_graph_and_update_cfg\\\", new_callable=AsyncMock) as mock_load:\\n            result = await component.update_build_config(\\n                build_config=build_config, field_value=flow_name, field_name=\\\"flow_name_selected\\\"\\n            )\\n\\n            # Should have derived flow_id from metadata\\n            assert result[\\\"flow_id_selected\\\"][\\\"value\\\"] == flow_id\\n\\n            # Should have called load_graph_and_update_cfg with correct parameters\\n            mock_load.assert_called_once_with(build_config, flow_id, updated_at)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/models_and_agents/test_mcp_component_flow_reload.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1e2a0362cc6a42065b1135953f06234c858df59063f2b0df0b9419c5c336821d\",\"content\":\"\\\"\\\"\\\"Unit tests for MCP component flow reload behavior.\\n\\nValidates that tool selection persists when navigating away and back to a flow:\\n- Cold cache (initial load) must NOT be treated as a server change\\n- Saved tool options and value must be preserved on initial load\\n- UUID override must only happen on genuine server changes\\n\\\"\\\"\\\"\\n\\nfrom typing import Any\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom lfx.base.agents.utils import safe_cache_get, safe_cache_set\\nfrom lfx.components.models_and_agents.mcp_component import MCPToolsComponent\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestMCPComponentFlowReload(ComponentTestBaseWithoutClient):\\n    \\\"\\\"\\\"Tests for tool selection persistence across flow navigation.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        return MCPToolsComponent\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        return []\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\n            \\\"mcp_server\\\": {\\n                \\\"name\\\": \\\"test_server\\\",\\n                \\\"config\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"test-mcp-server\\\"]},\\n            },\\n            \\\"tool\\\": \\\"saved_tool\\\",\\n            \\\"use_cache\\\": False,\\n        }\\n\\n    @pytest.fixture\\n    def saved_flow_build_config(self):\\n        \\\"\\\"\\\"Simulates build_config from a saved flow with tool already selected.\\\"\\\"\\\"\\n        return {\\n            \\\"mcp_server\\\": {\\\"value\\\": {\\\"name\\\": \\\"test_server\\\"}},\\n            \\\"tool\\\": {\\n                \\\"show\\\": True,\\n                \\\"options\\\": [\\\"saved_tool\\\", \\\"other_tool\\\"],\\n                \\\"value\\\": \\\"saved_tool\\\",\\n                \\\"placeholder\\\": \\\"Select a tool\\\",\\n            },\\n            \\\"tool_placeholder\\\": {\\\"tool_mode\\\": False},\\n            \\\"tools_metadata\\\": {\\\"show\\\": False},\\n        }\\n\\n    async def component_setup(self, component_class: type[Any], default_kwargs: dict[str, Any]) -> MCPToolsComponent:\\n        component_instance = await super().component_setup(component_class, default_kwargs)\\n        component_instance._user_id = str(uuid4())\\n        return component_instance\\n\\n    @pytest.mark.asyncio\\n    async def test_should_preserve_tool_options_when_cache_is_cold(\\n        self, component_class, default_kwargs, saved_flow_build_config\\n    ):\\n        \\\"\\\"\\\"Cold cache on initial flow load must not clear saved tool options.\\n\\n        Bug: navigating away and back to a flow clears tool.options because the\\n        backend treats cold cache (_last_selected_server=\\\"\\\") as a server change.\\n        \\\"\\\"\\\"\\n        # Arrange \u2014 ensure cold cache (no previous server selection)\\n        component = await self.component_setup(component_class, default_kwargs)\\n        safe_cache_set(component._shared_component_cache, \\\"last_selected_server\\\", \\\"\\\")\\n        build_config = saved_flow_build_config.copy()\\n        server_value = {\\\"name\\\": \\\"test_server\\\"}\\n\\n        # Act \u2014 simulate initial load (cold cache, no last_selected_server)\\n        updated_config = await component.update_build_config(build_config, server_value, \\\"mcp_server\\\")\\n\\n        # Assert \u2014 saved options must be preserved\\n        assert updated_config[\\\"tool\\\"][\\\"options\\\"] == [\\\"saved_tool\\\", \\\"other_tool\\\"]\\n        assert updated_config[\\\"tool\\\"][\\\"show\\\"] is True\\n\\n    @pytest.mark.asyncio\\n    async def test_should_preserve_tool_value_when_cache_is_cold(\\n        self, component_class, default_kwargs, saved_flow_build_config\\n    ):\\n        \\\"\\\"\\\"Cold cache on initial flow load must not override saved tool value with UUID.\\\"\\\"\\\"\\n        # Arrange \u2014 ensure cold cache\\n        component = await self.component_setup(component_class, default_kwargs)\\n        safe_cache_set(component._shared_component_cache, \\\"last_selected_server\\\", \\\"\\\")\\n        build_config = saved_flow_build_config.copy()\\n        server_value = {\\\"name\\\": \\\"test_server\\\"}\\n\\n        # Act\\n        updated_config = await component.update_build_config(build_config, server_value, \\\"mcp_server\\\")\\n\\n        # Assert \u2014 value must remain the saved tool name, not a UUID\\n        tool_value = updated_config[\\\"tool\\\"][\\\"value\\\"]\\n        assert tool_value == \\\"saved_tool\\\"\\n        assert not isinstance(tool_value, UUID)\\n\\n    @pytest.mark.asyncio\\n    async def test_should_override_tool_value_with_uuid_when_server_genuinely_changes(\\n        self, component_class, default_kwargs, saved_flow_build_config\\n    ):\\n        \\\"\\\"\\\"When user switches to a different server, tool value must be reset.\\\"\\\"\\\"\\n        # Arrange\\n        component = await self.component_setup(component_class, default_kwargs)\\n        build_config = saved_flow_build_config.copy()\\n\\n        # Simulate previous server was set (warm cache)\\n        safe_cache_set(component._shared_component_cache, \\\"last_selected_server\\\", \\\"old_server\\\")\\n\\n        new_server_value = {\\\"name\\\": \\\"new_server\\\"}\\n\\n        # Act\\n        updated_config = await component.update_build_config(build_config, new_server_value, \\\"mcp_server\\\")\\n\\n        # Assert \u2014 value must be a UUID (forced refresh)\\n        assert isinstance(updated_config[\\\"tool\\\"][\\\"value\\\"], UUID)\\n\\n    @pytest.mark.asyncio\\n    async def test_should_set_last_selected_server_in_cache_on_initial_load(\\n        self, component_class, default_kwargs, saved_flow_build_config\\n    ):\\n        \\\"\\\"\\\"Initial load must populate the cache with the current server name.\\\"\\\"\\\"\\n        # Arrange \u2014 ensure cold cache\\n        component = await self.component_setup(component_class, default_kwargs)\\n        safe_cache_set(component._shared_component_cache, \\\"last_selected_server\\\", \\\"\\\")\\n        build_config = saved_flow_build_config.copy()\\n        server_value = {\\\"name\\\": \\\"test_server\\\"}\\n\\n        # Act\\n        await component.update_build_config(build_config, server_value, \\\"mcp_server\\\")\\n\\n        # Assert\\n        cached_server = safe_cache_get(component._shared_component_cache, \\\"last_selected_server\\\", \\\"\\\")\\n        assert cached_server == \\\"test_server\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_clear_tool_options_when_server_genuinely_changes(\\n        self, component_class, default_kwargs, saved_flow_build_config\\n    ):\\n        \\\"\\\"\\\"When user switches server, old tool options must be cleared.\\\"\\\"\\\"\\n        # Arrange\\n        component = await self.component_setup(component_class, default_kwargs)\\n        build_config = saved_flow_build_config.copy()\\n\\n        # Simulate previous server was set (warm cache)\\n        safe_cache_set(component._shared_component_cache, \\\"last_selected_server\\\", \\\"old_server\\\")\\n\\n        new_server_value = {\\\"name\\\": \\\"new_server\\\"}\\n\\n        # Act\\n        updated_config = await component.update_build_config(build_config, new_server_value, \\\"mcp_server\\\")\\n\\n        # Assert \u2014 options must be cleared (new server has different tools)\\n        # The backend now attempts to fetch tools immediately; since \\\"new_server\\\"\\n        # doesn't exist in the database, it will fail with an error placeholder.\\n        assert updated_config[\\\"tool\\\"][\\\"options\\\"] == []\\n        assert updated_config[\\\"tool\\\"][\\\"placeholder\\\"] in (\\n            \\\"Error on MCP Server\\\",\\n            \\\"Timeout on MCP server\\\",\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/graph/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1c9a8d121331820cca87eca07999afe805c9d63ec83ff5d2ef3b77806e8c5bcf\",\"content\":\"\\\"\\\"\\\"Tests for graph-related functionality.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/graph/edge/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/graph/graph/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/graph/graph/state/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/graph/graph/test_branch_traversal.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"943c8ce4fb2ead6f806cf1df87612331a6f524ac941628d58b3443c4d5faedaa\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.graph.vertex.base import VertexStates\\nfrom lfx.io import MessageTextInput, Output\\nfrom lfx.schema.message import Message\\n\\n\\nclass TwoOutputSource(Component):\\n    display_name = \\\"Two Output Source\\\"\\n    name = \\\"TwoOutputSource\\\"\\n\\n    inputs = [MessageTextInput(name=\\\"feedback\\\", display_name=\\\"Feedback\\\", required=False)]\\n    outputs = [\\n        Output(display_name=\\\"Item\\\", name=\\\"item\\\", method=\\\"item_output\\\", group_outputs=True),\\n        Output(display_name=\\\"Done\\\", name=\\\"done\\\", method=\\\"done_output\\\", group_outputs=True),\\n    ]\\n\\n    def item_output(self) -> Message:\\n        return Message(text=\\\"item\\\")\\n\\n    def done_output(self) -> Message:\\n        return Message(text=\\\"done\\\")\\n\\n\\nclass PassThrough(Component):\\n    display_name = \\\"Pass Through\\\"\\n    name = \\\"PassThrough\\\"\\n\\n    inputs = [MessageTextInput(name=\\\"input_value\\\", display_name=\\\"Input\\\", required=False)]\\n    outputs = [Output(display_name=\\\"Out\\\", name=\\\"out\\\", method=\\\"run\\\")]\\n\\n    def run(self) -> Message:\\n        return Message(text=str(self.input_value or \\\"\\\"))\\n\\n\\ndef test_stopping_sibling_output_does_not_protect_branch_through_feedback_cycle():\\n    \\\"\\\"\\\"A feedback edge back to the source must not make sibling outputs look shared.\\\"\\\"\\\"\\n    graph = Graph()\\n    source = TwoOutputSource(_id=\\\"source\\\")\\n    body = PassThrough(_id=\\\"body\\\")\\n    feedback = PassThrough(_id=\\\"feedback\\\")\\n    done = PassThrough(_id=\\\"done\\\")\\n\\n    for component, component_id in (\\n        (source, \\\"source\\\"),\\n        (body, \\\"body\\\"),\\n        (feedback, \\\"feedback\\\"),\\n        (done, \\\"done\\\"),\\n    ):\\n        graph.add_component(component, component_id)\\n\\n    graph.add_component_edge(\\\"source\\\", (\\\"item\\\", \\\"input_value\\\"), \\\"body\\\")\\n    graph.add_component_edge(\\\"body\\\", (\\\"out\\\", \\\"input_value\\\"), \\\"feedback\\\")\\n    graph.add_component_edge(\\\"feedback\\\", (\\\"out\\\", \\\"feedback\\\"), \\\"source\\\")\\n    graph.add_component_edge(\\\"source\\\", (\\\"done\\\", \\\"input_value\\\"), \\\"done\\\")\\n    graph.prepare()\\n\\n    graph.mark_branch(\\\"source\\\", VertexStates.INACTIVE, output_name=\\\"done\\\")\\n\\n    assert graph.get_vertex(\\\"done\\\").state == VertexStates.INACTIVE\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/graph/graph/test_smart_router_branch_isolation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"680591b1c39385573f8b9a89488a1a421fb330e1d7eb8e158067f617058630df\",\"content\":\"\\\"\\\"\\\"Graph-level regression tests for Smart Router branch isolation.\\n\\nReproduces https://github.com/langflow-ai/langflow/issues/13440: the branch that the\\nLLM does *not* select must not continue into its downstream nodes. The bug only surfaced\\nonce a branch reconverged on a shared downstream node, because ``stop()`` alone marks a\\nbranch INACTIVE for a single scheduling pass and that state is reset between passes -- a\\nre-activated branch was then picked up again through the shared node. Smart Router now also\\nrecords a *persistent* conditional exclusion (like the If-Else router).\\n\\nThese tests drive the real graph engine and the real ``process_case`` / ``default_response``\\nrouting logic; only the LLM categorization is stubbed so the assertions are deterministic.\\n\\nThe persistent-exclusion mechanism lives in ``Graph.exclude_branch_conditionally`` and is\\nshared with the If-Else router (``ConditionalRouterComponent``). The final test guards that\\nshared path with the same reconvergence scenario: it would have failed before this fix\\nbecause the merge node was excluded along with the unselected branch and never ran.\\n\\\"\\\"\\\"\\n\\nfrom lfx.components.flow_controls.conditional_router import ConditionalRouterComponent\\nfrom lfx.components.llm_operations.llm_conditional_router import SmartRouterComponent\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.io import HandleInput, MessageTextInput, Output\\nfrom lfx.schema.message import Message\\n\\n\\nclass _StubbedSmartRouter(SmartRouterComponent):\\n    \\\"\\\"\\\"Smart Router with deterministic categorization (no real LLM call).\\n\\n    The static ``outputs`` mirror exactly what ``update_outputs`` produces for the routes\\n    used in these tests (``category_{i}_result`` + optional ``default_result``), so the real\\n    routing code under test is exercised unchanged.\\n    \\\"\\\"\\\"\\n\\n    forced_category = \\\"Positive\\\"\\n\\n    outputs = [\\n        Output(display_name=\\\"Positive\\\", name=\\\"category_1_result\\\", method=\\\"process_case\\\", group_outputs=True),\\n        Output(display_name=\\\"Negative\\\", name=\\\"category_2_result\\\", method=\\\"process_case\\\", group_outputs=True),\\n    ]\\n\\n    def _get_categorization(self) -> str:\\n        self._categorization_result = self.forced_category\\n        return self.forced_category\\n\\n\\nclass _ThreeRouteSmartRouter(_StubbedSmartRouter):\\n    \\\"\\\"\\\"Three-route variant to exercise excluding more than one unselected branch.\\\"\\\"\\\"\\n\\n    outputs = [\\n        Output(display_name=\\\"Positive\\\", name=\\\"category_1_result\\\", method=\\\"process_case\\\", group_outputs=True),\\n        Output(display_name=\\\"Neutral\\\", name=\\\"category_2_result\\\", method=\\\"process_case\\\", group_outputs=True),\\n        Output(display_name=\\\"Negative\\\", name=\\\"category_3_result\\\", method=\\\"process_case\\\", group_outputs=True),\\n    ]\\n\\n\\nclass _ElseSmartRouter(_StubbedSmartRouter):\\n    \\\"\\\"\\\"Two routes plus an Else output, to exercise the ``default_result`` deactivation path.\\n\\n    Mirrors what ``update_outputs`` produces when ``enable_else_output=True``: the two\\n    ``category_{i}_result`` outputs plus a ``default_result`` output bound to\\n    ``default_response``.\\n    \\\"\\\"\\\"\\n\\n    outputs = [\\n        Output(display_name=\\\"Positive\\\", name=\\\"category_1_result\\\", method=\\\"process_case\\\", group_outputs=True),\\n        Output(display_name=\\\"Negative\\\", name=\\\"category_2_result\\\", method=\\\"process_case\\\", group_outputs=True),\\n        Output(display_name=\\\"Else\\\", name=\\\"default_result\\\", method=\\\"default_response\\\", group_outputs=True),\\n    ]\\n\\n\\nclass RecordingSink(Component):\\n    display_name = \\\"Recording Sink\\\"\\n    name = \\\"RecordingSink\\\"\\n\\n    inputs = [MessageTextInput(name=\\\"input_value\\\", display_name=\\\"Input\\\", required=False)]\\n    outputs = [Output(display_name=\\\"Out\\\", name=\\\"out\\\", method=\\\"run_sink\\\")]\\n\\n    def __init__(self, *args, **kwargs):\\n        super().__init__(*args, **kwargs)\\n        self.did_run = False\\n\\n    def run_sink(self) -> Message:\\n        self.did_run = True\\n        return Message(text=f\\\"ran:{self._id}\\\")\\n\\n\\nclass MergeSink(Component):\\n    display_name = \\\"Merge Sink\\\"\\n    name = \\\"MergeSink\\\"\\n\\n    inputs = [\\n        MessageTextInput(name=\\\"in1\\\", display_name=\\\"In1\\\", required=False),\\n        MessageTextInput(name=\\\"in2\\\", display_name=\\\"In2\\\", required=False),\\n        MessageTextInput(name=\\\"in3\\\", display_name=\\\"In3\\\", required=False),\\n    ]\\n    outputs = [Output(display_name=\\\"Out\\\", name=\\\"out\\\", method=\\\"run_merge\\\")]\\n\\n    def __init__(self, *args, **kwargs):\\n        super().__init__(*args, **kwargs)\\n        self.did_run = False\\n        self.received: dict[str, object] = {}\\n\\n    def run_merge(self) -> Message:\\n        self.did_run = True\\n        self.received = {\\n            \\\"in1\\\": getattr(self, \\\"in1\\\", None),\\n            \\\"in2\\\": getattr(self, \\\"in2\\\", None),\\n            \\\"in3\\\": getattr(self, \\\"in3\\\", None),\\n        }\\n        return Message(text=\\\"merged\\\")\\n\\n\\nclass ListMergeSink(Component):\\n    \\\"\\\"\\\"Merge node with a single ``is_list=True`` input fed by several branches.\\n\\n    Records exactly what landed in the list so a stray contribution from an excluded\\n    predecessor (the input's template default) is observable.\\n    \\\"\\\"\\\"\\n\\n    display_name = \\\"List Merge Sink\\\"\\n    name = \\\"ListMergeSink\\\"\\n\\n    inputs = [HandleInput(name=\\\"items\\\", display_name=\\\"Items\\\", input_types=[\\\"Message\\\"], is_list=True, required=False)]\\n    outputs = [Output(display_name=\\\"Out\\\", name=\\\"out\\\", method=\\\"run_merge\\\")]\\n\\n    def __init__(self, *args, **kwargs):\\n        super().__init__(*args, **kwargs)\\n        self.did_run = False\\n        self.received_items: list = []\\n\\n    def run_merge(self) -> Message:\\n        self.did_run = True\\n        self.received_items = list(self.items or [])\\n        return Message(text=\\\"merged\\\")\\n\\n\\ndef _make_router(router_cls, routes, **extra):\\n    router = router_cls(_id=\\\"router\\\")\\n    router.set(input_text=\\\"I love this product!\\\", routes=routes, **extra)\\n    return router\\n\\n\\nasync def _run(graph: Graph) -> list[str]:\\n    graph.prepare()\\n    return [result.vertex.id async for result in graph.async_start() if hasattr(result, \\\"vertex\\\")]\\n\\n\\n_TWO_ROUTES = [\\n    {\\\"route_category\\\": \\\"Positive\\\", \\\"route_description\\\": \\\"good\\\", \\\"output_value\\\": \\\"\\\"},\\n    {\\\"route_category\\\": \\\"Negative\\\", \\\"route_description\\\": \\\"bad\\\", \\\"output_value\\\": \\\"\\\"},\\n]\\n\\n\\nasync def test_unselected_branch_does_not_run_separate_leaves():\\n    \\\"\\\"\\\"Each route feeds its own leaf: only the matched route's leaf runs.\\\"\\\"\\\"\\n    router = _make_router(_StubbedSmartRouter, _TWO_ROUTES)\\n    selected, unselected = RecordingSink(_id=\\\"selected\\\"), RecordingSink(_id=\\\"unselected\\\")\\n\\n    graph = Graph()\\n    graph.add_component(router, \\\"router\\\")\\n    graph.add_component(selected, \\\"selected\\\")\\n    graph.add_component(unselected, \\\"unselected\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_1_result\\\", \\\"input_value\\\"), \\\"selected\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_2_result\\\", \\\"input_value\\\"), \\\"unselected\\\")\\n\\n    yielded = await _run(graph)\\n\\n    assert selected.did_run is True\\n    assert unselected.did_run is False\\n    assert \\\"unselected\\\" not in yielded\\n\\n\\nasync def test_unselected_branch_does_not_run_when_branches_reconverge():\\n    \\\"\\\"\\\"Regression for #13440.\\n\\n    Branches reconverging on a shared downstream node must not re-run the unselected branch.\\n    \\\"\\\"\\\"\\n    router = _make_router(_StubbedSmartRouter, _TWO_ROUTES)\\n    selected, unselected = RecordingSink(_id=\\\"selected\\\"), RecordingSink(_id=\\\"unselected\\\")\\n    merge = MergeSink(_id=\\\"merge\\\")\\n\\n    graph = Graph()\\n    graph.add_component(router, \\\"router\\\")\\n    graph.add_component(selected, \\\"selected\\\")\\n    graph.add_component(unselected, \\\"unselected\\\")\\n    graph.add_component(merge, \\\"merge\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_1_result\\\", \\\"input_value\\\"), \\\"selected\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_2_result\\\", \\\"input_value\\\"), \\\"unselected\\\")\\n    graph.add_component_edge(\\\"selected\\\", (\\\"out\\\", \\\"in1\\\"), \\\"merge\\\")\\n    graph.add_component_edge(\\\"unselected\\\", (\\\"out\\\", \\\"in2\\\"), \\\"merge\\\")\\n\\n    yielded = await _run(graph)\\n\\n    assert selected.did_run is True\\n    assert unselected.did_run is False, \\\"Unselected branch executed despite not being routed to\\\"\\n    assert merge.did_run is True, \\\"Merge node should execute from selected branch\\\"\\n    assert \\\"unselected\\\" not in yielded\\n    assert \\\"merge\\\" in yielded\\n\\n\\nasync def test_unselected_branch_does_not_run_when_outputs_share_node_directly():\\n    \\\"\\\"\\\"Regression for the exact shape in LE-1427 / Alice's report.\\n\\n    Both router outputs connect *directly* to the same downstream node (no intermediate\\n    branch nodes): ``router.category_1_result -> shared.in1`` and\\n    ``router.category_2_result -> shared.in2``. The matched output feeds the shared node;\\n    the unselected output is excluded but must not stop the shared node from running once.\\n\\n    This complements ``test_unselected_branch_does_not_run_when_branches_reconverge`` (which\\n    routes through intermediate nodes): here the router is the immediate predecessor of the\\n    merge, so the shared node is reachable from a sibling output of the *router itself*.\\n    \\\"\\\"\\\"\\n    router = _make_router(_StubbedSmartRouter, _TWO_ROUTES)\\n    shared = MergeSink(_id=\\\"shared\\\")\\n\\n    graph = Graph()\\n    graph.add_component(router, \\\"router\\\")\\n    graph.add_component(shared, \\\"shared\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_1_result\\\", \\\"in1\\\"), \\\"shared\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_2_result\\\", \\\"in2\\\"), \\\"shared\\\")\\n\\n    yielded = await _run(graph)\\n\\n    assert shared.did_run is True, \\\"Shared node should run once from the matched output\\\"\\n    assert getattr(shared.received[\\\"in1\\\"], \\\"text\\\", shared.received[\\\"in1\\\"]) == \\\"I love this product!\\\"\\n    assert getattr(shared.received[\\\"in2\\\"], \\\"text\\\", shared.received[\\\"in2\\\"]) == \\\"\\\"\\n    assert \\\"shared\\\" in yielded\\n\\n\\nasync def test_list_input_merge_excludes_unselected_branch_contribution():\\n    \\\"\\\"\\\"A shared ``is_list=True`` input must not collect the excluded branch's template default.\\n\\n    When both the selected and the unselected branch feed the same list input, the excluded\\n    predecessor is never built. Pulling a value for it would return the input's template\\n    default (an empty ``Message``/``\\\"\\\"``) and inject a stray element next to the real one.\\n    Only the selected branch should contribute.\\n    \\\"\\\"\\\"\\n    router = _make_router(_StubbedSmartRouter, _TWO_ROUTES)\\n    selected, unselected = RecordingSink(_id=\\\"selected\\\"), RecordingSink(_id=\\\"unselected\\\")\\n    merge = ListMergeSink(_id=\\\"merge\\\")\\n\\n    graph = Graph()\\n    graph.add_component(router, \\\"router\\\")\\n    graph.add_component(selected, \\\"selected\\\")\\n    graph.add_component(unselected, \\\"unselected\\\")\\n    graph.add_component(merge, \\\"merge\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_1_result\\\", \\\"input_value\\\"), \\\"selected\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_2_result\\\", \\\"input_value\\\"), \\\"unselected\\\")\\n    graph.add_component_edge(\\\"selected\\\", (\\\"out\\\", \\\"items\\\"), \\\"merge\\\")\\n    graph.add_component_edge(\\\"unselected\\\", (\\\"out\\\", \\\"items\\\"), \\\"merge\\\")\\n\\n    await _run(graph)\\n\\n    assert selected.did_run is True\\n    assert unselected.did_run is False\\n    assert merge.did_run is True\\n    # Only the selected branch contributes: exactly one element, no stray template-default ''.\\n    texts = [getattr(item, \\\"text\\\", item) for item in merge.received_items]\\n    assert texts == [\\\"ran:selected\\\"], f\\\"merge collected a stray element: {merge.received_items!r}\\\"\\n\\n\\ndef _make_if_else_router():\\n    \\\"\\\"\\\"If-Else router whose condition evaluates True, so it routes to ``true_result``.\\\"\\\"\\\"\\n    router = ConditionalRouterComponent(_id=\\\"router\\\")\\n    router.set(input_text=\\\"go\\\", match_text=\\\"go\\\", operator=\\\"equals\\\")\\n    return router\\n\\n\\nasync def test_if_else_unselected_branch_does_not_run_when_branches_reconverge():\\n    \\\"\\\"\\\"Reconvergence regression for the shared If-Else routing path.\\n\\n    ``ConditionalRouterComponent`` (If-Else) drives the same persistent\\n    ``Graph.exclude_branch_conditionally`` mechanism as Smart Router. When its branches\\n    reconverge on a shared downstream node, the unselected branch must stay excluded while\\n    the shared node still runs from the selected branch. Before the exclusion logic learned\\n    to keep a sibling output's shared descendants, the merge node was excluded too and never\\n    ran -- so this guards a real (and previously latent) If-Else behavior, not only the new\\n    Smart Router code.\\n    \\\"\\\"\\\"\\n    router = _make_if_else_router()  # condition True -> routes to ``true_result``\\n    selected, unselected = RecordingSink(_id=\\\"selected\\\"), RecordingSink(_id=\\\"unselected\\\")\\n    merge = MergeSink(_id=\\\"merge\\\")\\n\\n    graph = Graph()\\n    graph.add_component(router, \\\"router\\\")\\n    graph.add_component(selected, \\\"selected\\\")\\n    graph.add_component(unselected, \\\"unselected\\\")\\n    graph.add_component(merge, \\\"merge\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"true_result\\\", \\\"input_value\\\"), \\\"selected\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"false_result\\\", \\\"input_value\\\"), \\\"unselected\\\")\\n    graph.add_component_edge(\\\"selected\\\", (\\\"out\\\", \\\"in1\\\"), \\\"merge\\\")\\n    graph.add_component_edge(\\\"unselected\\\", (\\\"out\\\", \\\"in2\\\"), \\\"merge\\\")\\n\\n    yielded = await _run(graph)\\n\\n    assert selected.did_run is True\\n    assert unselected.did_run is False, \\\"Unselected If-Else branch executed despite the condition routing elsewhere\\\"\\n    assert merge.did_run is True, \\\"Merge node should execute from the selected branch\\\"\\n    assert \\\"unselected\\\" not in yielded\\n    assert \\\"merge\\\" in yielded\\n\\n\\nasync def test_only_matched_branch_runs_with_three_routes():\\n    \\\"\\\"\\\"With three routes, both unselected branches must be excluded (not just the last one).\\\"\\\"\\\"\\n    three_routes = [\\n        {\\\"route_category\\\": \\\"Positive\\\", \\\"route_description\\\": \\\"good\\\", \\\"output_value\\\": \\\"\\\"},\\n        {\\\"route_category\\\": \\\"Neutral\\\", \\\"route_description\\\": \\\"meh\\\", \\\"output_value\\\": \\\"\\\"},\\n        {\\\"route_category\\\": \\\"Negative\\\", \\\"route_description\\\": \\\"bad\\\", \\\"output_value\\\": \\\"\\\"},\\n    ]\\n    router = _make_router(_ThreeRouteSmartRouter, three_routes)\\";
